// ===== CHECKLEVELUP COM CAP =====
window.checkLevelUp = function(){
 if(!P.team[0]) return;
 while(P.team[0].exp>=P.team[0].maxExp){
   if(P.team[0].level>=P.levelCap){
     notif(`🔒 CAP ${P.levelCap}! Vença o ginásio!`,3500);
     P.team[0].exp=P.team[0].maxExp-1;
     break;
   }
   P.team[0].exp-=P.team[0].maxExp;
   P.team[0].level++;
   P.team[0].maxExp=Math.floor(P.team[0].maxExp*1.25);
   ensurePokeBase(P.team[0]);
   recalcPoke(P.team[0]);
   notif(`⭐ Lv.${P.team[0].level}! CAP ${P.levelCap}`,2500);
 }
 updateHUD();
}

// ===== GYM SYSTEM V2 - CAP POR REGIÃO =====
const REGION_ORDER = ["KANTO","JOHTO","HOENN","SINNOH","UNOVA","KALOS","ALOLA","GALAR","PALDEA"];
const REGION_CAPS = {KANTO:30, JOHTO:40, HOENN:50, SINNOH:60, UNOVA:70, KALOS:80, ALOLA:90, GALAR:95, PALDEA:100};

function getRegionCompleted(regionName){
  let r = GYM_DATA.find(x=>x.region===regionName);
  if(!r) return false;
  return r.gyms.every(g=>P.gymProgress.includes(g.id));
}
function isRegionUnlocked(regionName){
  let idx = REGION_ORDER.indexOf(regionName);
  if(idx===0) return true; // KANTO sempre
  let prev = REGION_ORDER[idx-1];
  return getRegionCompleted(prev);
}
function recalcLevelCap(){
  let cap = 20; // inicial
  REGION_ORDER.forEach(reg=>{
    if(getRegionCompleted(reg)) cap = REGION_CAPS[reg];
  });
  P.levelCap = Math.min(100, cap);
}

function openGyms(){renderGyms();document.getElementById('screen-gyms').style.display='flex';}
function closeGyms(){document.getElementById('screen-gyms').style.display='none';}

function renderGyms(){
 let html="";
 REGION_ORDER.forEach((regName,ri)=>{
   let reg = GYM_DATA.find(r=>r.region===regName);
   if(!reg) return;
   let completedCount = reg.gyms.filter(g=>P.gymProgress.includes(g.id)).length;
   let regionDone = completedCount===8;
   let regionUnlocked = isRegionUnlocked(regName);

   html+=`<div class="gym-region" style="border-color:${reg.color}; opacity:${regionUnlocked?'1':'0.5'}">
   <div style="color:${reg.color};font-weight:900;margin-bottom:6px;display:flex;justify-content:space-between">
     <span>${reg.icon} ${reg.region} - ${completedCount}/8 ${regionDone?'✅':''}</span>
     <span style="font-size:10px; color:${regionDone?'#0f0':'#ffd700'}">${regionDone?'CAP '+REGION_CAPS[regName]+' LIBERADO':'CAP '+REGION_CAPS[regName]+' ao completar'}</span>
   </div><div class="gym-grid">`;

   reg.gyms.forEach((gym,gi)=>{
     let done = P.gymProgress.includes(gym.id);
     let prevGymDone = gi===0? true : P.gymProgress.includes(reg.gyms[gi-1].id);
     let unlocked = regionUnlocked && prevGymDone;
     let curr = unlocked &&!done;

     html+=`<div class="gym-card ${done?'done':''} ${!unlocked?'locked':''} ${curr?'current':''}" onclick="startGymBattle('${gym.id}')">
       <div class="gym-cap-badge">CAP ${REGION_CAPS[reg.region]}</div>
       <img class="trainer" src="https://play.pokemonshowdown.com/sprites/trainers/${gym.trainerSprite}.png" onerror="this.src='https://play.pokemonshowdown.com/sprites/trainers/red.png'">
       <div style="font-size:10px;font-weight:900;color:#fff">${gym.name}</div><div style="font-size:8px;color:#aaa">${gym.city} Lv${gym.level}</div>
       <div style="font-size:7px;color:${curr?'#ffd700':done?'#0f0':'#666'}">${done?'VENCIDO':curr?'DESAFIAR':'BLOQUEADO'}</div></div>`;
   });
   html+=`</div></div>`;
 });
 document.getElementById('gyms-list').innerHTML=html;
 recalcLevelCap();
 // HUD do topo
 let nextReg = REGION_ORDER.find(r=>!getRegionCompleted(r));
 document.getElementById('gym-cap-display').textContent=P.levelCap;
 document.getElementById('gym-next-cap').textContent= nextReg? REGION_CAPS[nextReg] : 100;
}

let gymBattle=null;
function startGymBattle(gymId){
  let gym=null, regName="";
  GYM_DATA.forEach(r=>r.gyms.forEach(g=>{if(g.id===gymId){gym=g; regName=r.region}}));
  if(!gym) return;
  if(!isRegionUnlocked(regName)){notif("🔒 Termine a região anterior!");return;}
  // verifica ordem dentro da região
  let reg = GYM_DATA.find(r=>r.region===regName);
  let gi = reg.gyms.findIndex(g=>g.id===gymId);
  if(gi>0 &&!P.gymProgress.includes(reg.gyms[gi-1].id)){notif("🔒 Derrote o anterior!");return;}

  gym.region = regName;
  closeGyms();
  gymBattle={gym:gym,current:0,queue:gym.pokes.map(p=>{
    let bId=p.id; let base=calcBaseHpV14(p.lv,2,false,false,bId);
    return {id:bId,name:getPokeName(bId),level:p.lv,maxHp:base,hp:base,type:TYPE_BY_ID_ALL[bId]||"Normal"};
  })};
  startNextGymPoke();
}

function startNextGymPoke(){
 if(!gymBattle) return;
 if(gymBattle.current>=6){
   let gym=gymBattle.gym;
   if(!P.gymProgress.includes(gym.id)){
     P.gymProgress.push(gym.id);
     // verifica se completou a região toda
     if(getRegionCompleted(gym.region)){
       recalcLevelCap();
       notif(`🏆 REGIÃO ${gym.region} COMPLETA! CAP ${P.levelCap} liberado!`,5000);
       try{ spawnFloat(`CAP ${P.levelCap}!`, "#ffd700"); }catch(e){}
     } else {
       notif(`🏆 VENCEU ${gym.name}! ${gym.region} ${regProgressText(gym.region)}`,3000);
     }
     autoSave();
   }
   gymBattle=null; endBattle(true); return;
 }
 let poke=gymBattle.queue[gymBattle.current];
 let gym=gymBattle.gym;
 inBattle=true;
 document.getElementById('battle-screen').style.display='flex';
 document.getElementById('gym-progress').style.display='block';
 document.getElementById('trainer-side').style.display='block';
 document.getElementById('gym-progress').textContent=`${gym.region} - ${gym.name} | ${gymBattle.current+1}/6 | REGIÃO CAP ${REGION_CAPS[gym.region]}`;
 document.getElementById('trainer-img').src=`https://play.pokemonshowdown.com/sprites/trainers/${gym.trainerSprite}.png`;
 document.getElementById('trainer-img').onerror=function(){this.src='https://play.pokemonshowdown.com/sprites/trainers/red.png';};
 document.getElementById('trainer-name').textContent=gym.name;
 battleData={wild:poke,wildHp:poke.maxHp,wildMaxHp:poke.maxHp,state:'active'};
 document.getElementById('enemy-name-tag').textContent=poke.name+" Lv"+poke.level;
 document.getElementById('enemy-img').src=getPokeAnim(poke);
 document.getElementById('player-name-tag').textContent=P.team[0].name;
 document.getElementById('player-img').src=getPokeAnim(P.team[0]);
 document.getElementById('battle-log').textContent=`🏆 ${gym.name} mandou ${poke.name}!`;
 updateBattleHP(); loadMoveButtons();
}
function regProgressText(regionName){
  let r = GYM_DATA.find(x=>x.region===regionName);
  return `${r.gyms.filter(g=>P.gymProgress.includes(g.id)).length}/8`;
}

// ===== PATCH UNICO CORRIGIDO V34 - TIER SHINY + BOSS + CAPTURA 14% =====
window.LEGENDARY_IDS = new Set([144,145,146,150,151,243,244,245,249,250,251,377,378,379,380,381,382,383,384,385,386,480,481,482,483,484,485,486,487,488,489,490,491,492,493,638,639,640,641,642,643,644,645,646,716,717,718,785,786,787,788,789,790,791,792,800,888,889,890,898,1007,1008,1001,1002,1003,1004,1014,1015,1016,1017,1024,1025]);
window.BOSS_BAN_IDS = new Set([467,466,477,350,373,289,465,935,936,376]);

window.TIER_BY_ID_REAL = {
  144:"SS",145:"SS",146:"SS",150:"UR",151:"UR",243:"SSS",244:"SSS",245:"SSS",249:"UR",250:"UR",251:"UR",377:"SSS",378:"SSS",379:"SSS",380:"SSS",381:"SSS",382:"UR",383:"UR",384:"UR",385:"UR",386:"UR",480:"SSS",481:"SSS",482:"SSS",483:"UR",484:"UR",485:"SSS",486:"UR",487:"UR",488:"SSS",489:"UR",490:"UR",491:"UR",492:"UR",493:"UR",638:"SSS",639:"SSS",640:"SSS",641:"SSS",642:"SSS",643:"UR",644:"UR",645:"SSS",646:"SSS",647:"SSS",648:"UR",649:"UR",716:"UR",717:"UR",718:"SSS",719:"SSS",720:"UR",721:"UR",785:"SSS",786:"SSS",787:"SSS",788:"SSS",789:"SSS",790:"SSS",791:"UR",792:"UR",800:"UR",888:"UR",889:"UR",890:"UR",898:"UR",1007:"UR",1008:"UR",1001:"SSS",1002:"SSS",1003:"SSS",1004:"SSS",1014:"SSS",1015:"SSS",1016:"SSS",1017:"UR",1024:"UR",1025:"SSS",
  467:"SSS",466:"SSS",477:"SSS",350:"SSS",373:"SSS",289:"SSS",465:"SSS",935:"SSS",936:"SSS",376:"SSS"
};

window.TIER_CONFIG = { E:{color:"#888888",capMax:70,mult:1.0}, D:{color:"#44ff44",capMax:55,mult:1.2}, C:{color:"#4488ff",capMax:40,mult:1.4}, B:{color:"#aa44ff",capMax:25,mult:1.7}, A:{color:"#ffaa00",capMax:15,mult:2.1}, S:{color:"#ff4444",capMax:10,mult:2.6}, SS:{color:"#ffd700",capMax:5,mult:3.2}, SSS:{color:"#00ffff",capMax:2,mult:4.0}, UR:{color:"#ffffff",capMax:0.8,mult:5.5}, "UR+":{color:"#ffffff",capMax:0.3,mult:8.0} };
window.TIER_BY_ID = {};
Object.assign(window.TIER_BY_ID, window.TIER_BY_ID_REAL);

// BASE SEM SHINY/MEGA/BOSS
window.getBaseTier = function(id){
  if(window.TIER_BY_ID[id]) return window.TIER_BY_ID[id];
  if(window.LEGENDARY_IDS.has(id)) return "UR";
  if(window.BOSS_BAN_IDS.has(id)) return "SSS";
  if(id>=906) return "A"; if(id>=650) return "B"; if(id>=494) return "B"; if(id>=387) return "C"; if(id>=252) return "C"; if(id>=152) return "D"; return id<10?"E":"D";
};

// FINAL COM SHINY/MEGA/BOSS - AGORA ACEITA SHINY
window.getTier = function(id, shiny, mega, isBoss){
  let base = getBaseTier(id);
  if(window.LEGENDARY_IDS.has(id)) return "UR";
  if(isBoss || window.BOSS_BAN_IDS.has(id)) return "SSS";
  if(mega) return "SSS";
  if(shiny){
    if(["E","D","C","B","A"].includes(base)) return "SS";
    if(["S","SS"].includes(base)) return "SSS";
    if(base==="SSS") return "UR";
    if(base==="UR") return "UR+";
    return "SS";
  }
  return base;
};

window.getEvoStage = function(id){ const S3=[3,6,9,31,34,45,71,76,94,103,112,130,149,154,157,160,389,392,395,466,467,477,350,373,289,465,935,936,376,823,822]; const S2=[5,8,2,30,33,44,70,75,93,102,126,125,26,134,135,136,196,197,470,471,700,38,59,78,82]; if(S3.includes(id)) return 3; if(S2.includes(id)) return 2; return 1; };
window.getStageMult = function(id){ let s=getEvoStage(id); return s==3?1.8: s==2?1.4:1; };
window.calcBaseHpV14=function(lv,mult,shiny,mega,id){
  mult=mult||1;
  let tier=getTier(id||1,!!shiny,!!mega, false);
  let tierMult=TIER_CONFIG[tier]?TIER_CONFIG[tier].mult:1;
  let sm=getStageMult(id||1);
  let f=1; if(shiny&&mega) f=5; else if(mega) f=3; else if(shiny) f=1.5;
  return Math.floor((60 + lv*18) * mult * tierMult * sm * f);
};
window.calcBaseAtkV14=function(lv,mult,shiny,mega,id){
  mult=mult||1;
  let tier=getTier(id||1,!!shiny,!!mega, false);
  let tierMult=TIER_CONFIG[tier]?TIER_CONFIG[tier].mult:1;
  let sm=getStageMult(id||1);
  let f=1; if(shiny&&mega) f=5; else if(mega) f=3; else if(shiny) f=1.5;
  return Math.floor((20 + lv*7) * mult * tierMult * sm * f);
};
window.getMaxStageForTier = function(tier){
  if(tier==1) return 1; // só base
  if(tier==2) return 2; // até 2º estágio
  if(tier==3) return 2; // ainda 2º
  if(tier>=4) return 3; // final
  return 3;
}

window.getPokesForHunt = function(regionKey, tipo, tier){
  tier = parseInt(tier)||1;
  let reg = (typeof HUNT_REGIONS!=='undefined'?HUNT_REGIONS.find(r=>r.key==regionKey):null);

  // Se não achar região (ex: kanto_planta_t1 antigo), usa WILD_ZONES_GEN1 com filtro de estágio
  if(!reg){
    let k = tipo+"_t"+tier;
    let list = (typeof WILD_ZONES_GEN1!=='undefined' && WILD_ZONES_GEN1[k])? WILD_ZONES_GEN1[k] : [];
    let maxStage = getMaxStageForTier(tier);
    return list.filter(p=>!BOSS_BAN_IDS.has(p.id) &&!LEGENDARY_IDS.has(p.id) && getEvoStage(p.id) <= maxStage);
  }

  let wants = (typeof TYPE_MAP_HUNT!=='undefined' && TYPE_MAP_HUNT[tipo])?TYPE_MAP_HUNT[tipo]:[tipo];
  let maxStage = getMaxStageForTier(tier);
  let list=[];
  for(let id=reg.s; id<=reg.e; id++){
    if(window.LEGENDARY_IDS.has(id)) continue;
    if(window.BOSS_BAN_IDS.has(id)) continue;
    if(typeof getEvoStage==='function' && getEvoStage(id) > maxStage) continue; // TRAVA VENUSAUR NO T1
    let tp = window.TYPE_BY_ID_FULL?window.TYPE_BY_ID_FULL[id]:null;
    if(!tp) continue;
    if(wants.some(w=>tp.toLowerCase().includes(w.toLowerCase()))){
      list.push({id:id, name:(typeof getPokeName==='function'?getPokeName(id):'Poke '+id), type:tp});
    }
  }
  return list;
};

window.getRegionPokemonList = function(regionKey){
  let r=(typeof WORLD_REGIONS!=='undefined'?WORLD_REGIONS[regionKey]:null);
  if(!r) return [];
  let list=[];
  for(let id=r.start; id<=r.end; id++){
    if(window.LEGENDARY_IDS.has(id)) continue;
    if(window.BOSS_BAN_IDS.has(id)) continue;
    list.push(id);
  }
  return list;
};
