// ROLL COM FILTRO DE TIER - AQUI É O PULO DO GATO
function rollRarity(tier) {
    tier = tier || "E";
    const MIN = {E:0, D:0, C:0, B:0, A:3, S:4, SS:5, SSS:6, UR:7};
    let minIdx = MIN[tier]||0;
    let allowed = RARITIES.slice(minIdx);
    let total = allowed.reduce((s,r)=>s+r.chance,0);
    let r = Math.random()*total;
    let acc = 0;
    for(let i=0; i<allowed.length; i++){
        acc += allowed[i].chance;
        if(r <= acc) return allowed[i];
    }
    return allowed[0];
}

