var fastEncounter = false;
window.fastEncounter = false;
let fastLoop = null;

function toggleFastEncounter(){
    window.fastEncounter = !window.fastEncounter;
    fastEncounter = window.fastEncounter;
    const btn = document.getElementById('fastEncounterBtn');
    if(btn){
        btn.style.background = window.fastEncounter ? '#22c55e' : '#dc2626';
        btn.style.boxShadow = window.fastEncounter
          ? '0 0 10px #0008,0 0 14px #22c55eaa'
          : '0 0 10px #0008,0 0 10px #ef444466';
        btn.title = window.fastEncounter ? 'Fast Encounter: ligado' : 'Fast Encounter: desligado';
        btn.setAttribute('aria-label', btn.title);
        btn.textContent = '';
    }
    if(window.fastEncounter){
        if(!inBattle){
            const last = P?.meta?.cleanHunt?.last;
            if(!last){
                window.fastEncounter=false; fastEncounter=false;
                if(btn){btn.style.background='#dc2626';btn.title='Fast Encounter: selecione uma Hunt primeiro';btn.setAttribute('aria-label',btn.title)}
                try{notif('Selecione e entre em uma Hunt antes de ligar o Fast Encounter.',2600)}catch(e){}
                return;
            }
            const key = `psy19:${last.region}:${last.type}:${last.band}`;
            P.currentHunt = key;
            triggerWild(key);
        }
    }else{
        clearInterval(fastLoop);
    }
}
function triggerRandomAnyType(){
    let tier = (P.currentHunt || "kanto_normal_t1").split('_t')[1] || "1";
    const sameTierKeys = Object.keys(WILD_ZONES_GEN1).filter(k => k.endsWith('_t'+tier) && WILD_ZONES_GEN1[k].length>0);
    const pool = sameTierKeys.length>0? sameTierKeys : Object.keys(WILD_ZONES_GEN1).filter(k => WILD_ZONES_GEN1[k].length>0);
    const randomKey = pool[Math.floor(Math.random()*pool.length)];
    triggerWild(randomKey);
}
