async function loadFullLearnset(){
  if(Object.keys(FULL_LEARNSET).length > 500) return;
  try{
    const res = await fetch('https://cdn.jsdelivr.net/gh/Deskbot/Pokemon-Learnsets@master/output/gen9.json');
    const data = await res.json();
    FULL_LEARNSET = data;
    localStorage.setItem('fullLearnset', JSON.stringify(data));
    console.log('Learnset carregado:', Object.keys(data).length);
  }catch(e){ console.warn('Falha learnset', e); }
}
