// === SISTEMA NOVO - PEGA DO GEN9.JSON TODOS OS MOVES ATÉ LVL 100 ===
window.getFullMoveList = function(pokeId, level){
  level = level || 100;
  let engName = (typeof getShowdownName==='function'?getShowdownName(pokeId):'').toLowerCase();
  let moves = [];
  if(typeof FULL_LEARNSET!=='undefined' && FULL_LEARNSET[engName]?.learnset){
    let ls = FULL_LEARNSET[engName].learnset;
    for(let mv in ls){
      let lvls = ls[mv].map(s=>{
        let m = s.match(/L(\d+)/);
        return m? parseInt(m[1]) : 999;
      }).filter(n=>n<999);
      let minLvl = lvls.length? Math.min(...lvls) : 999;
      if(minLvl <= level){
        let pretty = mv.replace(/-/g,' ').replace(/\b\w/g,l=>l.toUpperCase());
        let db = MOVE_TYPE_DB[pretty] || {type:"Normal",power:40};
        moves.push({lvl:minLvl, name:pretty, power:db.power, type:db.type});
      }
    }
    if(moves.length > 4){
      moves.sort((a,b)=>a.lvl-b.lvl);
      return [...new Map(moves.map(m=>[m.name,m])).values()];
    }
  }
  let typeStr = (TYPE_BY_ID_ALL[pokeId] || TYPE_BY_ID_EXT[pokeId] || "Normal");
  let types = typeStr.split('/').map(t=>t.trim());
  let pool=[];
  types.forEach(tp=>{
    let list = TYPE_FALLBACK_MOVES[tp] || [];
    pool.push(...list.filter(m=>m.lvl<=level));
  });
  if(pool.length<4) pool.push(...(TYPE_FALLBACK_MOVES["Normal"]||[]).filter(m=>m.lvl<=level));
  pool.sort((a,b)=>a.lvl-b.lvl);
  let uniq=[...new Map(pool.map(m=>[m.name,m])).values()];
  return uniq.length? uniq : [{lvl:1,name:"Tackle",power:40,type:"Normal"}];
};
window.getMovesForLevel = function(pokeId, level){
  return window.getFullMoveList(pokeId, level).slice(-4);
};
window.getMovesForDex = function(pokeId){
  return window.getFullMoveList(pokeId, 100);
};

