window.ensureMoveSwapScreen=function(){
  let old=document.getElementById('screen-move-swap'); if(old) old.remove();
  let d=document.createElement('div'); d.id='screen-move-swap';
  d.style.cssText='display:none;position:fixed;inset:0;background:rgba(0,0,0,0.96);z-index:1000000;padding:12px;overflow:auto;';
  d.innerHTML=`<div style="max-width:600px;margin:0 auto;background:#151520;border:2px solid #00d0ff;border-radius:12px;padding:12px;">
  <h3 style="color:#00d0ff;text-align:center;">🔄 TROCAR MOVES - <span id="swap-name"></span></h3>
  <div id="swap-cur" style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:8px 0;"></div>
  <div style="color:#aaa;font-size:10px;text-align:center;">TODOS OS MOVES ATÉ LVL <span id="swap-lvl"></span> - SELECIONE 1 ATIVO E 1 DA LISTA</div>
  <div id="swap-pool" style="display:grid;grid-template-columns:1fr 1fr;gap:6px;max-height:50vh;overflow:auto;margin:8px 0;"></div>
  <div style="display:flex;gap:8px;"><button id="swap-confirm" style="flex:1;background:#00ff41;color:#000;padding:12px;border-radius:8px;font-weight:900;display:none;">✅ CONFIRMAR TROCA</button><button onclick="document.getElementById('screen-move-swap').style.display='none'" style="flex:1;background:#333;color:#fff;padding:12px;border-radius:8px;">FECHAR</button></div></div>`;
  document.body.appendChild(d);
};
window._swap={a:null,p:null};
window.openMoveSwap=function(idx,isBox){
  ensureMoveSwapScreen(); _swap={idx,isBox,a:null,p:null}; renderMoveSwap(); document.getElementById('screen-move-swap').style.display='block';
};
window.renderMoveSwap=function(){
  let poke=_swap.isBox?P.box[_swap.idx]:P.team[_swap.idx];
  let fullPool=window.getFullMoveList(poke.id,100);
  poke.movePool=fullPool.filter(m=>m.lvl<=poke.level);
  if(!poke.moves || poke.moves.length<1) poke.moves=window.getMovesForLevel(poke.id,poke.level);
  document.getElementById('swap-name').textContent=poke.name+" Lv"+poke.level+" "+(TYPE_BY_ID_ALL[poke.id]||"");
  document.getElementById('swap-lvl').textContent=poke.level;
  document.getElementById('swap-cur').innerHTML=poke.moves.map((m,i)=>`<button onclick="_swap.a=${i};renderMoveSwap()" style="background:${_swap.a===i?'#00ff41':'#222'};color:${_swap.a===i?'#000':'#fff'};border:2px solid ${_swap.a===i?'#00ff41':'#555'};padding:10px;border-radius:8px;"><b>${m.name}</b><br><small>${m.type} ${m.power} Lv${m.lvl}</small></button>`).join('');
  let avail=fullPool.filter(x=>!poke.moves.some(y=>y.name===x.name) && x.lvl<=poke.level);
  document.getElementById('swap-pool').innerHTML=avail.map(m=>`<button onclick="_swap.p='${m.name}';renderMoveSwap()" style="background:${_swap.p===m.name?'#ffd700':'#1a1a2e'};color:${_swap.p===m.name?'#000':'#fff'};border:1px solid #334;padding:8px;border-radius:6px;text-align:left;"><b>${m.name}</b><br><small>${m.type} Lv${m.lvl} PWR${m.power}</small></button>`).join('')||"<div style='color:#666;grid-column:1/-1;text-align:center;'>Todos equipados! Upe para mais</div>";
  let btn=document.getElementById('swap-confirm');
  btn.style.display=(_swap.a!==null && _swap.p!==null)?'block':'none';
  btn.onclick=()=>{
    let nm=fullPool.find(x=>x.name===_swap.p);
    if(!nm) return;
    poke.moves[_swap.a]=nm;
    poke.moves=[...poke.moves];
    _swap.a=null; _swap.p=null;
    if(typeof autoSave==='function') autoSave();
    if(typeof loadMoveButtons==='function') loadMoveButtons();
    if(typeof renderTeam==='function') renderTeam();
    if(typeof notif==='function') notif("✅ Move salvo: "+nm.name);
    renderMoveSwap();
  };
};
