// ===== SAVE V2 - NÃO APAGA NUNCA MAIS =====
const SAVE_KEY = 'psyWorldSave_v2';
const SAVE_BACKUP_KEY = 'psyWorldSave_backup';

function safeStringify(obj){ try{ return JSON.stringify(obj); }catch(e){ return null; } }

function migratePoke(p){
    if(!p) return;
    if(typeof p.resets==='undefined') p.resets = 0;
    if(typeof p.boost==='undefined') p.boost = 0;
    if(typeof p.level==='undefined') p.level = 1;
    if(!p.rarity) p.rarity = {n:"Lixo", color:"#888", mult:1};
    try{
        if(typeof ensurePokeBase==='function') ensurePokeBase(p);
        if(typeof recalcPoke==='function'){
            let ratio = p.maxHp? (p.hp / p.maxHp) : 1;
            recalcPoke(p);
            if(ratio < 0.99) p.hp = Math.floor(p.maxHp * ratio);
        }
    }catch(e){}
}

function autoSave() {
    try{
        const saveData = { v:2, player: P, map: { x: P.x, y: P.y, px: P.px, py: P.py }, time: Date.now() };
        const str = safeStringify(saveData); if(!str) return;
        localStorage.setItem(SAVE_KEY, str);
        localStorage.setItem(SAVE_BACKUP_KEY, str);
        localStorage.setItem('psyWorldSave', str); // compat
    }catch(e){ console.warn(e); }
}

function autoLoad() {
    try{
        let raw = localStorage.getItem(SAVE_KEY) || localStorage.getItem(SAVE_BACKUP_KEY) || localStorage.getItem('psyWorldSave');
        if(!raw) return false;
        const data = JSON.parse(raw);
        const pd = data.player || data;
        if(!pd.team || (pd.team.length===0 && pd.box?.length===0)) return false;

        P.name = pd.name || P.name;
        P.gold = pd.gold?? P.gold;
        P.team = pd.team || [];
        P.box = pd.box || [];
        P.inventory = pd.inventory || P.inventory;
        P.levelCap = pd.levelCap?? P.levelCap;
        P.gymProgress = pd.gymProgress || [];
        P.trainerLevel = pd.trainerLevel || 1;
        P.trainerExp = pd.trainerExp || 0;
        P.trainerMaxExp = pd.trainerMaxExp || 100;
        P.trainerPoints = pd.trainerPoints || 0;
        P.trainerBuffs = pd.trainerBuffs || P.trainerBuffs;
        P.worldBuffs = pd.worldBuffs || P.worldBuffs;
        P.currentHunt = pd.currentHunt || P.currentHunt;

        P.x = data.map?.x?? 25; P.y = data.map?.y?? 25;
        P.px = data.map?.px?? P.x*32; P.py = data.map?.py?? P.y*32;

        P.team.forEach(migratePoke);
        P.box.forEach(migratePoke);
        if(P.team[0]){
            P.pokemon = P.team[0];
            P.hp = P.team[0].hp; P.maxHp = P.team[0].maxHp;
        }
        return true;
    }catch(e){
        console.warn("autoLoad erro", e);
        return false;
    }
}

function saveGame() {
    if(confirm(`💾 SALVAR? Team: ${P.team.length} Box: ${P.box.length}`)){
        autoSave(); notif(`💾 Salvo! Team ${P.team.length}`, 1500);
    }
}
function loadGame() {
    if(confirm("📂 CARREGAR save?")){
        const raw = localStorage.getItem(SAVE_KEY) || localStorage.getItem('psyWorldSave');
        if(!raw){ notif('❌ Nenhum save!'); return; }
        if(autoLoad()){
            updateHUD(); renderTeam();
            if(P.team[0]){ P.team[0].moves = getMovesForLevel(P.team[0].id, P.team[0].level); loadMoveButtons(); }
            document.getElementById('menu').style.display = 'none';
            notif(`✅ Carregado! Team: ${P.team.length}`, 2000);
        }
    }
}
function downloadSave() {
    if(!confirm(`⬇ BAIXAR SAVE v2? Team: ${P.team.length}`)) return;
    autoSave();
    const raw = localStorage.getItem(SAVE_KEY);
    const blob = new Blob([raw], {type: "application/json"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url;
    a.download = `${P.name||'player'}_PSYWORLD_v2_${P.team.length}p.psy`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);
    notif('✅.psy v2 baixado!', 2000);
}
function uploadSave(event) {
    const file = event.target.files[0]; if(!file) return;
    if(!confirm("⬆ Carregar esse.psy? Vai substituir o atual!")){ event.target.value=''; return; }
    const reader = new FileReader();
    reader.onload = e=>{
        try{
            const data = JSON.parse(e.target.result);
            const str = JSON.stringify(data);
            localStorage.setItem(SAVE_KEY, str);
            localStorage.setItem(SAVE_BACKUP_KEY, str);
            localStorage.setItem('psyWorldSave', str);
            autoLoad(); updateHUD(); renderTeam(); if(P.team[0]) loadMoveButtons();
            document.getElementById('menu').style.display='none';
            notif(`✅ Arquivo OK! Team ${P.team.length}`, 3000);
        }catch(err){ notif('❌.psy inválido!'); }
    };
    reader.readAsText(file); event.target.value='';
}
function uploadSaveLogin(event){
    const file = event.target.files[0]; if(!file) return;
    const reader = new FileReader();
    reader.onload = e=>{
        try{
            const data = JSON.parse(e.target.result);
            const str = JSON.stringify(data);
            localStorage.setItem(SAVE_KEY, str);
            localStorage.setItem(SAVE_BACKUP_KEY, str);
            localStorage.setItem('psyWorldSave', str);
            if(autoLoad()){
                document.getElementById('screen-login').style.display='none';
                document.getElementById('game-wrap').style.display='block';
                updateHUD(); initEngine(); loadMoveButtons();
                notif(`✅ Bem vindo ${P.name}!`, 3000);
            }
        }catch(err){ notif('❌ Arquivo inválido!'); }
    };
    reader.readAsText(file); event.target.value='';
}
function loadOnLogin(){
    if(autoLoad()){
        document.getElementById('screen-login').style.display='none';
        document.getElementById('game-wrap').style.display='block';
        updateHUD(); initEngine(); loadMoveButtons();
        notif(`✅ Bem vindo ${P.name}! Team ${P.team.length}`, 3000);
    }else notif('❌ Nenhum save v2 encontrado!');
}
