// CARREGAR SAVE DA TELA DE LOGIN
function loadOnLogin() {
    const saveData = localStorage.getItem('psyWorldSave');
    if(!saveData) { notif('❌ Nenhum save encontrado!'); return; }

    if(autoLoad()){
        document.getElementById('screen-login').style.display = 'none';
        document.getElementById('game-wrap').style.display = 'block';
        updateHUD();
        initEngine();
        loadMoveButtons();
        notif(`✅ Bem vindo de volta, ${P.name}!`, 3000);
    }
}

// CARREGAR ARQUIVO DA TELA DE LOGIN
function uploadSaveLogin(event) {
    const file = event.target.files[0];
    if(!file) return;

    const reader = new FileReader();
    reader.onload = function(e) {
        try {
            const data = JSON.parse(e.target.result);
            Object.assign(P, data.player);
            P.x = data.map.x; P.y = data.map.y;
            P.px = data.map.px; P.py = data.map.py;

            if(P.team[0]) { // seta o poke
                P.team[0].moves = getMovesForLevel(P.team[0].id, P.team[0].level);
                P.pokemon = P.team[0];
                P.hp = P.pokemon.hp;
                P.maxHp = P.pokemon.maxHp;
            }

            document.getElementById('screen-login').style.display = 'none';
            document.getElementById('game-wrap').style.display = 'block';
            updateHUD();
            initEngine();
            loadMoveButtons();
            notif(`✅ Save do arquivo carregado!`, 2000);
        } catch(err) {
            notif('❌ Arquivo inválido!');
        }
    };
    reader.readAsText(file);
    event.target.value = '';
}
function buildStarterScreen() {
    const container = document.getElementById('starter-list');
    container.innerHTML = '';
    GENS.forEach(gen => {
        const sec = document.createElement('div');
        sec.className = 'gen-section';
        sec.innerHTML = `<div class="gen-label">${gen.label}</div>`;
        const row = document.createElement('div');
        row.className = 'starter-row';
        gen.starters.forEach(s => {
            const card = document.createElement('div');
            card.className = 's-card';
            card.id = 'sc' + s.id;
            card.innerHTML = `
                <img src="${getSpriteUrl(s.id)}"
                     onerror="this.onerror=null; this.src='https://play.pokemonshowdown.com/sprites/ani/${getShowdownName(s.id)}.gif'">
                <span class="sname">${s.name}</span>
                <span class="stype">${s.type}</span>`;
            card.onclick = () => selectPoke(s, card);
            row.appendChild(card);
        });
        sec.appendChild(row);
        container.appendChild(sec);
    });
}

function selectPoke(s, el) {
    document.querySelectorAll('.s-card').forEach(c => c.classList.remove('sel'));
    el.classList.add('sel');
    chosenPoke = s;
    document.getElementById('btn-confirm').style.display = 'inline-block';
    document.getElementById('chosen-label').textContent = `Selecionado: ${s.name}`;
}

function confirmStarter() {
    if(!chosenPoke) { notif('Escolha um Pokémon primeiro!'); return; }

    // 1. Se já tem save v2/v1/backup, NUNCA apaga. Só entra.
    if(autoLoad() && P.team && P.team.length > 0){
        document.getElementById('screen-starter').style.display = 'none';
        document.getElementById('game-wrap').style.display = 'block';
        updateHUD();
        initEngine();
        loadMoveButtons();
        notif(`✅ Bem vindo de volta, ${P.name}! Team: ${P.team.length}`, 3000);
        return;
    }

    // 2. Só cria starter se REALMENTE não tem nada
    const rarity = rollRarity();
    const novoPoke = {
      ...chosenPoke,
        rarity: rarity,
        premier: false,
        level: 1,
        exp: 0,
        maxExp: 100,
        moves: getMovesForLevel(chosenPoke.id, 1),
        boost: 0,
        resets: 0
    };
    // usa seu sistema novo, não o calculo manual
    if(typeof ensurePokeBase === 'function') ensurePokeBase(novoPoke);
    if(typeof recalcPoke === 'function') recalcPoke(novoPoke);
    else {
        novoPoke.maxHp = Math.floor(50 + novoPoke.level * 5 + (rarity.bonus||0));
        novoPoke.hp = novoPoke.maxHp;
    }

    document.getElementById('screen-starter').style.display = 'none';

    P.team = [novoPoke];
    P.box = P.box || []; // NÃO faz P.box = [] se já tinha backup
    P.pokemon = P.team[0];
    P.maxHp = P.pokemon.maxHp;
    P.hp = P.pokemon.hp;

    // ⭐ VIP DE BOAS-VINDAS — somente para uma conta realmente nova.
    // Não é aplicado em saves já existentes e não reduz um VIP maior já ativo.
    P.meta = P.meta || {};
    if(!P.meta.welcomeVip3DaysGranted){
        const welcomeVipMs = 3 * 24 * 60 * 60 * 1000;
        P.meta.vipUntil = Math.max(Number(P.meta.vipUntil || 0), Date.now()) + welcomeVipMs;
        P.meta.welcomeVip3DaysGranted = true;
        P.meta.welcomeVipGrantedAt = Date.now();
    }

    document.getElementById('game-wrap').style.display = 'block';
    updateHUD();
    initEngine();
    autoSave(); // já salva em v2 + backup + v1
    notif(`${P.name} escolheu ${chosenPoke.name}! 🎉 ⭐ VIP de boas-vindas ativado por 3 dias!`, 4500);
}
