function openShop()  { document.getElementById('screen-shop').style.display = 'flex'; }
function closeShop() { document.getElementById('screen-shop').style.display = 'none'; }

function buyItem(name, price) {
    if(P.gold < price) { notif('❌ Gold insuficiente!'); return; }
    P.gold -= price;
    P.inventory[name] = (P.inventory[name] || 0) + 1;
    updateHUD(); autoSave();
    notif(`✅ ${name} comprada! (${P.inventory[name]} no estoque)`);
}

/* ══════════   ═══════════════════
   HUD
══════════════════════════════ */
function updateHUD() {
    if(!P.team[0]) return; // <- PROTEÇÃO PRA NÃO QUEBRAR

    P.pokemon = P.team[0]; // <- SEMPRE pega quem tá na frente

    document.getElementById('hud-name').textContent = P.name;
    document.getElementById('hud-lv').textContent = P.pokemon.level;

    P.hp = P.pokemon.hp; // <- SINCRONIZA
    P.maxHp = P.pokemon.maxHp; // <- SINCRONIZA

    document.getElementById('hp-fill').style.width = Math.max(0,(P.hp/P.maxHp*100))+'%';
    document.getElementById('hp-txt').textContent = P.hp+'/'+P.maxHp;

    document.getElementById('exp-fill').style.width = (P.pokemon.exp/P.pokemon.maxExp*100)+'%';
    document.getElementById('exp-txt').textContent = P.pokemon.exp+'/'+P.pokemon.maxExp;

    document.getElementById('hud-gold').textContent = P.gold;
    const pct = P.hp / P.maxHp;
    const fill = document.getElementById('hp-fill');
    fill.style.background = pct > 0.5? '#00ff41' : pct > 0.25? '#ffaa00' : '#ff2222';
}
/* ══════════════════════════════
   MAPA
══════════════════════════════ */
const TILE = 55;
const MAP_W = 60, MAP_H = 60;
const map = [];

for(let y = 0; y < MAP_H; y++) {
    map[y] = [];
    for(let x = 0; x < MAP_W; x++) {
        // tudo areia, sem cruz, sem borda
        map[y][x] = 1;
    }
}
const BUILDINGS = []; // REMOVIDO - agora é só pelos botões

const SOLID = new Set();
for(let y = 0; y < MAP_H; y++)
    for(let x = 0; x < MAP_W; x++)
        if(map[y][x] === 2 || map[y][x] === 4) SOLID.add(x+','+y);

BUILDINGS.forEach(b => {
    for(let dy = 0; dy < b.h; dy++)
        for(let dx = 0; dx < b.w; dx++)
            if(dy < b.h - 1) SOLID.add((b.x+dx)+','+(b.y+dy));
});

/* NPCs */
const CITY_POKES = []; // V32: removidos da cidade para reduzir lag
function updateNPCSprites() {
    if(inBattle) return;
    CITY_POKES.forEach((n, i) => {
        // FIX: usa o ÍNDICE i pra não repetir ID
        let idUnico = n.id + '-' + i;
        let container = document.getElementById('npc-container-' + idUnico);
        if(!container) {
            container = document.createElement('div');
            container.id = 'npc-container-' + idUnico;
            container.style.position = 'absolute'; 
            container.style.textAlign = 'center'; 
            container.style.pointerEvents = 'none'; 
            container.style.zIndex = '10';
            container.style.display = 'flex';
            container.style.flexDirection = 'column';
            container.style.alignItems = 'center';

            const label = document.createElement('div'); 
            label.textContent = (n.shiny ? '✨ Shiny ' : '') + n.name; 
            label.style.background = 'rgba(0,0,0,0.7)'; 
            label.style.color = n.shiny ? '#ffd700' : '#fff'; 
            label.style.fontSize = '10px'; 
            label.style.padding = '2px 5px'; 
            label.style.borderRadius = '4px'; 
            label.style.marginBottom = '2px';

            const img = document.createElement('img'); 
            img.style.imageRendering = 'pixelated'; 
            img.style.width = '70px';
            // usa o animado certo do Showdown
            let sdName = (typeof getShowdownName === 'function' ? getShowdownName(n.id) : 'psyduck');
            let folder = n.shiny ? 'ani-shiny' : 'ani';
            img.src = `https://play.pokemonshowdown.com/sprites/${folder}/${sdName}.gif`;

            container.appendChild(label); 
            container.appendChild(img);
            document.getElementById('game-wrap').appendChild(container);
        }
        const camX = P.px - canvas.width / 2; 
        const camY = P.py - canvas.height / 2;
        const sx = n.x * TILE - camX; 
        const sy = n.y * TILE - camY;
        container.style.left = (sx - 8) + 'px'; 
        container.style.top = (sy - 20) + 'px';
        let fora = (sx < -80 || sx > canvas.width+20 || sy < -80 || sy > canvas.height+20);
        container.style.display = fora ? 'none' : 'flex';
    });
}

