// ===== HUNTS - 648 ZONAS - 9 REGIOES x 18 TIPOS x 4 TIERS - FIX DEFINITIVO =====
const HUNT_TYPES = ["normal","fogo","agua","planta","eletrico","gelo","lutador","venenoso","terra","voador","psiquico","inseto","pedra","fantasma","dragao","aco","fada","dark"];
const HUNT_COLORS = {normal:"#aaa",fogo:"#ff4444",agua:"#4488ff",planta:"#44ff88",eletrico:"#ffeb00",gelo:"#00e5ff",lutador:"#ff8800",venenoso:"#aa44ff",terra:"#aa7744",voador:"#88aaff",psiquico:"#ff44aa",inseto:"#88cc00",pedra:"#aa8866",fantasma:"#6655aa",dragao:"#4444ff",aco:"#888888",fada:"#ff88cc",dark:"#444444"};
const HUNT_REGIONS = [
{key:"kanto",name:"KANTO",s:1,e:151,color:"#ff4444"},
{key:"johto",name:"JOHTO",s:152,e:251,color:"#ffd700"},
{key:"hoenn",name:"HOENN",s:252,e:386,color:"#00ff88"},
{key:"sinnoh",name:"SINNOH",s:387,e:493,color:"#aa88ff"},
{key:"unova",name:"UNOVA",s:494,e:649,color:"#ffffff"},
{key:"kalos",name:"KALOS",s:650,e:721,color:"#ff88cc"},
{key:"alola",name:"ALOLA",s:722,e:809,color:"#ffaa00"},
{key:"galar",name:"GALAR",s:810,e:898,color:"#88ccff"},
{key:"paldea",name:"PALDEA",s:906,e:1025,color:"#ff6600"}
];
function getPokesForHunt(regionKey,tipo,tier){
  let reg=HUNT_REGIONS.find(r=>r.key==regionKey);
  if(!reg){
    let k = tipo+"_t"+tier;
    return (WILD_ZONES_GEN1[k]||[]).filter(p=>!BOSS_BAN_IDS.has(p.id) &&!LEGENDARY_IDS.has(p.id));
  }
  let list=[];
  let typeMap={normal:["Normal"],fogo:["Fogo"],agua:["Agua"],planta:["Planta"],eletrico:["Eletrico"],gelo:["Gelo"],lutador:["Lutador"],venenoso:["Venenoso"],terra:["Terra"],voador:["Voador"],psiquico:["Psiquico"],inseto:["Inseto"],pedra:["Pedra"],fantasma:["Fantasma"],dragao:["Dragao"],aco:["Aco"],fada:["Fada"],dark:["Noturno","Dark"]};
  let wants=typeMap[tipo]||[tipo];
  for(let id=reg.s;id<=reg.e;id++){
    if(typeof LEGENDARY_IDS!=='undefined' && LEGENDARY_IDS.has(id)) continue;
    if(typeof BOSS_BAN_IDS!=='undefined' && BOSS_BAN_IDS.has(id)) continue;
    let tp=window.TYPE_BY_ID_FULL[id]||TYPE_BY_ID_ALL[id]||"";
    if(!tp) continue;
    if(wants.some(w=>tp.toLowerCase().includes(w.toLowerCase()))){
      let nm=(typeof getPokeName==='function'?getPokeName(id):"Poke "+id);
      list.push({id:id,name:nm,type:tp});
    }
  }
  if(!list.length){
    let k = tipo+"_t"+tier;
    if(WILD_ZONES_GEN1[k] && WILD_ZONES_GEN1[k].length>0){
      return WILD_ZONES_GEN1[k].filter(p=>{
        if(typeof BOSS_BAN_IDS!=='undefined' && BOSS_BAN_IDS.has(p.id)) return false;
        if(typeof LEGENDARY_IDS!=='undefined' && LEGENDARY_IDS.has(p.id)) return false;
        return true;
      });
    }
  }
  return list;
}
function openHunts(){
const list=document.getElementById('hunt-list');
list.innerHTML='';
list.className='dungeon-grid-mini';
list.style.gridTemplateColumns='repeat(4,1fr)';
HUNT_REGIONS.forEach(function(reg){
HUNT_TYPES.forEach(function(tipo){
for(let tier=1;tier<=4;tier++){
let key=reg.key+"_"+tipo+"_t"+tier;
let pokes=getPokesForHunt(reg.key,tipo,tier);
if(!pokes||pokes.length==0) continue;
let lvl=tier==1?"1-10":tier==2?"10-20":tier==3?"20-30":"40-60";
let cor=HUNT_COLORS[tipo]||"#fff";
let preview=pokes.slice(0,4).map(function(p){
let sd=getShowdownName(p.id);
return '<img src="https://play.pokemonshowdown.com/sprites/ani/'+sd+'.gif" style="width:24px;height:24px;image-rendering:pixelated" onerror="this.onerror=null; this.src=\'https://play.pokemonshowdown.com/sprites/ani/'+sd+'.gif\'">';
}).join('');
let div=document.createElement('div');
div.className='dungeon-card-mini';
div.style.background='#1a1a2e';
div.style.border='2px solid '+reg.color;
div.style.borderRadius='10px';
div.style.padding='5px 3px';
div.style.textAlign='center';
div.style.cursor='pointer';
div.innerHTML='<div style="color:'+reg.color+';font-size:7px;font-weight:900">'+reg.name+'</div><div style="display:flex;flex-wrap:wrap;justify-content:center;gap:1px;min-height:48px;align-content:center">'+preview+'</div><div class="shiny-name" style="font-size:7px;line-height:1">'+tipo.toUpperCase()+' T'+tier+'</div><div style="color:#ffd700;font-size:6px">Lv '+lvl+'</div><div style="color:#888;font-size:6px">'+pokes.length+' pokes</div><div style="margin-top:3px;background:'+cor+';color:#000;border-radius:3px;padding:2px;font-size:7px;font-weight:900">ENTRAR</div>';
div.onclick=function(){enterHunt(key);};
list.appendChild(div);
}
});
});
document.getElementById('screen-hunts').style.display='flex';
}
function closeHunts(){document.getElementById('screen-hunts').style.display='none';}
function enterHunt(key){
closeHunts();
document.getElementById('menu').style.display='none';
P.currentHunt=key;
notif('📍 '+key.toUpperCase(),2000);
triggerWild(key);
}
function triggerWild(pool){
if(inBattle||!P.team[0]) return;
let key=pool;
let regKey, tipo, tierNum;
if(key.includes('_t')){
  let parts=key.split('_');
  if(parts.length>=3){
    regKey=parts[0];
    tipo=parts[1];
    tierNum=parseInt(parts[2].replace('t',''))||1;
  }else{
    regKey="kanto";
    tipo=parts[0];
    tierNum=parseInt(parts[1].replace('t',''))||1;
  }
}else{
  regKey="kanto";
  tipo=key.split('_t')[0];
  tierNum=1;
}
let list=getPokesForHunt(regKey,tipo,tierNum);
if(typeof BOSS_BAN_IDS!=='undefined') list = list.filter(p=>!BOSS_BAN_IDS.has(p.id));
if(!list||list.length==0){
  notif(`❌ ${regKey.toUpperCase()} sem ${tipo.toUpperCase()} T${tierNum}`,2500);
  return;
}
const base=list[Math.floor(Math.random()*list.length)];
let tierLetter = getTier(base.id); // <-- E,D,C,B,A,S,SS,SSS,UR
const rarity=typeof rollRarity==='function'?rollRarity(tierLetter):{n:"Comum",bonus:0,mult:1};
let realType=base.type||TYPE_BY_ID_ALL[base.id]||"Normal";
let tier=tierNum; // esse tierNum é o da HUNT 1-4, mantém
let min=1,max=10; if(tier==2){min=10;max=20;}else if(tier==3){min=20;max=35;}else if(tier==4){min=40;max=60;}else if(tier==5){min=60;max=80;}
const lvl=Math.floor(Math.random()*(max-min+1))+min;
const maxHp=Math.floor(65+lvl*8+(rarity.bonus||0));
if(tipo==='metal') tipo='aco';
const BG_FALLBACK={planta:'#1a3a1a',fogo:'#3a1a1a',agua:'#1a2a3a',eletrico:'#3a3a1a',gelo:'#1a3a3a',normal:'#2a2a2a',venenoso:'#2a1a3a',terra:'#3a2a1a',voador:'#2a2a3a',psiquico:'#3a1a2a',inseto:'#2a3a1a',pedra:'#3a2e1a',fantasma:'#1a1a2e',dragao:'#1a1a3a',aco:'#2a2a2e',fada:'#3a1a2e',lutador:'#3a1a1a',dark:'#111'};
let hud=document.querySelector('.battle-hud');
if(hud){
hud.style.backgroundImage=`url(Hunts/${tipo}.png)`;
hud.style.backgroundColor=BG_FALLBACK[tipo]||'#1a3a1a';
hud.style.backgroundSize='cover';
hud.style.backgroundPosition='center';
}
startBattle({id:base.id,name:base.name,type:realType,shiny:Math.random()<0.0005,rarity,tier:tierLetter,level:lvl,maxHp:maxHp,hp:maxHp});
}
