function getPokeName(id){ return ALL_POKE_NAMES[id] || `Pokemon ${id}`; }

function calcHp(base, p){
  // Premier NÃO dá status - só aura
  let isShiny = p.shiny || false;
  let isMega = p.isMega || p.mega || false;
  let m = getFormMult(isShiny, isMega);
  return Math.floor(base * m);
}


function tryEvolve(pokemon, stoneName){
    let evo = null;
    if(SPECIAL_EVOLUTIONS[pokemon.id] && SPECIAL_EVOLUTIONS[pokemon.id][stoneName]) evo = SPECIAL_EVOLUTIONS[pokemon.id][stoneName];
    else if(EVOLUTION_MAP[pokemon.id] && EVOLUTION_MAP[pokemon.id].stone === stoneName) evo = EVOLUTION_MAP[pokemon.id];
    if(!evo){ notif(`❌ ${pokemon.name} não evolui com ${stoneName}!`); return false; }
    let qtdNeed = evo.qtd || 10;
    if(pokemon.level < evo.minLevel){ notif(`🔒 Precisa Lv.${evo.minLevel} (ta Lv.${pokemon.level})`); return false; }
    if((P.inventory[stoneName]||0) < qtdNeed){ notif(`❌ Precisa ${qtdNeed}x ${stoneName} (tem ${P.inventory[stoneName]||0})`); return false; }

    let oldName = pokemon.name;
    let oldHp = pokemon.maxHp;
    let oldAtk = pokemon.atk;
    let oldRarity = pokemon.rarity;
    let oldShiny = pokemon.shiny;
    let oldResets = pokemon.resets||0;
    let oldBoost = pokemon.boost||0;
    let oldEvoMult = pokemon.evoMult||1;

    const goingToSecond =!!EVOLUTION_MAP[evo.to];
    const multStage = goingToSecond? 1.4 : 1.6;

    P.inventory[stoneName] -= qtdNeed;
    if(P.inventory[stoneName]<=0) delete P.inventory[stoneName];

    pokemon.id = evo.to;
    pokemon.name = getPokeName(evo.to);
    pokemon.type = TYPE_BY_ID_ALL[evo.to] || TYPE_BY_ID_FULL[evo.to] || pokemon.type;
    pokemon.rarity = oldRarity;
    pokemon.shiny = oldShiny;
    pokemon.resets = oldResets;
    pokemon.boost = oldBoost;
    pokemon.evoMult = oldEvoMult * multStage;
    pokemon.isMega = false;

    pokemon.level = 1;
    pokemon.exp = 0;
    pokemon.maxExp = 100;
    pokemon.moves = getMovesForLevel(pokemon.id, 1);
    pokemon.movePool = getFullMoveList(pokemon.id, 1);

    recalcPoke(pokemon);

    // SE FICOU MAIS FRACO QUE ANTES (porque Lv36 -> Lv1), força +5%
    if(pokemon.maxHp < oldHp || pokemon.atk < oldAtk){
        let baseHp1 = calcBaseHpV14(1, oldRarity?.mult||1, oldShiny, false, pokemon.id);
        let baseAtk1 = calcBaseAtkV14(1, oldRarity?.mult||1, oldShiny, false, pokemon.id);
        let boostMult = 1 + oldBoost/100;
        let resetMult = 1 + oldResets*0.05;
        let hpBuff = 1+getTotalBuff('hp')/100;
        let dmgBuff = 1+getTotalBuff('dmg')/100;
        let needHp = (oldHp * 1.05) / (baseHp1 * boostMult * resetMult * hpBuff);
        let needAtk = (oldAtk * 1.05) / (baseAtk1 * boostMult * resetMult * dmgBuff);
        pokemon.evoMult = Math.max(pokemon.evoMult, needHp, needAtk);
        recalcPoke(pokemon);
    }

    spawnFloat(`✨ ${oldName} -> ${pokemon.name} EVO x${pokemon.evoMult.toFixed(2)}`, "#ffd700");
    notif(`✨ ${oldName} -> ${pokemon.name} Lv.1! ${oldHp}HP/${oldAtk}ATK -> ${pokemon.maxHp}HP/${pokemon.atk}ATK +${goingToSecond?40:60}%`,4000);
    autoSave(); updateHUD(); closeBag(); renderTeam();
    return true;
}

function checkEvoStone(stoneName){
    let found = [];
    [...P.team,...P.box].forEach((p, globalIdx)=>{
        let isTeam = globalIdx < P.team.length;
        let req = EVOLUTION_MAP[p.id];
        if(req && req.stone===stoneName) found.push({p, isTeam, idx: isTeam? globalIdx : globalIdx - P.team.length, req});
        let sp = SPECIAL_EVOLUTIONS[p.id]?.[stoneName];
        if(sp) found.push({p, isTeam, idx: isTeam? globalIdx : globalIdx - P.team.length, req:sp});
    });

    if(found.length===0){ notif(`❌ Ninguém evolui com ${stoneName}`); return; }

    const list=document.getElementById('bag-list');
    document.getElementById('bag-title').innerText=`💎 ${stoneName} - ESCOLHA QUEM EVOLUI`;

    let html="";
    found.forEach(f=>{
        let tem=P.inventory[stoneName]||0;
        let pode=tem>=f.req.qtd && f.p.level>=f.req.minLevel;
        html+=`<div style="background:#1a1a2e; border:2px solid ${pode?'#7c3aed':'#444'}; border-radius:12px; padding:8px; text-align:center;">
          <img src="${getPokeAnim(f.p)}" style="width:50px;height:50px;">
          <div style="color:#fff;font-size:10px;font-weight:900;">${f.p.name} Lv.${f.p.level} → ${getPokeName(f.req.to)}</div>
          <div style="color:${tem>=f.req.qtd?'#0f0':'#f00'};font-size:9px;">${f.req.qtd}x (tem ${tem}) | Lv.${f.req.minLevel}</div>
          <div style="font-size:8px;color:#888;">${f.isTeam?'TIME':'BOX'}</div>
          <button onclick="tryEvolve(${f.isTeam?'P.team':'P.box'}[${f.idx}],'${stoneName}')" style="width:100%;margin-top:5px;background:${pode?'#7c3aed':'#333'};color:#fff;border:none;padding:6px;border-radius:6px;font-weight:900;" ${!pode?'disabled':''}>${pode?'✨ EVOLUIR':'🔒'}</button>
        </div>`;
    });
    html+=`<div style="grid-column:1/-1;"><button onclick="openBag()" style="width:100%;background:#333;color:#fff;border:none;padding:10px;border-radius:8px;margin-top:8px;">⬅ VOLTAR</button></div>`;
    list.innerHTML=html;
}

function renderTeam(){
    const tl=document.getElementById('team-list');
    const bl=document.getElementById('box-list');
    const search = (document.getElementById('box-search')?.value || '').toLowerCase().trim();
    const bc = document.getElementById('box-count');
    if(bc) bc.textContent = P.box.length;

    let ht="";
    for(let i=0;i<6;i++){
        let p=P.team[i];
        if(p){
            ensurePokeBase(p);
            let tier = typeof getTier==='function'? (p.forceTier||p.tier||getTier(p.id, p.shiny, p.isMega, false)) : 'E';
            let nameShow = p.shiny? `<span class="shiny-name">${p.name}</span>` : p.name;
            ht+=`<div onclick="openPokeDetail(${i}, false)" style="display:flex; align-items:center; justify-content:space-between; background:#1a1a2e; border:${i==0?'2px solid #00ff41':'2px solid #334'}; border-radius:10px; padding:6px; margin:4px 0; cursor:pointer; position:relative;" class="aura-${tier}">
              <span class="tier-badge ${tier}">${tier}</span>
              <div style="display:flex; align-items:center; gap:8px;"><img src="${getPokeAnim(p)}" style="width:42px; height:42px;"><div><div style="color:#fff;font-weight:bold;font-size:12px;">${i==0?'▶ ':''}${nameShow} Lv${p.level} <span style="font-size:9px;color:#aaa;">ATK ${p.baseMaxAtk||p.atk||0}</span></div><div style="font-size:10px;color:#888">HP ${p.hp}/${p.maxHp} | <span style="color:${p.rarity.color}">${p.rarity.n}</span> ${p.shiny?'✨':''}</div></div></div>
              <div style="display:flex;gap:4px" onclick="event.stopPropagation()"><button onclick="setActive(${i})" style="width:50px;background:#334;color:#fff;border:1px solid #556;border-radius:4px;padding:4px;font-size:10px;">ATIVO</button><button onclick="removeFromTeam(${i})" style="width:50px;background:#844;color:#fff;border:none;border-radius:4px;padding:4px;font-size:10px;">TIRAR</button></div>
            </div>`;
        } else {
            ht+=`<div style="color:#444; border:1px dashed #333; padding:10px; border-radius:8px; text-align:center; font-size:11px; margin:3px 0;">VAZIO</div>`;
        }
    }
    tl.innerHTML=ht;

    let filtered = P.box.map((p,i)=>({p,originalIdx:i})).filter(o=>o.p.name.toLowerCase().includes(search)).slice(0,100);
    let hb="";
    filtered.forEach(o=>{
      let p=o.p, i=o.originalIdx;
      let tier = typeof getTier==='function'? getTier(p.id, p.shiny, false, false) : 'E';
      hb+=`<div onclick="openPokeDetail(${i}, true)" style="background:#1a1a2e; border:2px solid ${p.rarity.color}; border-radius:10px; padding:6px 4px; text-align:center; cursor:pointer; position:relative;" class="aura-${tier}"><span class="tier-badge ${tier}" style="font-size:7px">${tier}</span><img src="${getPokeAnim(p)}" style="width:52px; height:52px;"><span style="font-size:10px; color:#fff; font-weight:bold; display:block; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${p.shiny?`Shiny ${p.name}`:p.name}</span><span style="font-size:9px; color:#888;">Lv${p.level} | ${p.rarity.n}</span></div>`;
    });
    bl.innerHTML=hb||"<p style='color:#666; grid-column:1/-1; text-align:center; padding:20px;'>Nenhum Pokémon</p>";
}

function setActive(i){
    const target=P.team?.[i];if(!target)return;const need=typeof psySpecialUseReq==='function'?psySpecialUseReq(target):1;
    if((P.trainerLevel||1)<need)return notif(`🔒 ${target.name} exige Trainer Lv.${need} para usar.`,3500);
    if(i==0){if(inBattle)closeTeam();return;}
    let tmp=P.team[0];P.team[0]=P.team[i];P.team[i]=tmp;renderTeam();updateHUD();autoSave();
    if(inBattle){document.getElementById('player-name-tag').textContent=P.team[0].name;document.getElementById('player-img').src=getPokeAnim(P.team[0]);updateBattleHP();loadMoveButtons();document.getElementById('battle-log').textContent=`🔄 Vai ${P.team[0].name}!`;closeTeam();}
}
function addToTeam(boxIndex){
    if(P.team.length>=6){notif("❌ Time cheio!");return;}const poke=P.box?.[boxIndex];if(!poke)return;
    const need=typeof psySpecialUseReq==='function'?psySpecialUseReq(poke):1;if((P.trainerLevel||1)<need)return notif(`🔒 ${poke.name} fica na Box até Trainer Lv.${need}.`,3500);
    P.box.splice(boxIndex,1);poke.hp=poke.maxHp;P.team.push(poke);renderTeam();updateHUD();autoSave();
}
function removeFromTeam(teamIndex){
    if(P.team.length<=1){ notif("❌ Não pode ficar sem Pokémon!"); return; }
    let poke = P.team.splice(teamIndex,1)[0];
    P.box.push(poke);
    renderTeam(); updateHUD(); autoSave();
}
