function getWorldTier(){ let lv=P.team[0]?.level||1; if(lv<10) return {name:"T1 1-10", min:1, max:10}; if(lv<20) return {name:"T2 10-20", min:10, max:20}; if(lv<40) return {name:"T3 20-40", min:20, max:40}; if(lv<60) return {name:"T4 40-60", min:40, max:60}; return {name:"T5 60-80", min:60, max:80}; }
