// PATCH V35 FIX - DANO USA ATK REAL + DROP + XP TREINADOR
battleAction = function(action, moveData){
  ensureTrainerData();
  if (!inBattle || battleData.state!== 'active') return;
  const log = document.getElementById('battle-log');
  if (action === 'move') {
    const move = moveData;
    const moveKey=String(move?.name||'').toLowerCase().trim();
    const isStatusMove=Number(move?.power||0)<=0||String(move?.type||'').toLowerCase()==='status';
    battleData.statusFx=battleData.statusFx||{enemyAtk:0,enemyAtkTurns:0,enemyDef:0,enemyDefTurns:0,myAtk:0,myAtkTurns:0,myDef:0,myDefTurns:0,protect:0};
    const fx=battleData.statusFx;
    let wildType = (typeof psyResolvePokemonTypes==='function' ? psyResolvePokemonTypes(battleData.wild) : (battleData.wild.type || "Normal"));

    let eff = getEffectiveness(move.type, wildType);
    let isCrit = Math.random() < (0.12 + getTotalBuff('crit')/100);

    let stats = calcDetailedStats(P.team[0]);
    let myAtk = Math.floor(stats.finalAtk*(1+(fx.myAtk||0)/100));
    let wildDef = Math.floor(battleData.wildMaxHp * 0.18*(1+(fx.enemyDef||0)/100));

    /* Status moves never deal fallback damage. They alter combat state and still consume the turn. */
    if(isStatusMove){
      let statusText='Efeito de status aplicado.';
      if(moveKey==='growl'){fx.enemyAtk=Math.max(-60,(fx.enemyAtk||0)-20);fx.enemyAtkTurns=2;statusText='ATK do inimigo -20% por 2 turnos.'}
      else if(moveKey==='tail whip'){fx.enemyDef=Math.max(-60,(fx.enemyDef||0)-18);fx.enemyDefTurns=2;statusText='DEF do inimigo -18% por 2 turnos.'}
      else if(moveKey==='leer'){fx.enemyDef=Math.max(-60,(fx.enemyDef||0)-15);fx.enemyDefTurns=2;statusText='DEF do inimigo -15% por 2 turnos.'}
      else if(moveKey==='harden'||moveKey==='defense curl'){fx.myDef=Math.min(100,(fx.myDef||0)+20);fx.myDefTurns=3;statusText='DEF +20% por 3 turnos.'}
      else if(moveKey==='swords dance'){fx.myAtk=Math.min(120,(fx.myAtk||0)+40);fx.myAtkTurns=3;statusText='ATK +40% por 3 turnos.'}
      else if(moveKey==='howl'){fx.myAtk=Math.min(120,(fx.myAtk||0)+20);fx.myAtkTurns=3;statusText='ATK +20% por 3 turnos.'}
      else if(moveKey==='calm mind'){fx.myAtk=Math.min(120,(fx.myAtk||0)+20);fx.myDef=Math.min(100,(fx.myDef||0)+20);fx.myAtkTurns=3;fx.myDefTurns=3;statusText='ATK e DEF +20% por 3 turnos.'}
      else if(moveKey==='protect'){fx.protect=1;statusText='Protege contra o próximo ataque.'}
      if(log)log.textContent=`✨ ${P.team[0].name} usou ${move.name}! ${statusText}`;
      attackAnimation('player');
      setTimeout(() => {
        attackAnimation('enemy');
        let eff2 = getEffectiveness(wildType.split('/')[0], (typeof psyResolvePokemonTypes==='function'?psyResolvePokemonTypes(P.team[0]):(P.team[0].type||"Normal")));
        let enemyAtk = Math.floor((20 + battleData.wild.level*4 + battleData.wildMaxHp*0.04)*(1+(fx.enemyAtk||0)/100));
        let myDef = Math.floor(stats.finalDef*(1+(fx.myDef||0)/100));
        let eDmg = fx.protect?0:Math.floor(enemyAtk * 0.85 * eff2 * (100/(100+myDef*0.15)));
        if(!fx.protect&&eDmg<3)eDmg=3;
        if(fx.protect){fx.protect=0;if(log)log.textContent+=` 🛡️ O ataque de ${battleData.wild.name} foi bloqueado!`}
        else{P.team[0].hp=Math.max(0,P.team[0].hp-eDmg);showDmgPopup(eDmg,false,false);if(log)log.textContent+=` 💢 ${battleData.wild.name} revidou: ${eDmg} dmg.`;setPlayerBlink()}
        if(fx.enemyAtkTurns>0&&--fx.enemyAtkTurns<=0)fx.enemyAtk=0;
        if(fx.enemyDefTurns>0&&--fx.enemyDefTurns<=0)fx.enemyDef=0;
        if(fx.myAtkTurns>0&&--fx.myAtkTurns<=0)fx.myAtk=0;
        if(fx.myDefTurns>0&&--fx.myDefTurns<=0)fx.myDef=0;
        updateBattleHP();updateHUD();
        if(P.team[0].hp<=0)setTimeout(()=>{if(typeof window.psyOpenBattleSwitch==='function')window.psyOpenBattleSwitch();else endBattle(false)},1200);
      },900);
      return;
    }

    let dmgBuff = getTotalBuff('dmg');
    let base = Math.floor((myAtk * Number(move.power||0) / 55) + (P.team[0].level * 3));
    base = Math.floor(base * (1+dmgBuff/100));

    let dmg = eff===0?0:Math.floor(base * eff * (isCrit?1.9:1) * (100/(100+wildDef*0.15)));
    /* Imunidade é dano zero de verdade; o piso mínimo só vale para ataques
       que acertaram. Assim “não teve efeito” não causa dano escondido. */
    if(eff!==0 && dmg < 15) dmg = 15 + Math.floor(Math.random()*10);

    showDmgPopup(dmg, true, isCrit);
    if(isCrit || eff!==1) showEffPopup(eff, isCrit);
    let msgEff = isCrit?" ⭐ CRÍTICO!" : eff===0?" 😴 IMUNE!":eff>=2?" 🔥 SUPER EFETIVO!":eff<=0.5?" 💧 NÃO MUITO...":"";

    battleData.wildHp = Math.max(0, battleData.wildHp - dmg);
    if(log) log.textContent = `💥 ${P.team[0].name} usou ${move.name}! ${dmg} dmg! ATK ${myAtk} ${msgEff}`;
    attackAnimation('player'); setEnemyBlink(); updateBattleHP();

    if (battleData.wildHp <= 0) {
      battleData.state = 'won';
      let lvl = battleData.wild.level || 5;
      let finalXp = Math.floor((lvl*85+150)*(1+getTotalBuff('xp')/100));
      let finalGold = Math.floor((lvl*18+80)*(1+getTotalBuff('gold')/100));
      P.team[0].exp += finalXp; P.gold += finalGold;psyAwardGlobalPsyduckXp(finalXp,'battle');
      gainTrainerXp(Math.floor(finalXp*0.1));
      /* O Wild entrega os materiais no ponto real da vitória. O encerramento
         legado continua responsável por fechar a batalha; a camada compartilhada
         marca o alvo para que o callback posterior não duplique o drop. */
      try{window.psySharedWildVictoryDrop?.(battleData.wild)}catch(e){console.warn('[PSYWORLD WILD] shared drops',e)}
      tryDropStone(wildType, lvl);
      if(log) log.textContent = `🎉 Derrotou Lv.${lvl} ${battleData.wild.name}! +${finalXp} EXP +${finalGold}G${msgEff}`;
      checkLevelUp(); updateHUD();
    // === GYM FIX - TEM QUE FICAR AQUI DENTRO ===
      if(gymBattle){
        gymBattle.current++;
        setTimeout(()=>startNextGymPoke(),1200);
        return;
      }
      setTimeout(() => endBattle(true), 1200); return;
    }
    setTimeout(() => {
      attackAnimation('enemy');
      let eff2 = getEffectiveness(wildType.split('/')[0], (typeof psyResolvePokemonTypes==='function'?psyResolvePokemonTypes(P.team[0]):(P.team[0].type||"Normal")));
      let enemyAtk = Math.floor((20 + battleData.wild.level*4 + battleData.wildMaxHp*0.04)*(1+(fx.enemyAtk||0)/100));
      let myDef = Math.floor(stats.finalDef*(1+(fx.myDef||0)/100));
      let eDmg = fx.protect?0:Math.floor(enemyAtk * 0.85 * eff2 * (100/(100+myDef*0.15)));
      if(!fx.protect&&eDmg<3) eDmg=3;
      if(fx.protect)fx.protect=0;
      P.team[0].hp = Math.max(0, P.team[0].hp - eDmg);
      showDmgPopup(eDmg, false, false);
      if(log) log.textContent = `💢 ${battleData.wild.name} revidou! ${eDmg} dmg!`;
      setPlayerBlink();
      if(fx.enemyAtkTurns>0&&--fx.enemyAtkTurns<=0)fx.enemyAtk=0;
      if(fx.enemyDefTurns>0&&--fx.enemyDefTurns<=0)fx.enemyDef=0;
      if(fx.myAtkTurns>0&&--fx.myAtkTurns<=0)fx.myAtk=0;
      if(fx.myDefTurns>0&&--fx.myDefTurns<=0)fx.myDef=0;
      updateBattleHP(); updateHUD();
      if (P.team[0].hp <= 0) { setTimeout(() => { if(typeof window.psyOpenBattleSwitch==='function')window.psyOpenBattleSwitch();else endBattle(false); }, 1200); }
    }, 900);
  } else if (action === 'heal') { openBagSelector('potion'); }
    else if (action === 'capture') { openBagSelector('ball'); }
    else if (action === 'flee') {
  gymBattle=null;
  battleData.state='fled';
  setTimeout(()=>endBattle(false), 600);
  }
}

// UPDATE HUD COM TREINADOR
const _origUpdateHUD = updateHUD;
updateHUD = function(){
  if(!P.team[0]) return;
  P.pokemon = P.team[0];
  document.getElementById('hud-name').textContent = P.name + ` [T.Lv${P.trainerLevel}]`;
  document.getElementById('hud-lv').textContent = P.pokemon.level;
  P.hp = P.pokemon.hp; P.maxHp = P.pokemon.maxHp;
  document.getElementById('hp-fill').style.width = Math.max(0,(P.hp/P.maxHp*100))+'%';
  document.getElementById('hp-txt').textContent = P.hp+'/'+P.maxHp;
  document.getElementById('exp-fill').style.width = (P.pokemon.exp/P.pokemon.maxExp*100)+'%';
  document.getElementById('exp-txt').textContent = P.pokemon.exp+'/'+P.pokemon.maxExp;
  document.getElementById('hud-gold').textContent = P.gold;
  const pct = P.hp / P.maxHp;
  const fill = document.getElementById('hp-fill');
  fill.style.background = pct > 0.5? '#00ff41' : pct > 0.25? '#ffaa00' : '#ff2222';
  try{
    let hud=document.getElementById('hud-player');
    if(hud && !document.getElementById('trainer-hud-line')){
      let div=document.createElement('div');
      div.id='trainer-hud-line';
      div.style.cssText='font-size:9px; color:#00d0ff; margin-top:4px;';
      hud.appendChild(div);
    }
    let tLine=document.getElementById('trainer-hud-line');
    if(tLine) tLine.innerHTML=`🧑🏫 Lv.${P.trainerLevel} | ${P.trainerExp}/${P.trainerMaxExp} XP | ${P.trainerPoints} pts | Drop ${getTotalBuff('drop')}% • Captura por Tier`;
  }catch(e){}
};

setTimeout(()=>{ let atk=document.getElementById('world-atk'); if(atk) atk.onclick=()=>{ let near=worldWilds.slice().sort((a,b)=>Math.hypot(a.x-worldPlayer.x,a.y-worldPlayer.y)-Math.hypot(b.x-worldPlayer.x,b.y-worldPlayer.y))[0]; if(near&&Math.hypot(near.x-worldPlayer.x,near.y-worldPlayer.y)<6.5) attackWorldTarget(near); else notif("Ninguém na mira!"); }; let skill=document.getElementById('world-skill'); if(skill) skill.onclick=()=>{ if(skillCooldown>0){ notif('Cooldown'); return; } let inRange=worldWilds.filter(w=>Math.hypot(w.x-worldPlayer.x,w.y-worldPlayer.y)<6).slice(0,5); if(!inRange.length){ notif('Nenhum perto!'); return; } inRange.forEach(w=>{ let strong=getStrongestPoke(); w.hp-=(60+strong.level*2)*(1+getTotalBuff('dmg')/100); if(w.hp<=0) handleWorldKill(w); }); skillCooldown=10000; }; let heal=document.getElementById('world-heal'); if(heal) heal.onclick=()=>{ let best=getBestPotion(); if(!best){ notif("Sem poção!"); return; } useWorldPotion(best,false); }; },600);


// ==================== FIX V11 - HP RETROATIVO + TALENTOS FUNCIONANDO ====================
function ensurePokeBase(p){
  if(!p) return;
  if(typeof p.baseMaxHp === 'undefined' || p.baseMaxHp <=0){
    // Se não tem base, usa o maxHp atual como base (sem buffs ainda)
    p.baseMaxHp = p.maxHp || 50;
  }
}
function recalcPoke(p){
  if(!p) return;
  ensurePokeBase(p);
  let oldMax = p.maxHp || p.baseMaxHp;
  let ratio = oldMax>0 ? (p.hp / oldMax) : 1;
  // Se tava com vida cheia, mantém cheia
  if(p.hp >= oldMax*0.99) ratio = 1;
  let buff = getTotalBuff('hp');
  p.maxHp = Math.floor(p.baseMaxHp * (1 + buff/100));
  p.hp = Math.min(p.maxHp, Math.max(1, Math.floor(p.maxHp * ratio)));
  if(ratio>=0.99) p.hp = p.maxHp;
}
function recalcAllPokes(){
  try{
    ensureTrainerData();
    if(P.team) P.team.forEach(recalcPoke);
    if(P.box) P.box.forEach(recalcPoke);
    if(P.team && P.team[0]) { P.pokemon = P.team[0]; P.hp = P.pokemon.hp; P.maxHp = P.pokemon.maxHp; }
    // World player também
    try{
      let strong = getStrongestPoke();
      let base = strong.baseMaxHp || strong.maxHp || 100;
      worldPlayer.maxHp = Math.max(50, Math.floor(base * (1+getTotalBuff('hp')/100)));
      worldPlayer.hp = Math.min(worldPlayer.hp, worldPlayer.maxHp);
    }catch(e){}
    updateHUD();
    updateWorldHUD();
    try{ renderTeam(); }catch(e){}
    try{ drawBox(); }catch(e){}
  }catch(e){ console.log('recalc erro',e); }
}



// FIX level up - aumenta baseMaxHp
const _origCheckLevelUp = checkLevelUp;
checkLevelUp = function() {
    if(!P.team[0]) return;
    let leveled = false;
    while (P.team[0].exp >= P.team[0].maxExp) {
        P.team[0].exp -= P.team[0].maxExp; P.team[0].level++; P.team[0].maxExp = Math.floor(P.team[0].maxExp * 1.3);
        ensurePokeBase(P.team[0]);
        P.team[0].baseMaxHp += 20;
        recalcPoke(P.team[0]);
        P.hp = P.team[0].hp; P.maxHp = P.team[0].maxHp;
        notif(`⭐ ${P.team[0].name} subiu para o nível ${P.team[0].level}! HP ${P.team[0].maxHp}`, 3000);
        leveled = true;
    }
    if(leveled) { updateHUD(); try{ renderTeam(); }catch(e){} }
}

// FIX para pokes existentes ao carregar save
function migrateOldPokes(){
  if(!P.team) return;
  let changed = false;
  [...P.team, ...P.box].forEach(p=>{
    if(typeof p.baseMaxHp === 'undefined'){
      // tenta recuperar base dividindo pelo buff atual
      let buff = getTotalBuff('hp');
      let base = Math.floor(p.maxHp / (1+buff/100));
      if(base < 10) base = p.maxHp;
      p.baseMaxHp = base;
      changed = true;
    }
  });
  if(changed){
    recalcAllPokes();
    notif('🔄 Pokes migrados para sistema retroativo! HP atualizado!',4000);
    autoSave();
  }
}

// Roda migração 1s após iniciar
setTimeout(()=>{ migrateOldPokes(); recalcAllPokes(); }, 1200);
setTimeout(()=>{ migrateOldPokes(); recalcAllPokes(); }, 3000);

// Também recalcula toda vez que abre o time
const _origRenderTeam = renderTeam;
renderTeam = function(){
  recalcAllPokes();
  _origRenderTeam();
}

