// ===== PARTE 2: FOTOS SHOWDOWN - CORRIGIDO X/Y =====
function getShowdownName(id){
  if(!id) return null;
  if(typeof NPC_NAMES!== 'undefined' && NPC_NAMES[id]) return NPC_NAMES[id].toLowerCase();
  if(typeof ALL_POKE_NAMES!== 'undefined' && ALL_POKE_NAMES[id]){
    let n = ALL_POKE_NAMES[id];
    const specialMap = {
      'NidoranF':'nidoranf','NidoranM':'nidoranm','MrMime':'mrmime','Farfetchd':'farfetchd',
      'Mr.Mime':'mrmime','MimeJr':'mimejr','TypeNull':'typenull','MrRime':'mrrime','Ho-Oh':'hooh',
      'Porygon2':'porygon2','PorygonZ':'porygonz','GreatTusk':'greattusk','ScreamTail':'screamtail',
      'BruteBonnet':'brutebonnet','FlutterMane':'fluttermane','SlitherWing':'slitherwing',
      'SandyShocks':'sandyshocks','IronTreads':'irontreads','IronBundle':'ironbundle',
      'IronHands':'ironhands','IronJugulis':'ironjugulis','IronMoth':'ironmoth','IronThorns':'ironthorns'
    };
    if(specialMap[n]) return specialMap[n];
    return n.toLowerCase().replace(/[^a-z0-9]/g,'');
  }
  return null;
}

window.getImg = function(id, shiny=false, isMega=false, megaForm=null){
  const pokeLike = { id, shiny:!!shiny, isMega:!!isMega, megaForm:megaForm || null };
  const url = getRealSprite(pokeLike);
  const key = url;
  if(typeof imgCache === 'undefined') window.imgCache = {};
  if(imgCache[key]) return imgCache[key];
  const img = new Image();
  img.src = url;
  img.onerror = function(){
    this.onerror = null;
    this.src = `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/${id}.png`;
  };
  imgCache[key] = img;
  return img;
};

window.getPokeAnim = function(p){ return getRealSprite(p); }
function getPokeAnim(p){ return getRealSprite(p); }
