window.calcDetailedStats = function(poke){
  if(typeof ensureTrainerData==='function') ensureTrainerData();
  poke = poke || {};
  let lvl = poke.level || 1;
  let mult = poke.rarity?.mult || 1;
  
  // USA O CALCULO REAL DO JOGO (igual batalha)
  let realBaseHp = calcBaseHpV14(lvl, mult, poke.shiny, poke.isMega, poke.id);
  let realBaseAtk = calcBaseAtkV14(lvl, mult, poke.shiny, poke.isMega, poke.id);

  let hpBuff = typeof getTotalBuff==='function'?getTotalBuff('hp'):0;
  let dmgBuff = typeof getTotalBuff==='function'?getTotalBuff('dmg'):0;
  let critBuff = typeof getTotalBuff==='function'?getTotalBuff('crit'):0;
  let capBuff = typeof getTotalBuff==='function'?getTotalBuff('cap'):0;
  let goldBuff = typeof getTotalBuff==='function'?getTotalBuff('gold'):0;
  let xpBuff = typeof getTotalBuff==='function'?getTotalBuff('xp'):0;
  let dropBuff = typeof getTotalBuff==='function'?getTotalBuff('drop'):0;
  let shinyBuff = typeof getTotalBuff==='function'?getTotalBuff('shiny'):0;

  let finalHp = Math.floor(realBaseHp * (1+hpBuff/100));
  let finalAtk = Math.floor(realBaseAtk * (1+dmgBuff/100));
  
  let baseDef = Math.floor(realBaseAtk * 0.65);
  let finalDef = Math.floor(finalAtk * 0.65);
  let baseSpd = Math.floor(60 + lvl*1.5);
  let baseCrit = 5;
  let finalCrit = baseCrit + critBuff;
  let finalSpd = baseSpd;

  // compatibilidade com seu HTML
  return { 
    baseHp: realBaseHp, finalHp, hpBuff, 
    baseAtk: realBaseAtk, finalAtk, dmgBuff, 
    baseDef, finalDef, baseSpd, finalSpd, baseCrit, finalCrit, 
    critBuff, capBuff, goldBuff, xpBuff, dropBuff, shinyBuff, lvl,
    rarityBonus: mult, shinyBonus: poke.shiny?1:0, premierBonus: poke.premier?1:0
  };
};
window.showBuffOrigin = function(buffKey){
  if(typeof ensureTrainerData==='function') ensureTrainerData();
  let world = (typeof P!=='undefined' && P.worldBuffs) ? (P.worldBuffs[buffKey]||0) : 0;
  let trainer = (typeof P!=='undefined' && P.trainerBuffs) ? (P.trainerBuffs[buffKey]||0) : 0;
  let total = world+trainer;
  let nameMap = {cap:'Captura', gold:'Gold', xp:'XP', dmg:'Dano/ATK', hp:'HP/DEF', crit:'Crítico', drop:'Drop', shiny:'Shiny'};
  let name = nameMap[buffKey]||buffKey;
  if(typeof notif==='function') notif(`📊 ${name}: World ${world}% + Treinador ${trainer}% = Total ${total}%`, 4000);
};

window.renderPlayerStats = function(){
  if(typeof ensureTrainerData==='function') ensureTrainerData();
  let html = '';
  if(typeof WORLD_BUFFS_CFG==='undefined') return;
  WORLD_BUFFS_CFG.forEach(cfg=>{
    let world = (typeof P!=='undefined' && P.worldBuffs) ? (P.worldBuffs[cfg.key]||0) : 0;
    let trainer = (typeof P!=='undefined' && P.trainerBuffs) ? (P.trainerBuffs[cfg.key]||0) : 0;
    let total = world+trainer;
    let color = total>0 ? '#00ff88' : '#666';
    let maxInfo = cfg.max ? `/${cfg.max}%` : '';
    html += `<div onclick="showBuffOrigin('${cfg.key}')" style="display:flex; justify-content:space-between; align-items:center; background:#1a1a2e; padding:8px; border-radius:6px; margin:4px 0; border:1px solid #333; cursor:pointer;"><div><div style="color:#fff; font-size:11px; font-weight:bold;">${cfg.name}</div><div style="color:#888; font-size:9px;">World ${world}% + Treinador ${trainer}%</div></div><div style="text-align:right;"><div style="color:${color}; font-weight:900; font-size:13px;">${total}%${maxInfo}</div></div></div>`;
  });
  let el = document.getElementById('detail-player-stats');
  if(el) el.innerHTML = html;
  let lvEl = document.getElementById('detail-trainer-lv'); if(lvEl) lvEl.textContent = (typeof P!=='undefined'?P.trainerLevel:1);
  let ptsEl = document.getElementById('detail-trainer-pts'); if(ptsEl) ptsEl.textContent = (typeof P!=='undefined'?P.trainerPoints:0);
  let goldEl = document.getElementById('detail-gold'); if(goldEl) goldEl.textContent = (typeof P!=='undefined'?(P.gold||0).toLocaleString():'0');
};

