window.closePokeDetail = function(){
  let el = document.getElementById('screen-poke-detail');
  if(el) el.style.display = 'none';
  currentDetailPoke = null;
  if(typeof renderTeam==='function') renderTeam();
};
window.addToTeamFromDetail = function(){
  if(!currentDetailPoke || !currentDetailPoke.isBox) return;
  if(typeof addToTeam==='function') addToTeam(currentDetailPoke.idx);
  closePokeDetail();
};
window.releasePokeFromDetail = function(){
  if(!currentDetailPoke || !currentDetailPoke.isBox) return;
  if(!confirm(`Liberar ${currentDetailPoke.poke.name} Lv.${currentDetailPoke.poke.level}?`)) return;
  P.box.splice(currentDetailPoke.idx,1);
  if(typeof autoSave==='function') autoSave();
  closePokeDetail();
};
window.setActiveFromDetail = function(){
  if(!currentDetailPoke || currentDetailPoke.isBox) return;
  if(typeof setActive==='function') setActive(currentDetailPoke.idx);
  closePokeDetail();
};
window.removeFromTeamDetail = function(){
  if(!currentDetailPoke || currentDetailPoke.isBox) return;
  if(typeof removeFromTeam==='function') removeFromTeam(currentDetailPoke.idx);
  closePokeDetail();
};

// ===== RENDER TEAM REFEITO - SHINY + TIER + FILTRO =====
let _lastRecalcTime = 0;
function shouldRecalc(){
  let now = Date.now();
  if(now - _lastRecalcTime > 3000){ _lastRecalcTime = now; return true; }
  return false;
}

window.renderTeam = function(){
  try{
    if(shouldRecalc()){
      if(P.team) P.team.forEach(p=>{ if(p){ if(typeof ensurePokeBase==='function') ensurePokeBase(p); if(typeof recalcPoke==='function') recalcPoke(p); } });
      if(P.box) P.box.forEach(p=>{ if(p){ if(typeof ensurePokeBase==='function') ensurePokeBase(p); if(typeof recalcPoke==='function') recalcPoke(p); } });
    }
  }catch(e){}
  const tl=document.getElementById('team-list');
  const bl=document.getElementById('box-list');
  const search = (document.getElementById('box-search')?.value || '').toLowerCase().trim();
  const fShiny = document.getElementById('box-filter-shiny')?.value || 'all';
  const fTier = document.getElementById('box-filter-tier')?.value || 'all';
  const fSort = document.getElementById('box-sort')?.value || 'id';
  const bc = document.getElementById('box-count');
  if(bc) bc.textContent = P.box.length;

  let ht="";
  for(let i=0;i<6;i++){
      let p=P.team[i];
      if(p){
        let stats = calcDetailedStats(p);
        let tier = p.forceTier||p.tier||(p.forceTier||p.tier||getTier(p.id, p.shiny, p.isMega, false));
        let displayName = p.name; // já vem Shiny Mega Charizard Y do fix anterior
        // FIX TIME/CIDADE - usa megaForm e shiny
        let base = p.megaForm || getShowdownName(p.id) + (p.isMega?'-mega':'');
        let folder = p.shiny ? 'ani-shiny' : 'ani';
        let imgSrc = `https://play.pokemonshowdown.com/sprites/${folder}/${base}.gif`;
        let fallbackSrc = `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/${p.id}.png`;
        
        ht+=`<div onclick="openPokeDetail(${i}, false)" style="display:flex; align-items:center; justify-content:space-between; background:#1a1a2e; border:${i==0?'2px solid #00ff41':'1px solid #333'}; border-radius:8px; padding:6px; margin:3px 0; cursor:pointer; position:relative">
          <span class="tier-badge ${tier}">${tier}</span>
          <div style="display:flex; align-items:center; gap:8px;">
          <img src="${imgSrc}" style="width:40px; height:40px; image-rendering:pixelated;" onerror="this.onerror=null;this.src='${fallbackSrc}'">
            <div>
              <div style="color:#fff;font-weight:bold; font-size:12px;">${i==0?'▶ ':''}${p.shiny?'<span class="shiny-tag">'+displayName+'</span>':displayName} Lv${p.level} <span style="color:#888; font-size:10px;">ATK ${stats.finalAtk}</span></div>
              <div style="font-size:10px;color:#888">HP ${p.hp}/${p.maxHp} | <span style="color:${p.rarity.color}">${p.rarity.n}</span> | <b style="color:${TIER_CONFIG[tier]?.color||'#fff'}">${tier}</b> ${p.shiny?'✨':''} ${p.isMega?'🔷':''} ${p.premier?'👑':''}</div>
            </div>
          </div>
          <div style="display:flex;gap:4px" onclick="event.stopPropagation()">
            <button onclick="setActive(${i})" style="width:50px; background:#334; color:#fff; border:1px solid #556; border-radius:4px; padding:4px; font-size:10px;">ATIVO</button>
            <button onclick="removeFromTeam(${i})" style="width:50px;background:#844; color:#fff; border:none; border-radius:4px; padding:4px; font-size:10px;">TIRAR</button>
          </div>
        </div>`;
      } else {
        ht+=`<div style="color:#444; border:1px dashed #333; padding:8px; border-radius:6px; text-align:center; font-size:11px; margin:2px 0;">VAZIO</div>`;
      }
  }
  if(tl) tl.innerHTML=ht;

  let filtered = P.box.map((p,i)=>({p,originalIdx:i})).filter(o=>{
    if(search &&!o.p.name.toLowerCase().includes(search)) return false;
    if(fShiny==='shiny' &&!o.p.shiny) return false;
    if(fShiny==='normal' && o.p.shiny) return false;
    if(fTier!=='all'){
      let t = o.p.forceTier||o.p.tier||getTier(o.p.id, o.p.shiny, o.p.isMega, false);
      if(t!==fTier) return false;
    }
    return true;
  });

  filtered.sort((a,b)=>{
    if(fSort==='level_desc') return b.p.level - a.p.level;
    if(fSort==='level_asc') return a.p.level - b.p.level;
    if(fSort==='atk_desc') return (b.p.atk||b.p.baseMaxAtk||0)-(a.p.atk||a.p.baseMaxAtk||0);
    if(fSort==='rarity_desc') return (b.p.rarity.mult||0)-(a.p.rarity.mult||0);
    return a.p.id - b.p.id;
  });

let toShow = filtered.slice(0, 80);
let hb = "";

toShow.forEach(o=>{
  let p = o.p, i = o.originalIdx;
  let stats = calcDetailedStats(p);
  let tier = p.forceTier||p.tier||(p.forceTier||p.tier||getTier(p.id, p.shiny, p.isMega, false));

  // FIX BOX - também usa megaForm
  let base = p.megaForm || getShowdownName(p.id) + (p.isMega?'-mega':'');
  let folder = p.shiny ? 'ani-shiny' : 'ani';
  let imgSrc = `https://play.pokemonshowdown.com/sprites/${folder}/${base}.gif`;
  let fallbackSrc = `https://play.pokemonshowdown.com/sprites/dex/${getShowdownName(p.id)}.png`;

  hb += `<div onclick="openPokeDetail(${i}, true)" style="background:#1a1a2e; border:2px solid ${p.rarity.color}; border-radius:10px; padding:6px 4px; text-align:center; cursor:pointer; position:relative">
    <span class="tier-badge ${tier}" style="font-size:7px">${tier}</span>
    <img src="${imgSrc}" style="width:56px; height:56px; image-rendering:pixelated;" onerror="this.onerror=null;this.src='${fallbackSrc}'">
    <div style="font-size:10px; color:#fff; font-weight:bold; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${p.name}</div>
    <div style="font-size:9px; color:#888;">Lv${p.level} | ${tier} | ATK ${stats.finalAtk}</div>
  </div>`;
});

if(filtered.length > 80){
  hb += `<div style="grid-column:1/-1; text-align:center; color:#888; font-size:10px; padding:8px;">Mostrando 80 de ${filtered.length} | Use busca/filtro</div>`;
}

if(bl) bl.innerHTML = hb || "<p style='color:#666; grid-column:1/-1; text-align:center; padding:20px;'>Nenhum Pokémon</p>";
};
