  WILD_ZONES_GEN1['fogo_t2']=[{id:4,name:"Charmander"},{id:37,name:"Vulpix"},{id:58,name:"Growlithe"},{id:77,name:"Ponyta"},{id:240,name:"Magby"},{id:5,name:"Charmeleon"}];
  WILD_ZONES_GEN1['fogo_t3']=[{id:5,name:"Charmeleon"},{id:126,name:"Magmar"},{id:6,name:"Charizard"},{id:38,name:"Ninetales"},{id:59,name:"Arcanine"},{id:78,name:"Rapidash"},{id:136,name:"Flareon"}];
  WILD_ZONES_GEN1['fogo_t4']=[{id:6,name:"Charizard"},{id:38,name:"Ninetales"},{id:59,name:"Arcanine"},{id:78,name:"Rapidash"},{id:136,name:"Flareon"},{id:126,name:"Magmar"}];
  WILD_ZONES_GEN1['eletrico_t1']=[{id:25,name:"Pikachu"},{id:81,name:"Magnemite"},{id:100,name:"Voltorb"},{id:239,name:"Elekid"}];
  WILD_ZONES_GEN1['eletrico_t2']=[{id:25,name:"Pikachu"},{id:81,name:"Magnemite"},{id:100,name:"Voltorb"},{id:239,name:"Elekid"},{id:26,name:"Raichu"},{id:82,name:"Magneton"}];
