// GARANTE QUE O CAP RECALCULE SEMPRE QUE ABRE O JOGO
window.recalcLevelCap = function(){
  let cap = 20;
  REGION_ORDER.forEach(reg=>{
    if(typeof getRegionCompleted === 'function' && getRegionCompleted(reg)){
        cap = REGION_CAPS[reg];
    }
  });
  P.levelCap = Math.min(100, cap);
  return P.levelCap;
};
window.fixMeusPokes=function(){ P.team.forEach(recalcPoke); P.box.forEach(recalcPoke); updateHUD(); renderTeam(); autoSave(); };
setTimeout(fixMeusPokes, 800);
window.triggerWild = function(pool){
  if(inBattle) return;
  if(!P.team[0]) return;

  let key = pool;
  let regKey, tipo, tierNum;
  if(key.includes('_t')){
    let parts=key.split('_');
    if(parts.length>=3){ regKey=parts[0]; tipo=parts[1]; tierNum=parseInt(parts[2].replace('t',''))||1; }
    else { regKey="kanto"; tipo=parts[0]; tierNum=parseInt(parts[1].replace('t',''))||1; }
  }else{ regKey="kanto"; tipo=key.split('_t')[0]; tierNum=1; }

  let list = getPokesForHunt(regKey,tipo,tierNum);
  if(typeof BOSS_BAN_IDS!=='undefined') list = list.filter(p=>!BOSS_BAN_IDS.has(p.id));
  if(!list||!list.length){
    notif(`❌ ${regKey.toUpperCase()} SEM ${tipo.toUpperCase()} T${tierNum}`,2500);
    return;
  }

  const base = list[Math.floor(Math.random()*list.length)];
  // RARIDADE AGORA USA O TIER DO POKE, NÃO DA HUNT
  let pokeTier = getTier(base.id);
  const rarity = rollRarity(pokeTier);
  let isShiny = Math.random() < (0.0005 + getTotalBuff('shiny')*0.00002);
  let isMega = Math.random() < 0.01;

  let min=1,max=10;
  if(tierNum==2){min=10;max=20;}
  else if(tierNum==3){min=20;max=35;}
  else if(tierNum==4){min=40;max=60;}

  const lvl = Math.floor(Math.random()*(max-min+1))+min;
  let baseHp = calcBaseHpV14(lvl, rarity.mult||1, isShiny, isMega, base.id);

  let tipoBg = tipo==='metal'?'aco':tipo;
  let hud=document.querySelector('.battle-hud');
  if(hud){
    hud.style.backgroundImage=`url(Hunts/${tipoBg}.png)`;
    hud.style.backgroundColor='#1a3a1a';
    hud.style.backgroundSize='cover';
    hud.style.backgroundPosition='center';
  }

  startBattle({
    id:base.id,
    name:base.name,
    type:base.type||TYPE_BY_ID_ALL[base.id]||"Normal",
    shiny:isShiny, isMega:isMega,
    rarity, level:lvl, maxHp:baseHp, hp:baseHp
  });
};

window.createWorldWildData = function(id,x,y,lvl,isHorde=false){ let rarity = (window.rollRarityWorld?window.rollRarityWorld():rollRarity()); let totalShiny = typeof getTotalBuff==='function'?getTotalBuff('shiny'):0; let isShiny = Math.random()*100 < (0.05+totalShiny*0.0025); let isMega = Math.random()*100 < 2.0; let baseHp = window.calcBaseHpV14(lvl, rarity.mult, isShiny, isMega, id); let finalHp = Math.floor(baseHp * (isHorde?2.2:1.4)); return {id,name:getPokeName(id),x,y,hp:finalHp,maxHp:finalHp,lvl,dir:Math.random()*6.28,moveTimer:Math.random()*60,atkCD:0,speed:isHorde?0.032:0.050+Math.random()*0.01,region:typeof worldRegion!=='undefined'?worldRegion:'kanto',isHorde,rarity,shiny:isShiny,isMega:isMega}; };
window.spawnWorldWilds = function(qtd){ worldWilds=[]; let regionList=typeof getRegionPokemonList==='function'?getRegionPokemonList(worldRegion):[1,4,7,25]; if(!regionList.length) regionList=[1,4,7,25]; let tier=typeof getWorldTier==='function'?getWorldTier():{min:1,max:10}; for(let i=0;i<qtd;i++){ let id=regionList[Math.floor(Math.random()*regionList.length)]; let x,y,t=0; do{ x=Math.floor(Math.random()*(WORLD_W-10))+5+Math.random(); y=Math.floor(Math.random()*(WORLD_H-10))+5+Math.random(); t++; }while((worldMap[Math.floor(y)]?.[Math.floor(x)]!==0&&worldMap[Math.floor(y)]?.[Math.floor(x)]!==3)||Math.hypot(x-SAFE_X,y-SAFE_Y)<SAFE_R+5&&t<100); let lvl=Math.floor(Math.random()*(tier.max-tier.min+1))+tier.min; worldWilds.push(window.createWorldWildData(id,x,y,lvl,false)); } };
window.spawnWorldWildsIncremental = function(qtd){ let regionList=typeof getRegionPokemonList==='function'?getRegionPokemonList(worldRegion):[1,4,7,25]; let tier=typeof getWorldTier==='function'?getWorldTier():{min:1,max:10}; for(let i=0;i<qtd;i++){ let id=regionList[Math.floor(Math.random()*regionList.length)]; let x,y,t=0; do{ x=Math.floor(Math.random()*(WORLD_W-10))+5+Math.random(); y=Math.floor(Math.random()*(WORLD_H-10))+5+Math.random(); t++; }while((worldMap[Math.floor(y)]?.[Math.floor(x)]!==0&&worldMap[Math.floor(y)]?.[Math.floor(x)]!==3)||Math.hypot(x-SAFE_X,y-SAFE_Y)<SAFE_R+5&&t<100); let lvl=Math.floor(Math.random()*(tier.max-tier.min+1))+tier.min; worldWilds.push(window.createWorldWildData(id,x,y,lvl,false)); } };

window.ensureMoveSwapScreen=function(){ if(document.getElementById('screen-move-swap')) return; let d=document.createElement('div'); d.id='screen-move-swap'; d.style.cssText='display:none;position:fixed;inset:0;background:rgba(0,0,0,0.96);z-index:1000000;padding:12px;overflow:auto;'; d.innerHTML=`<div style="max-width:600px;margin:0 auto;background:#151520;border:2px solid #00d0ff;border-radius:12px;padding:12px;"><h3 style="color:#00d0ff;text-align:center;">🔄 TROCAR MOVES</h3><div id="move-swap-current"></div><div style="color:#aaa;font-size:10px;margin:8px 0;text-align:center;">Selecione 1 ativo e depois 1 da lista</div><div id="move-swap-pool" style="display:grid;grid-template-columns:1fr 1fr;gap:6px;max-height:50vh;overflow:auto;"></div><button onclick="document.getElementById('screen-move-swap').style.display='none'" style="width:100%;margin-top:10px;background:#333;color:#fff;border:none;padding:10px;border-radius:6px;">FECHAR</button></div>`; document.body.appendChild(d); };
window.openMoveSwap=function(idx,isBox){ window.ensureMoveSwapScreen(); window._swapRef={idx,isBox}; window._selCur=null; window.renderMoveSwap(); document.getElementById('screen-move-swap').style.display='block'; };
window.renderMoveSwap=function(){ let ref=window._swapRef; let poke=ref.isBox?P.box[ref.idx]:P.team[ref.idx]; if(!poke.movePool) poke.movePool=window.getFullMoveList(poke.id,poke.level); document.getElementById('move-swap-current').innerHTML=`<div style="color:#ffd700;font-size:11px;">ATIVOS (${poke.moves.length}/4)</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:6px;">`+poke.moves.map((m,i)=>`<button onclick="window._selCur=${i};window.renderMoveSwap()" style="background:${window._selCur===i?'#00d0ff':'#333'};color:#fff;border:2px solid ${window._selCur===i?'#fff':'#555'};padding:8px;border-radius:6px;font-size:11px;"><b>${m.name}</b><br>${m.type} ${m.power}</button>`).join('')+`</div>`; let avail=poke.movePool.filter(x=>!poke.moves.some(c=>c.name===x.name)); document.getElementById('move-swap-pool').innerHTML=avail.length?avail.map(m=>`<button onclick="window.swapLearn('${m.name.replace(/'/g,"\\'")}')" style="background:#1a1a2e;border:1px solid #334;color:#fff;padding:8px;border-radius:6px;font-size:11px;text-align:left;"><b>${m.name}</b> ${m.type} PWR${m.power}</button>`).join(''):`<div style="color:#666;grid-column:1/-1;text-align:center;padding:20px;">Nenhum extra - upe mais!</div>`; };
window.swapLearn=function(name){ let ref=window._swapRef; let poke=ref.isBox?P.box[ref.idx]:P.team[ref.idx]; let mv=poke.movePool.find(x=>x.name===name); if(!mv) return; if(poke.moves.length<4) poke.moves.push(mv); else { if(window._selCur===null){ notif("Selecione um ativo primeiro!"); return; } poke.moves[window._selCur]=mv; window._selCur=null; } notif(`✅ ${name} equipado!`); window.renderMoveSwap(); autoSave(); loadMoveButtons(); renderTeam(); };
let _oldDetail=openPokeDetail; window.openPokeDetail=function(idx,isBox){ _oldDetail(idx,isBox); let cont=document.getElementById('detail-poke-content'); if(!cont) return; if(!document.getElementById('btn-troca-moves')){ let b=document.createElement('button'); b.id='btn-troca-moves'; b.textContent='🔄 TROCAR MOVES'; b.style.cssText='width:100%;margin-top:8px;background:linear-gradient(90deg,#00d0ff,#0066ff);color:#fff;border:none;padding:10px;border-radius:8px;font-weight:900;'; b.onclick=()=>openMoveSwap(idx,isBox); cont.appendChild(b); } };

