window.ensureDungeonScreen=function(){
if(document.getElementById('screen-dungeon')) document.getElementById('screen-dungeon').remove();
let d=document.createElement('div'); d.id='screen-dungeon'; d.style.cssText='display:none;position:fixed;inset:0;background:rgba(0,0,0,0.97);z-index:999999;overflow:auto;padding:12px;'; d.innerHTML=`<div style="max-width:950px;margin:0 auto;background:#111;border:2px solid #ff0055;border-radius:14px;padding:12px;"><div style="display:flex;justify-content:space-between;"><h2 style="color:#ff0055;margin:0;">🏰 DUNGEONS</h2><button onclick="document.getElementById('screen-dungeon').style.display='none'" style="background:#833;color:#fff;border:none;padding:6px 12px;border-radius:6px;">X</button></div><div style="display:flex;gap:8px;margin:10px 0;"><button id="btn-tab-boss" onclick="switchDungeonTab('boss')" style="flex:1;background:#ff0055;color:#fff;border:none;padding:10px;border-radius:8px;font-weight:900;">👹 BOSS 1M</button><button id="btn-tab-shiny" onclick="switchDungeonTab('shiny')" style="flex:1;background:#333;color:#fff;border:none;padding:10px;border-radius:8px;font-weight:900;">✨ SHINY 50k</button></div><div id="dungeon-info" style="background:#000;padding:8px;border-radius:8px;color:#aaa;font-size:10px;text-align:center;margin-bottom:10px;"></div><div id="dungeon-boss-list" style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;"></div><div id="dungeon-shiny-list" style="display:none;grid-template-columns:repeat(4,1fr);gap:10px;"></div><div id="dungeon-craft-area" style="margin-top:12px;background:#1a1a2e;padding:10px;border-radius:10px;"><h3 style="color:#ffd700;margin:0 0 6px;font-size:12px;">🔧 CRAFT</h3><div id="dungeon-craft-list"></div></div></div>`; document.body.appendChild(d); let st=document.createElement('style'); st.innerHTML=`.boss-card{position:relative;background:#1a0a;border:2px solid #f00;border-radius:12px;padding:8px;text-align:center;cursor:pointer;animation:redAura 1.2s infinite alternate} @keyframes redAura{0%{box-shadow:0 0 8px #f00}100%{box-shadow:0 0 20px #f00}}.shiny-card{position:relative;background:#1a1a2e;border:2px solid #ffd700;border-radius:12px;padding:8px;text-align:center;cursor:pointer}.rainbow-text{background:linear-gradient(90deg,#f00,#ff0,#0f0,#0ff,#00f,#f0f,#f00);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-size:200% auto;animation:rb 2s linear infinite;font-weight:900} @keyframes rb{to{background-position:200% center}}`; document.head.appendChild(st);
};
window.switchDungeonTab=function(tab){ document.getElementById('dungeon-boss-list').style.display=tab=='boss'?'grid':'none'; document.getElementById('dungeon-shiny-list').style.display=tab=='shiny'?'grid':'none'; document.getElementById('btn-tab-boss').style.background=tab=='boss'?'#ff0055':'#333'; document.getElementById('btn-tab-shiny').style.background=tab=='shiny'?'#cc9900':'#333'; document.getElementById('dungeon-info').innerHTML=tab=='boss'?'👹 Boss 1M | Recompensa: 900k +30 stones +30x XP (+200%) | Essência 1% max 2% | 10=craft':'✨ Shiny 50k | Recompensa: 75k +900 Trainer XP (+200%) | Essência 1% até 10% | 50=craft'; };
window.openDungeons=function(){ ensureDungeonScreen(); renderDungeonBosses(); renderDungeonShinies(); renderDungeonCraft(); switchDungeonTab('boss'); document.getElementById('screen-dungeon').style.display='block'; };
function renderDungeonBosses(){ let c=document.getElementById('dungeon-boss-list'); if(!c) return; c.innerHTML=DUNGEON_BOSSES.map(b=>{ let en=`Essência Boss - ${b.name}`; let hv=P.inventory[en]||0; let tag=b.id==935?'🔥':b.id==936?'👻':''; return `<div class="boss-card" onclick="enterDungeonBoss(${b.id})"><img src="${getPokeAnim({id:b.id})}" style="width:80px;height:80px;" onerror="this.onerror=null; this.src='https://play.pokemonshowdown.com/sprites/ani/${getShowdownName(b.id)}.gif'"><div style="color:#fff;font-weight:900;font-size:11px;">${b.name} ${tag}</div><div style="color:#ff5555;font-size:8px;font-weight:900;">MEGA STATUS</div><div class="rainbow-text" style="font-size:9px;">${en}: ${hv}/10</div><button style="width:100%;margin-top:4px;background:#f00;color:#fff;border:none;padding:6px;border-radius:6px;font-size:10px;">⚔ 1M</button></div>`; }).join(''); }
function renderDungeonShinies(){ let c=document.getElementById('dungeon-shiny-list'); if(!c) return; c.innerHTML=DUNGEON_SHINIES.map(s=>{ let en=`Essência Shiny - ${s.name}`; let hv=P.inventory[en]||0; let img=`https://play.pokemonshowdown.com/sprites/ani-shiny/${ALL_POKE_NAMES[s.id].toLowerCase()}.gif`; return `<div class="shiny-card" onclick="enterDungeonShiny(${s.id})"><img src="${img}" style="width:64px;height:64px;" onerror="this.src='https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/shiny/${s.id}.png'"><div style="color:#ffd700;font-weight:900;font-size:10px;">✨ ${s.name}</div><div class="rainbow-text" style="font-size:8px;">${en}: ${hv}/50</div><button style="width:100%;margin-top:4px;background:#cc9900;color:#000;border:none;padding:5px;border-radius:5px;font-size:9px;font-weight:900;">✨ 50k</button></div>`; }).join(''); }
function renderDungeonCraft(){ let c=document.getElementById('dungeon-craft-list'); if(!c) return; let h=''; DUNGEON_BOSSES.forEach(b=>{ let e=`Essência Boss - ${b.name}`; let hv=P.inventory[e]||0; if(hv>=1) h+=`<div style="display:flex;justify-content:space-between;background:#220a0a;padding:6px;border-radius:6px;margin:4px 0;border:1px solid #f00;"><span class="rainbow-text" style="font-size:10px;">${e} x${hv}</span><button ${hv<10?'disabled':''} onclick="craftBoss(${b.id})" style="background:${hv>=10?'#f00':'#444'};color:#fff;border:none;padding:4px 8px;border-radius:4px;">CRAFT 10</button></div>`; }); DUNGEON_SHINIES.forEach(s=>{ let e=`Essência Shiny - ${s.name}`; let hv=P.inventory[e]||0; if(hv>=1) h+=`<div style="display:flex;justify-content:space-between;background:#1a1a0a;padding:6px;border-radius:6px;margin:4px 0;border:1px solid #ffd700;"><span class="rainbow-text" style="font-size:10px;">${e} x${hv}</span><button ${hv<50?'disabled':''} onclick="craftShiny(${s.id})" style="background:${hv>=50?'#cc9900':'#444'};color:#fff;border:none;padding:4px 8px;border-radius:4px;">CRAFT 50</button></div>`; }); if(!h) h=`<div style="color:#666;font-size:10px;text-align:center;">Nenhuma essência</div>`; c.innerHTML=h; }
window.craftBoss=function(id){ let b=DUNGEON_BOSSES.find(x=>x.id==id); let e=`Essência Boss - ${b.name}`; if((P.inventory[e]||0)<10){ notif("❌ Precisa 10"); return; } P.inventory[e]-=10; if(P.inventory[e]<=0) delete P.inventory[e]; let r=rollRarity(); let pk=createCapturedPoke(id,r,false); P.box.push(pk); notif(`✅ ${b.name}!`,3000); autoSave(); renderDungeonBosses(); renderDungeonCraft(); renderTeam(); };
window.craftShiny=function(id){ let s=DUNGEON_SHINIES.find(x=>x.id==id); let e=`Essência Shiny - ${s.name}`; if((P.inventory[e]||0)<50){ notif("❌ Precisa 50"); return; } P.inventory[e]-=50; if(P.inventory[e]<=0) delete P.inventory[e]; let r=rollRarity(); let pk=createCapturedPoke(id,r,true); P.box.push(pk); notif(`✨ SHINY ${s.name}!`,4000); autoSave(); renderDungeonShinies(); renderDungeonCraft(); renderTeam(); };
window.enterDungeonBoss=function(id){
  if((P.gold||0)<1000000){ notif("❌ Precisa 1M de Gold!"); return; }
  P.gold-=1000000; autoSave(); updateHUD();
  let b=DUNGEON_BOSSES.find(x=>x.id==id);
  let lvl=80;
  let bh=calcBaseHpV14(lvl,12,true,true,id)*5;
  document.getElementById('screen-dungeon').style.display='none';
  window.isDungeonBoss=true; window.currentDungeonId=id;
  startBattle({id:b.id,name:b.name+" [BOSS MEGA]",type:TYPE_BY_ID_ALL[id]||TYPE_BY_ID_EXT[id]||"Normal",shiny:false,isMega:true,rarity:{n:"DEUS",mult:20,color:"#fff"},level:lvl,maxHp:bh,hp:bh,isBoss:true});
};
window.enterDungeonShiny=function(id){ if((P.gold||0)<50000){ notif("❌ 50k!"); return; } P.gold-=50000; autoSave(); updateHUD(); let s=DUNGEON_SHINIES.find(x=>x.id==id); let lvl=60; let bh=calcBaseHpV14(lvl,5,true,false,id)*2.5; document.getElementById('screen-dungeon').style.display='none'; window.isDungeonShiny=true; window.currentDungeonId=id; startBattle({id:s.id,name:s.name+" ✨",type:TYPE_BY_ID_ALL[id]||"Normal",shiny:true,isMega:false,rarity:{n:"Pika",mult:10,color:"#ffd700"},level:lvl,maxHp:bh,hp:bh}); };
window.endBattle=function(won){
  let wasBoss=window.isDungeonBoss, wasShiny=window.isDungeonShiny, dId=window.currentDungeonId;
  inBattle=false;
  let bs=document.getElementById('battle-screen'); if(bs){ bs.style.display='none'; bs.classList.remove('active'); }
  isPlayerBlinking=isEnemyBlinking=false;
  let pDiv=document.getElementById('battle-player'); let eDiv=document.getElementById('battle-enemy');
  if(pDiv){ pDiv.classList.remove('poke-blink'); pDiv.style.transform=''; }
  if(eDiv){ eDiv.classList.remove('poke-blink'); eDiv.style.transform=''; }
  if(battleData) battleData.state=won?'won':'lost';
  if(won&&wasBoss&&dId){
    let b=DUNGEON_BOSSES.find(x=>x.id==dId);
    let goldDrop=900000;
    let stoneType=getStoneForType(TYPE_BY_ID_ALL[dId]||"Normal");
    let xpBase=(80*85+150)*30;
    let xpFinal=Math.floor(xpBase*(1+getTotalBuff('xp')/100));
    P.gold+=goldDrop;
    P.inventory[stoneType]=(P.inventory[stoneType]||0)+30;
    if(P.team[0]){ P.team[0].exp+=xpFinal; checkLevelUp(); }
    psyAwardGlobalPsyduckXp(xpFinal,'dungeon');
    gainTrainerXp(1500);
    let db=getTotalBuff('drop');
    let fin=Math.min(2,1*(1+db/100));
    if(Math.random()*100<fin){
      let en=`Essência Boss - ${b.name}`;
      P.inventory[en]=(P.inventory[en]||0)+1;
      notif(`🌈 DROP RARO! ${en} +1 (${fin.toFixed(2)}%)`,4000);
    }
    notif(`🏆 BOSS MORTO! +${goldDrop.toLocaleString()}G +30x ${stoneType} +${xpFinal} XP!`,5000);
    try{ spawnFloat(`+900k G +30 ${stoneType} +${xpFinal} XP`, "#ffd700"); }catch(e){}
    autoSave();
  }
  if(won&&wasShiny&&dId){
    let s=DUNGEON_SHINIES.find(x=>x.id==dId);
    let db=getTotalBuff('drop');
    let fin=Math.min(10,1*(1+db/100));
    if(Math.random()*100<fin){
      let en=`Essência Shiny - ${s.name}`;
      P.inventory[en]=(P.inventory[en]||0)+1;
      notif(`✨ DROP! ${en} +1 (${fin.toFixed(2)}%)`,4000);
    }
    P.gold+=75000; gainTrainerXp(900); autoSave();
  }
  window.isDungeonBoss=false; window.isDungeonShiny=false; window.currentDungeonId=null;
  if(won && window.fastEncounter){ setTimeout(()=>triggerWild(P.currentHunt||'kanto_planta_t1'),600); }
};
// TALENTO - SÓ SHINY 0.1%
window.TALENT_CONFIG = {
  cap: { name:"Chance captura", per:1, max:30 },
  gold: { name:"Gold", per:3, max:900 },
  xp: { name:"XP", per:3, max:300 },
  dmg: { name:"Dano", per:2, max:50 },
  hp: { name:"HP", per:3, max:60 },
  crit: { name:"Crítico", per:2, max:50 },
  drop: { name:"Drop", per:3, max:300 },
  shiny: { name:"Shiny", per:0.1, max:20 } // SÓ ESSE 0.1% MAX 20%
};
window.getTalentCost = function(type){
  let lvl = (P.trainerTalents && P.trainerTalents[type])? P.trainerTalents[type] : 0;
  let cost = Math.ceil(Math.pow(1.05, lvl));
  return cost<1?1:cost;
};

window.upgradeTalent = function(type){
  if(!P.trainerTalents) P.trainerTalents={};
  if(!P.trainerTalents[type]) P.trainerTalents[type]=0;
  let cfg = TALENT_CONFIG[type];
  if((P.trainerTalents[type]*cfg.per)>=cfg.max){ notif("❌ MAX!"); return; }
  let cost = getTalentCost(type);
  if((P.trainerPoints||0)<cost){ notif(`❌ Precisa ${cost} pontos!`); return; }
  P.trainerPoints -= cost;
  P.trainerTalents[type]++;
  notif(`✅ ${cfg.name} +${cfg.per}% = ${(P.trainerTalents[type]*cfg.per).toFixed(1)}% custou ${cost}`,2500);
  autoSave();
  if(typeof renderTrainerTalents==='function') renderTrainerTalents();
};
window.renderTrainerTalents = window.openTrainerTalents = function(){
  let scr = document.getElementById('screen-talentos');
  if(!scr){ scr=document.createElement('div'); scr.id='screen-talentos'; scr.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.95);z-index:999999;overflow:auto;padding:12px;'; document.body.appendChild(scr); }
  scr.style.display='block';
  let pts = P.trainerPoints||0;
  let html=`<div style="max-width:600px;margin:0 auto;background:#111;border:2px solid #00d0ff;border-radius:12px;padding:12px;"><div style="display:flex;justify-content:space-between;"><h2 style="color:#00d0ff;margin:0;">🧙 TALENTOS</h2><button onclick="document.getElementById('screen-talentos').style.display='none'" style="background:#833;color:#fff;border:none;padding:6px 12px;border-radius:6px;">X</button></div><div style="background:#000;padding:8px;border-radius:8px;margin:10px 0;color:#ffd700;font-size:12px;">Pontos: ${pts} | Shiny +0.1% max 20% | Outros +1% | Custo +5% por level</div>`;
  for(let k in TALENT_CONFIG){
    let cfg=TALENT_CONFIG[k]; let lvl=P.trainerTalents&&P.trainerTalents[k]?P.trainerTalents[k]:0; let buff=(lvl*cfg.per).toFixed(1); let cost=getTalentCost(k); let can=pts>=cost && parseFloat(buff)<cfg.max;
    html+=`<div style="display:flex;justify-content:space-between;align-items:center;background:#1a1a2e;border:1px solid #334;padding:8px;border-radius:8px;margin:6px 0;"><div><b style="color:#fff;">${cfg.name} +${cfg.per}%</b><br><span style="color:#888;font-size:10px;">Nv.${lvl} = ${buff}%/${cfg.max}% | Custo: ${cost}</span></div><button ${!can?'disabled':''} onclick="upgradeTalent('${k}')" style="background:${can?'#00d0ff':'#444'};color:${can?'#000':'#888'};border:none;padding:8px 12px;border-radius:6px;font-weight:900;">${parseFloat(buff)>=cfg.max?'MAX':`UPAR ${cost}`}</button></div>`;
  }
  html+=`</div>`; scr.innerHTML=html;
};

