POTION_DATA["Poção 100% HP"]={pct:100};

// --- POKÉDEX V24 - ANIMADA + STATS LV1 + MOVES OFICIAL + RESGATAR ---
function openPokedex(){
  document.getElementById('screen-pokedex').style.display='flex';
  if(!Object.keys(FULL_LEARNSET).length) loadFullLearnset().then(()=>renderPokedex());
  renderPokedex();
}
function closePokedex(){
  document.getElementById('screen-pokedex').style.display='none';
}

function renderPokedex(){
  let grid = document.getElementById('dex-grid');
  if(!grid) return;
  let search = (document.getElementById('dex-search')?.value||'').toLowerCase();
  let html = '';
  for(let id in ALL_POKE_NAMES){
    let name = ALL_POKE_NAMES[id];
    let tp = (TYPE_BY_ID_ALL[id]||TYPE_BY_ID_EXT[id]||'').toLowerCase();
    if(search &&!name.toLowerCase().includes(search) &&!id.includes(search) &&!tp.includes(search)) continue;
    let caught = (P.box.some(p=>p.id==id) || P.team.some(p=>p.id==id))? 'dex-caught' : '';
    let anim = getPokeAnim({id: parseInt(id)});
    html += `<div class="dex-card ${caught}" onclick="showDexDetail(${id})">
      <img src="${anim}" onerror="this.src='https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png'">
      <span class="dex-num">#${id}</span>
      <span class="dex-name">${name}</span>
    </div>`;
  }
  grid.innerHTML = html || "<div style='color:#666;grid-column:1/-1;text-align:center'>Nenhum encontrado</div>";
}

function showDexDetail(id){
  let panel = document.getElementById('dex-detail-panel');
  let name = ALL_POKE_NAMES[id] || ('Pokemon '+id);
  let tp = TYPE_BY_ID_ALL[id] || TYPE_BY_ID_EXT[id] || 'Normal';
  let types = tp.split('/').map(t=>`<span class="type-badge type-${t.trim().toLowerCase()}">${t.trim()}</span>`).join('');

  // STATS LVL 1 REAL
  let baseHp = calcBaseHpV14(1,1,false,false,parseInt(id));
  let baseAtk = calcBaseAtkV14(1,1,false,false,parseInt(id));
  let stage = getEvoStage? getEvoStage(parseInt(id)) : 1;
  let anim = getPokeAnim({id: parseInt(id)});

  // LISTA COMPLETA DE MOVES OFICIAL
  let fullMoves = getFullMoveList(parseInt(id), 100); // todos até 100
  fullMoves.sort((a,b)=> (a.lvl||1) - (b.lvl||1));

  let teamPoke = P.team[0];
  let teamMoveNames = new Set((teamPoke?.moves||[]).map(m=>m.name));

  let movesHtml = fullMoves.map(m=>{
    let has = teamMoveNames.has(m.name);
    return `<div class="move-card">
      <div>
        <div class="move-name">${m.name} <span class="move-lv">Lv.${m.lvl||1}</span></div>
        <div class="move-meta" style="color:${MOVE_COLORS[m.type]||'#888'};font-weight:900;">${m.type} • PWR ${m.power||0}</div>
      </div>
      <button class="btn-claim ${has?'claimed':'available'}" onclick="claimDexMove('${m.name.replace(/'/g,"\\'")}')">
        ${has?'✓ JÁ TEM':'RESGATAR'}
      </button>
    </div>`;
  }).join('') || "<div style='color:#666;font-size:11px;text-align:center'>Sem moves</div>";

  panel.innerHTML = `
    <img class="dex-detail-img" src="${anim}" onerror="this.src='https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png'">
    <div class="dex-detail-name">${name}</div>
    <div class="dex-detail-num">#${id} | Estágio ${stage}</div>
    <div class="dex-types">${types}</div>

    <div style="background:#0a0a12;border-radius:8px;padding:8px;margin:8px 0;">
      <div style="color:#ffd700;font-size:10px;font-weight:900;margin-bottom:4px;">📊 STATS LVL 1</div>
      <div class="stat-row"><div class="stat-label"><span>HP</span><span>${baseHp}</span></div><div class="stat-bar-bg"><div class="stat-bar-fill" style="width:${Math.min(100,baseHp)}%;background:#00ff88"></div></div></div>
      <div class="stat-row"><div class="stat-label"><span>ATK</span><span>${baseAtk}</span></div><div class="stat-bar-bg"><div class="stat-bar-fill" style="width:${Math.min(100,baseAtk*2)}%;background:#ff4444"></div></div></div>
      <div class="stat-row"><div class="stat-label"><span>Team Atual</span><span style="color:#00d0ff">${teamPoke?teamPoke.name+' Lv'+teamPoke.level:'Sem time'}</span></div></div>
    </div>

    <div style="color:#00d0ff;font-size:10px;font-weight:900;margin:10px 0 6px;letter-spacing:1px;">📜 TODOS OS MOVES - OFICIAL (LVL NECESSÁRIO)</div>
    <div style="max-height:260px;overflow:auto;padding-right:4px;">${movesHtml}</div>
  `;
}

function claimDexMove(moveName){
  let teamPoke = P.team[0];
  if(!teamPoke){ notif('❌ Sem Pokémon no time!'); return; }

  // pega o move oficial da Pokédex do POKÉMON QUE VOCÊ ESTÁ VENDO
  let detailPanel = document.getElementById('dex-detail-panel');
  let viewingId = null;
if(detailPanel && detailPanel._viewingId) viewingId = detailPanel._viewingId;
  if(!viewingId){
    // fallback: tenta pegar do id salvo no panel
    viewingId = teamPoke.id;
  }
  let allMovesViewed = getFullMoveList(parseInt(viewingId), 100);
  let moveObj = allMovesViewed.find(m=>m.name===moveName);
  if(!moveObj){ notif('❌ Move não encontrado!'); return; }

  // TRAVA DE LEVEL - O POKÉMON DO TIME TEM QUE TER O LEVEL DO MOVE
  if(teamPoke.level < (moveObj.lvl||1)){
    notif(`🔒 ${teamPoke.name} Lv.${teamPoke.level} precisa ser Lv.${moveObj.lvl} para resgatar ${moveName}!`, 3500);
    spawnFloat(`PRECISA LV.${moveObj.lvl}!`, "#ff4444");
    return;
  }

  if((teamPoke.moves||[]).some(m=>m.name===moveName)){
    notif(`ℹ️ ${teamPoke.name} já tem ${moveName}!`, 2500);
    return;
  }

  if(!teamPoke.moves) teamPoke.moves=[];
  if(!teamPoke.movePool) teamPoke.movePool=[];
  if(!teamPoke.movePool.some(m=>m.name===moveObj.name)) teamPoke.movePool.push(moveObj);

  if(teamPoke.moves.length < 4){
    teamPoke.moves.push(moveObj);
    notif(`✅ ${moveName} Lv.${moveObj.lvl} resgatado para ${teamPoke.name} Lv.${teamPoke.level}!`, 3000);
    autoSave(); loadMoveButtons(); renderTeam();
    showDexDetail(parseInt(viewingId));
  } else {
    notif(`⚠️ ${teamPoke.name} cheio! Escolha qual trocar por ${moveName}`);
    openMoveSwap(0,false);
    setTimeout(()=>{
      let pool = document.getElementById('move-swap-pool');
      if(pool){
        let btn = document.createElement('button');
        btn.innerHTML = `<b>${moveObj.name} ⭐ LVL ${moveObj.lvl}</b><br>${moveObj.type} PWR${moveObj.power}`;
        btn.style.cssText = "background:#00ff88;color:#000;border:2px solid #fff;padding:10px;border-radius:8px;font-weight:900;width:100%;grid-column:1/-1;";
        btn.onclick = ()=>{
          if(window._selCur===null){ notif("Selecione 1 move ativo acima!"); return; }
          teamPoke.moves[window._selCur]=moveObj;
          notif(`✅ ${teamPoke.name} aprendeu ${moveObj.name}!`);
          document.getElementById('screen-move-swap').style.display='none';
          autoSave(); loadMoveButtons(); renderTeam();
        };
        pool.prepend(btn);
      }
    },150);
  }
}

// salva o id que está vendo
let _oldShowDexDetail = showDexDetail;
showDexDetail = function(id){
  _oldShowDexDetail(id);
  let panel = document.getElementById('dex-detail-panel');
  if(panel) panel._viewingId = id;
}
