const MOVE_COLORS = {
  Grass:"#2d8a4e", Planta:"#2d8a4e",
  Fire:"#cc3a2b", Fogo:"#cc3a2b",
  Water:"#2a6bba", Agua:"#2a6bba",
  Electric:"#b8a000", Eletrico:"#b8a000",
  Normal:"#666", Voador:"#5a7ab0", Flying:"#5a7ab0",
  Poison:"#7a3da0", Venenoso:"#7a3da0",
  Ground:"#8a6a3a", Terra:"#8a6a3a",
  Psychic:"#c43a6a", Psiquico:"#c43a6a",
  Bug:"#7a8a2a", Inseto:"#7a8a2a",
  Rock:"#8a7a3a", Pedra:"#8a7a3a",
  Ghost:"#5a4a8a", Fantasma:"#5a4a8a",
  Dragon:"#4a3aab", Dragao:"#4a3aab",
  Steel:"#7a7a8a", Aco:"#7a7a8a",
  Fairy:"#c45a8a", Fada:"#c45a8a",
  Dark:"#4a3a3a", Noturno:"#4a3a3a",
  Fighting:"#aa3333", Lutador:"#aa3333",
  Ice:"#3ab0b0", Gelo:"#3ab0b0",
  Status:"#444"
};

window.loadMoveButtons = function(){
  const moveDiv = document.getElementById('move-buttons');
  if(!moveDiv || !P.team[0]) return;
  let poke = P.team[0];
  if(!poke.moves || poke.moves.length===0){
    poke.moves = getMovesForLevel(poke.id, poke.level);
  }
  moveDiv.innerHTML = '';
  moveDiv.className = 'move-grid';
  poke.moves.forEach(move=>{
    const btn = document.createElement('button');
    let col = MOVE_COLORS[move.type] || MOVE_COLORS[move.type?.split('/')[0]] || "#333";
    btn.innerHTML = `${move.name}<br><small>${move.type} • PWR ${move.power||0}</small>`;
    btn.style.cssText = `background:${col};border:2px solid #fff;color:#fff;padding:10px;border-radius:10px;font-weight:900;font-size:12px;box-shadow:0 0 10px ${col}99;cursor:pointer;`;
    btn.onclick = ()=>battleAction('move', move);
    moveDiv.appendChild(btn);
  });
};

