// --- V34 FINAL - BOSS/MEGA BLOQUEADO + CAPTURA 14% ---
window.tryCaptureBattle = function(ballName){
  if((P.inventory[ballName]||0)<=0){ notif('Sem balls!'); return; }

  if(window.isDungeonBoss || window.isDungeonMega){
    notif('❌ BOSS/MEGA não pode ser capturado! Só essência!', 3000);
    document.getElementById('screen-bag').style.display='none';
    document.getElementById('battle-log').textContent='❌ BOSS/MEGA não capturável!';
    return;
  }

  P.inventory[ballName]--; if(P.inventory[ballName]<=0) delete P.inventory[ballName];
  document.getElementById('screen-bag').style.display='none';
  window.bagBattleMode = null;

  let wild=battleData.wild;
  let hpPct=battleData.wildHp/battleData.wildMaxHp;
  let hpFactor=0.4+(1-hpPct)*1.0;
  let tier=getTier(wild.id, wild.shiny, wild.isMega, wild.isBoss);
  let cfg=TIER_CONFIG[tier]||{capMax:40};

  let maxCap = 0.5;
  let capBuff = getTotalBuff('cap');

  let baseChance = cfg.capMax * hpFactor * (BALL_DATA[ballName]?.chance||1) * (1/Math.sqrt(wild.rarity?.mult||1));
  let finalCap = Math.min(maxCap, baseChance * (1 + capBuff/100));

  if(Math.random()*100<finalCap){
    let pk=createCapturedPoke(wild.id,wild.rarity,wild.shiny);
    P.box.push(pk);
    notif(`✅ ${pk.name} [${tier}] ${baseChance.toFixed(2)}% +${capBuff}% = ${finalCap.toFixed(2)}%/${maxCap}%`,3500);
    endBattle(true); autoSave(); renderTeam();
  }else{
    notif(`❌ ${wild.name} escapou! ${baseChance.toFixed(2)}% +${capBuff}% = ${finalCap.toFixed(2)}%/${maxCap}%`,2000);
    document.getElementById('battle-log').textContent=`❌ Escapou! ${finalCap.toFixed(1)}%`;
    updateHUD();

    // GASTA TURNO - INIMIGO ATACA SE FALHAR
    setTimeout(() => {
        if(!battleData.wild || battleData.wild.hp <= 0) return;
        if(!P.team[0] || P.team[0].hp <= 0) return;

        document.getElementById('battle-log').textContent = `💢 ${battleData.wild.name} revidou!`;
        attackAnimation('enemy');

        let eDmg = Math.max(5, Math.floor((battleData.wild.level * 2.5) + Math.random()*10));
        P.team[0].hp = Math.max(0, P.team[0].hp - eDmg);
        spawnFloat(`-${eDmg}`, "#ff4444", 'player');
        updateBattleHP(); updateHUD();

        if(P.team[0].hp <= 0){
            document.getElementById('battle-log').textContent = `💀 ${P.team[0].name} desmaiou!`;
            setTimeout(()=>{if(typeof window.psyHandleBattleFaint==='function')window.psyHandleBattleFaint();else if(typeof window.psyOpenBattleSwitch==='function')window.psyOpenBattleSwitch(true);else endBattle(false)},800);
        }
        autoSave();
    }, 800);
  }
};
// ===== CORE FIX - BOOST 100 + RESET + EVO 40/60 =====
window.ensurePokeBase = function(p){
  if(!p) return;
  if(typeof p.resets==='undefined') p.resets=0;
  if(typeof p.boost==='undefined') p.boost=0;
  if(typeof p.evoMult==='undefined') p.evoMult=1;
  if(p.boost>100) p.boost=100;
  if(!p.movePool) p.movePool=getFullMoveList(p.id,p.level||1);
  if(!p.moves||!p.moves.length) p.moves=p.movePool.slice(-4);
};

window.recalcPoke = function(p){
  if(!p) return;
  ensurePokeBase(p);
  if(p.boost>100) p.boost=100;
  if(!p.evoMult) p.evoMult=1;
  let baseHp = calcBaseHpV14(p.level, p.rarity?.mult||1, p.shiny, p.isMega, p.id);
  let baseAtk = calcBaseAtkV14(p.level, p.rarity?.mult||1, p.shiny, p.isMega, p.id);
  let resetMult = 1 + p.resets*0.05;
  let boostMult = 1 + p.boost/100;
  let evoMult = p.evoMult;
  let formMult = (p.shiny && p.isMega)? 3 : 1;
  p.baseMaxHp = Math.floor(baseHp * resetMult * boostMult * evoMult * formMult);
  p.baseMaxAtk = Math.floor(baseAtk * resetMult * boostMult * evoMult * formMult);
  p.maxHp = Math.floor(p.baseMaxHp * (1+getTotalBuff('hp')/100));
  p.atk = Math.floor(p.baseMaxAtk * (1+getTotalBuff('dmg')/100));
  p.def = Math.floor(p.atk * 0.65);
  p.hp = Math.min(p.maxHp, p.hp||p.maxHp);
  if(p.hp<1) p.hp=p.maxHp;
};

window.createCapturedPoke = function(id, rarity, shiny, isPremier, isMega){
  let tier = getTier(id,!!shiny,!!isMega, false);
  if(!rarity) rarity = rollRarity(tier);
  let bh = calcBaseHpV14(1, rarity.mult,!!shiny,!!isMega, id);
  let ba = calcBaseAtkV14(1, rarity.mult,!!shiny,!!isMega, id);
  let all = getFullMoveList(id, 1);
  return {
    id, name: getPokeName(id),
    type: TYPE_BY_ID_ALL[id]||"Normal",
    rarity, shiny:!!shiny, premier:!!isPremier, isMega:!!isMega,
    level:1, exp:0, maxExp:100,
    baseMaxHp:bh, baseMaxAtk:ba,
    maxHp: Math.floor(bh*(1+getTotalBuff('hp')/100)),
    hp: Math.floor(bh*(1+getTotalBuff('hp')/100)),
    atk: Math.floor(ba*(1+getTotalBuff('dmg')/100)),
    boost:0, resets:0, evoMult:1,
    moves: all.slice(-4), movePool: all, tier: tier
  };
};

window.resetPokemon=function(idx, isBox){
  let poke = isBox? P.box[idx] : P.team[idx];
  if(!poke) return;
  if(poke.level < 100){ notif(`🔒 Só Lv100! Atual Lv.${poke.level}`,3000); return; }
  let cost = 100000000;
  if(!confirm(`♻ RESETAR ${poke.name} Lv100?\n\nReset atual: ${poke.resets||0} (+${(poke.resets||0)*5}%)\nDepois: ${poke.resets+1} (+${(poke.resets+1)*5}%)\nCusto: 100M\nVoltar pro Lv1 com +5% PERMANENTE?`)) return;
  if(P.gold < cost){ notif(`❌ Precisa 100M! Tem ${P.gold.toLocaleString()}`); return; }
  P.gold-=cost;
  poke.resets=(poke.resets||0)+1;
  poke.level=1; poke.exp=0; poke.maxExp=100;
  poke.moves=getMovesForLevel(poke.id, 1);
  recalcPoke(poke);
  notif(`♻ ${poke.name} RESET ${poke.resets}! +${poke.resets*5}% PERMANENTE!`,5000);
  try{ spawnFloat(`♻ RESET ${poke.resets} +${poke.resets*5}%`, "#00ffff"); }catch(e){}
  autoSave(); updateHUD(); renderTeam();
  if(window.currentDetailPoke) openPokeDetail(idx, isBox);
};

let _oldDetailReset=openPokeDetail;
openPokeDetail=function(idx, isBox){
  _oldDetailReset(idx, isBox);
  let content=document.getElementById('detail-poke-content');
  if(!content) return;
  let oldBtn=document.getElementById('btn-reset-poke');
  if(oldBtn) oldBtn.remove();
  let poke=isBox? P.box[idx] : P.team[idx];
  let resets=poke.resets||0;
  let btn=document.createElement('button');
  btn.id='btn-reset-poke';
  btn.innerHTML=poke.level>=100?`♻ RESET LV100 → LV1<br><small>Resets: ${resets} (+${resets*5}%) → ${resets+1} (+${(resets+1)*5}%) | 💰 100M</small>`:`🔒 RESET LIBERA NO LV100 (Lv.${poke.level})`;
  btn.style.cssText=`width:100%; margin-top:10px; background:${poke.level>=100?'linear-gradient(90deg,#ff0055,#ff6600)':'#444'}; color:#fff; border:2px solid #fff; padding:12px; border-radius:10px; font-weight:900; cursor:${poke.level>=100?'pointer':'not-allowed'};`;
  btn.onclick=()=>{ if(poke.level>=100) resetPokemon(idx, isBox); };
  content.appendChild(btn);
};

function curarTimeCity(){
  if(!P.team ||!P.team.length) return;
  P.team.forEach(p=>{ ensurePokeBase(p); recalcPoke(p); p.hp = p.maxHp; });
  if(P.team[0]){ P.pokemon = P.team[0]; P.hp = P.team[0].hp; P.maxHp = P.team[0].maxHp; }
  updateHUD(); try{ renderTeam(); }catch(e){}
  notif('💚 Time curado!',1500); autoSave();
}

console.log('🔥 PATCH MEGA V3 FIX REAL');
const TIER_SHINY_COST = Object.freeze({E:10,D:20,C:30,B:40,A:50,S:60,SS:70,SSS:80,UR:200,"UR+":300});
if(!P.inventory["Boost Stone"]) P.inventory["Boost Stone"]=0;
if(!P.inventory["Shiny Stone"]) P.inventory["Shiny Stone"]=0;
if(!P.inventory["Fragmento Mega Stone"]) P.inventory["Fragmento Mega Stone"]=0;
if(!P.inventory["Ultra Ball"]) P.inventory["Ultra Ball"]=0;
function getTierCost(pokeId){
  const id=Number(pokeId?.id ?? pokeId);
  const tier = typeof getTier==='function'?getTier(id,false,false,false):'E';
  return Number(TIER_SHINY_COST[tier]??10);
}
/* Fonte única para custo de Shiny Stone no Time/Box e nas evoluções Shiny. */
window.TIER_SHINY_COST=TIER_SHINY_COST;
window.getTierCost=getTierCost;
window.getShinyStoneCost=function(pokeOrId){return getTierCost(pokeOrId);};

window.calcDetailedStats = function(poke){
  if(typeof ensureTrainerData==='function') ensureTrainerData();
  poke = poke || {};
  let lvl = poke.level || 1;
  let mult = poke.rarity?.mult || 1;
  let boost = poke.boost||0;
  let resets = poke.resets||0;
  let evoMult = poke.evoMult||1;
  let realBaseHp = calcBaseHpV14(lvl, mult, poke.shiny, poke.isMega, poke.id);
  let realBaseAtk = calcBaseAtkV14(lvl, mult, poke.shiny, poke.isMega, poke.id);
  let hpBuff = getTotalBuff('hp');
  let dmgBuff = getTotalBuff('dmg');
  let boostMult = 1 + boost/100;
  let resetMult = 1 + resets*0.05;
  let formMult = (poke.shiny && poke.isMega)? 3 : 1;
  let afterBoostHp = Math.floor(realBaseHp * boostMult * resetMult * evoMult * formMult);
  let afterBoostAtk = Math.floor(realBaseAtk * boostMult * resetMult * evoMult * formMult);
  let finalHp = Math.floor(afterBoostHp * (1+hpBuff/100));
  let finalAtk = Math.floor(afterBoostAtk * (1+dmgBuff/100));
  let baseDef = Math.floor(realBaseAtk * 0.65);
  let finalDef = Math.floor(finalAtk * 0.65);
  return {
    baseHp: realBaseHp, afterBoostHp, finalHp, hpBuff,
    baseAtk: realBaseAtk, afterBoostAtk, finalAtk, dmgBuff,
    baseDef, finalDef,
    baseCrit:5, finalCrit:5+(getTotalBuff('crit')||0),
    critBuff:getTotalBuff('crit')||0,
    capBuff:getTotalBuff('cap')||0,
    goldBuff:getTotalBuff('gold')||0,
    xpBuff:getTotalBuff('xp')||0,
    dropBuff:getTotalBuff('drop')||0,
    shinyBuff:getTotalBuff('shiny')||0,
    boost, resets, evoMult, boostMult, resetMult
  };
};
function tryGlobalDrops(wildPoke){
  ensureTrainerData();
  let dropBuff = getTotalBuff('drop');
  let ubFinal = Math.min(5, 0.2 * (1+dropBuff/100));
  if(Math.random()*100 < ubFinal){
    P.inventory["Ultra Ball"]=(P.inventory["Ultra Ball"]||0)+1;
    notif(`🔴 Ultra Ball! ${ubFinal.toFixed(3)}%/5%`,3500);
    spawnFloat("+Ultra Ball", "#ffff00");
  }
  let bsFinal = Math.min(1, 0.01 * (1+dropBuff/100));
  if(Math.random()*100 < bsFinal){
    P.inventory["Boost Stone"]=(P.inventory["Boost Stone"]||0)+1;
    notif(`💎 Boost Stone!`,3500);
    spawnFloat("+Boost Stone", "#00ffff");
  }
  if(wildPoke.shiny){
    let ssFinal = Math.min(0.5, 0.02 * (1+dropBuff/100));
    if(Math.random()*100 < ssFinal){
      P.inventory["Shiny Stone"]=(P.inventory["Shiny Stone"]||0)+1;
      notif(`✨ Shiny Stone!`,4000);
    }
  }
  if(window.isDungeonMega){
    /* Restored original Mega Dungeon fragment roll: base 0.10%, scaling with Drop up to 1.00%. */
    const mfFinal=dropBuff>=300?1:0.1+(Math.max(0,dropBuff)/300)*0.9;
    if(Math.random()*100<mfFinal){
      P.inventory["Fragmento Mega Stone"]=(P.inventory["Fragmento Mega Stone"]||0)+1;
      notif(`🔷 Fragmento Mega Stone obtido!`,4000);
    }
  }
}
if(!window._endBattlePatched){
  window._endBattlePatched=true;
  let _endOld = window.endBattle;
  window.endBattle = function(won){
    if(won && window.battleData && window.battleData.wild) tryGlobalDrops(window.battleData.wild);
    _endOld(won);
  }
}
window.useBoostStone = function(idx,isBox){
  let poke = isBox?P.box[idx]:P.team[idx];
  if((P.inventory["Boost Stone"]||0)<=0) return notif("❌ Sem Boost Stone");
  if(poke.boost>=100) return notif("❌ Máx 100/100");
  P.inventory["Boost Stone"]--; if(P.inventory["Boost Stone"]<=0) delete P.inventory["Boost Stone"];
  poke.boost=(poke.boost||0)+1; recalcPoke(poke);
  notif(`💪 ${poke.name} boost ${poke.boost}`,2500);
  autoSave(); renderTeam(); if(currentDetailPoke) openPokeDetail(idx,isBox);
}
window.useShinyStone = function(idx,isBox){
  let poke = isBox?P.box[idx]:P.team[idx];
  if((P.inventory["Shiny Stone"]||0)<=0) return notif("❌ Sem Shiny Stone");
  let costTier = getTierCost(poke.id);

  if(!poke.shiny){
    if((P.inventory["Shiny Stone"]||0) < costTier) return notif(`❌ Precisa ${costTier}`);
    if(!confirm(`Transformar ${poke.name} em SHINY? Custo: ${costTier}`)) return;
    P.inventory["Shiny Stone"]-=costTier;
    poke.shiny=true;
    poke.shinyCostInvested=costTier;
    recalcPoke(poke);
  } else {
    let evo = EVOLUTION_MAP[poke.id];
    if(!evo) return notif("❌ Forma final");
    let nextId = evo.to;
    let nextTierCost = getTierCost(nextId);
    // FIX: paga só o próximo tier, não total de novo
    let totalCost = nextTierCost;

    if((P.inventory["Shiny Stone"]||0) < totalCost) return notif(`❌ Precisa ${totalCost}`);
    if(!confirm(`Evoluir Shiny para ${getPokeName(nextId)}? Custo ${totalCost} (+${!!EVOLUTION_MAP[nextId]?40:60}%)`)) return;

    P.inventory["Shiny Stone"]-=totalCost;

    let oldEvo = poke.evoMult||1;
    let isSecond =!!EVOLUTION_MAP[nextId];
    let add = isSecond? 1.4 : 1.6;

    // === FIX SPLASH SHINY ===
    poke.id=nextId;
    poke.name=getPokeName(nextId);
    poke.type=TYPE_BY_ID_ALL[nextId]||TYPE_BY_ID_FULL[nextId]||poke.type;
    poke.shiny=true; // GARANTE SHINY
    poke.isMega=false; // tira mega se tinha
    poke.shinyCostInvested=(poke.shinyCostInvested||costTier)+totalCost;
    poke.evoMult = oldEvo * add;
    poke.level=1; poke.exp=0; poke.maxExp=100;
    poke.moves=getMovesForLevel(poke.id,1);
    poke.movePool=getFullMoveList(poke.id,1);

    // limpa cache da imagem antiga
    if(typeof imgCache!== 'undefined'){
        delete imgCache[poke.id+'_s'];
        delete imgCache[nextId+'_s'];
    }

    recalcPoke(poke);
    spawnFloat(`✨ SHINY EVO +${isSecond?40:60}% x${poke.evoMult.toFixed(2)}`, "#ff00ff");
  }

  if(P.inventory["Shiny Stone"]<=0) delete P.inventory["Shiny Stone"];
  autoSave();

  // força render com getPokeAnim e não raw/github
  renderTeam();
  if(currentDetailPoke) openPokeDetail(idx,isBox);
  updateHUD();
}

