const _oldDetailBoost = openPokeDetail;
window.openPokeDetail = function(idx,isBox){
  _oldDetailBoost(idx,isBox);
  let content=document.getElementById('detail-poke-content'); if(!content) return;
  if(document.getElementById('poke-boost-info')) document.getElementById('poke-boost-info').remove();
  let poke=isBox?P.box[idx]:P.team[idx]; if(!poke) return;

  let evo = EVOLUTION_MAP[poke.id];
  let canEvo = evo && poke.level >= (evo.lvl||16);

  let div=document.createElement('div'); div.id='poke-boost-info';
  div.style.cssText='background:#000;padding:8px;border-radius:8px;margin:8px 0;border:1px solid #00ffff;display:grid;grid-template-columns:1fr 1fr;gap:6px;';

  let megaCost = poke.shiny? 150 : 50;
  let megaLabel = poke.shiny? `✨ SHINY MEGA (${P.inventory["Fragmento Mega Stone"]||0}/${megaCost})` : `MEGA (${P.inventory["Fragmento Mega Stone"]||0}/${megaCost})`;

  div.innerHTML=`
    <button onclick="useBoostStone(${idx},${isBox})" style="background:#00ffff;color:#000;border:none;padding:10px;border-radius:6px;font-weight:900;">💪 BOOST (${P.inventory["Boost Stone"]||0})<br><small>${poke.boost||0}/100</small></button>
    <button onclick="useShinyStone(${idx},${isBox})" style="background:#ff00ff;color:#fff;border:none;padding:10px;border-radius:6px;font-weight:900;">✨ SHINY (${P.inventory["Shiny Stone"]||0})</button>
    <button onclick="useMegaStone(${idx},${isBox})" style="background:${poke.isMega?'#444':'#00aaff'};color:#fff;border:none;padding:10px;border-radius:6px;font-weight:900;grid-column:${canEvo?'1':'1 / -1'};" ${poke.isMega?'disabled':''}>🔷 ${poke.isMega?'JÁ É MEGA':megaLabel}<br><small>${poke.shiny?'150 Frag':'50 Frag'}</small></button>
    ${canEvo?`<button onclick="tryEvolve(${idx},${isBox})" style="background:#ffaa00;color:#000;border:none;padding:10px;border-radius:6px;font-weight:900;">⬆ EVOLUIR<br><small>p/ ${getPokeName(evo.to)} Lv.${evo.lvl||16}</small></button>`:''}
  `;
  content.prepend(div);
}

// evoluir fora da bag
window.tryEvolve = function(idx,isBox){
  let poke = isBox?P.box[idx]:P.team[idx];
  let evo = EVOLUTION_MAP[poke.id];
  if(!evo) return notif("❌ Sem evolução");
  if(poke.level < (evo.lvl||16)) return notif(`🔒 Precisa Lv.${evo.lvl}`);
  if(!confirm(`Evoluir ${poke.name} para ${getPokeName(evo.to)}?`)) return;
  let oldId = poke.id;
  poke.id = evo.to;
  poke.name = getPokeName(evo.to);
  poke.type = TYPE_BY_ID_ALL[evo.to]||TYPE_BY_ID_FULL[evo.to]||poke.type;
  // Evolução deve atualizar os movimentos automaticamente; abrir a Pokédex não
  // pode ser necessário para receber os ataques do novo estágio/tipagem.
  poke.movePool = getFullMoveList(poke.id, poke.level||1);
  poke.moves = getMovesForLevel(poke.id, poke.level||1);
  poke.evoMult = (poke.evoMult||1) * (EVOLUTION_MAP[evo.to]?1.4:1.6);
  recalcPoke(poke);
  if(typeof imgCache!=='undefined'){ delete imgCache[oldId]; delete imgCache[evo.to]; delete imgCache[oldId+'_s']; }
  notif(`⬆ ${poke.name} evoluiu! x${poke.evoMult.toFixed(2)}`,4000);
  autoSave(); renderTeam(); openPokeDetail(idx,isBox);
}
