/* ============================================================
   POKÉ CARDS BATTLE 3.0 — dynamic map, 3 action cards only.
   ============================================================ */
window.cgStartStage=function(){
  ensureCardData();
  if(!P.cardGame.deck.length)return notif('Monte seu deck primeiro!');
  const stage=P.cardGame.stage||1;
  const deck=P.cardGame.deck.slice(0,3).map(k=>P.cardGame.collection[k]).filter(Boolean);
  if(!deck.length)return notif('Escolha pelo menos 1 Pokémon no deck.');
  let ids=Object.keys(ALL_POKE_NAMES||{}).map(Number).filter(psyEligibleEggId);
  const rank={E:0,D:1,C:2,B:3,A:4,S:5,SS:6,SSS:7,UR:8,"UR+":9};
  const need=stage>=18?'SS':stage>=14?'S':stage>=10?'A':stage>=6?'B':stage>=3?'C':'D';
  let pool=ids.filter(id=>rank[getTier(id,false,false,false)||'E']>=rank[need]);if(!pool.length)pool=ids;
  const enemyId=pool[Math.floor(Math.random()*pool.length)],enemyTier=getTier(enemyId,false,false,false)||'E';
  const partyHp=Math.floor(450+deck.reduce((s,c)=>s+cg2Power(c),0)*.28);
  const enemyHp=Math.floor((420*Math.pow(1.20,stage-1))*({E:1,D:1.1,C:1.25,B:1.45,A:1.7,S:2,SS:2.35,SSS:2.8,UR:3.3}[enemyTier]||1));
  window.cgBattleState={stage,enemyId,enemyTier,enemyHp,enemyMax:enemyHp,playerHp:partyHp,playerMax:partyHp,
    energy:3,maxEnergy:3,turn:1,deck,buffs:{atk:0,def:0},actionsUsed:0};
  cgDrawBattle();
};
window.cgDrawBattle=function(){
  const s=cgBattleState,c=document.getElementById('cg-content');if(!s||!c)return;
  const hero=s.deck[(s.turn-1)%s.deck.length]||s.deck[0];
  const enemyPct=Math.max(0,s.enemyHp/s.enemyMax*100),playerPct=Math.max(0,s.playerHp/s.playerMax*100);
  const tc=CG_TIER_COLOR[s.enemyTier]||'#888';
  c.innerHTML=`<div class="cg-map">
    <div class="cg-enemy-zone">
      <div class="cg-hpbox"><b style="color:${tc}">${getPokeName(s.enemyId)} • ${s.enemyTier}</b><div class="cg-bar"><div class="cg-fill" style="width:${enemyPct}%"></div></div>${Math.max(0,s.enemyHp).toLocaleString()} / ${s.enemyMax.toLocaleString()} HP</div>
      <img class="cg-battle-sprite cg-enemy-sprite aura-${s.enemyTier}" src="${getRealSprite({id:s.enemyId})}">
    </div>
    <div class="cg-player-zone">
      <img class="cg-battle-sprite" src="${getRealSprite({id:hero.id})}">
      <div class="cg-hpbox"><b>${getPokeName(hero.id)}</b> • PWR ${cg2Power(hero).toLocaleString()}<div class="cg-bar"><div class="cg-fill" style="width:${playerPct}%"></div></div>${Math.max(0,s.playerHp).toLocaleString()} / ${s.playerMax.toLocaleString()} HP ${s.buffs.atk?` • ⚔ +${s.buffs.atk}%`:''}${s.buffs.def?` • 🛡 +${s.buffs.def}%`:''}</div>
    </div>
    <div class="cg-energy-orb">${s.energy}</div>
    <div class="cg-action-hand">
      <button class="cg-action-card attack" ${s.energy<=0?'disabled':''} onclick="cgUseAction('attack')"><div class="ico">⚔️</div><strong>ATAQUE</strong><div>Dano baseado no Tier e PWR do Pokémon ativo.</div><small>⚡ 1</small></button>
      <button class="cg-action-card heal" ${s.energy<=0?'disabled':''} onclick="cgUseAction('heal')"><div class="ico">💚</div><strong>CURAR</strong><div>Recupera 16–24% do Nexus. Menos eficiente se repetida.</div><small>⚡ 1</small></button>
      <button class="cg-action-card buff" ${s.energy<=0?'disabled':''} onclick="cgUseAction('buff')"><div class="ico">🛡️</div><strong>BUFF</strong><div>+18% ATK e +12% defesa por 2 turnos.</div><small>⚡ 1</small></button>
    </div>
    <button class="cg-ready" onclick="cgEndTurn()">READY / TURNO</button>
  </div>`;
  psyDecorateAllPokemonImages(c);
};
window.cgUseAction=function(type){
  const s=cgBattleState;if(!s||s.energy<=0)return;
  const hero=s.deck[(s.turn-1)%s.deck.length]||s.deck[0];s.energy--;s.actionsUsed++;
  if(type==='attack'){
    let dmg=cg2Power(hero)*(0.72+Math.random()*.22)*(1+s.buffs.atk/100);
    s.enemyHp-=Math.floor(dmg);
    if(s.enemyHp<=0)return cgWinStage();
  }else if(type==='heal'){
    const repeat=Math.max(0,s.actionsUsed-1),pct=Math.max(.10,.22-repeat*.025);
    s.playerHp=Math.min(s.playerMax,s.playerHp+Math.floor(s.playerMax*pct));
  }else{
    s.buffs.atk=Math.min(54,s.buffs.atk+18);s.buffs.def=Math.min(36,s.buffs.def+12);
  }
  cgEnemyCounter();if(s.playerHp<=0)return cgLoseStage();cgDrawBattle();
};
function cgEnemyCounter(){
  const s=cgBattleState;if(!s)return;
  const tr={E:1,D:1.08,C:1.16,B:1.27,A:1.4,S:1.55,SS:1.72,SSS:1.92,UR:2.15}[s.enemyTier]||1;
  let dmg=Math.floor(20*Math.pow(1.13,s.stage-1)*tr*(1-s.buffs.def/100));
  s.playerHp-=Math.max(4,dmg);
}
window.cgEndTurn=function(){
  const s=cgBattleState;if(!s)return;
  /* enemy gets one extra attack if player ends early */
  if(s.energy>0)cgEnemyCounter();
  if(s.playerHp<=0)return cgLoseStage();
  s.turn++;s.energy=s.maxEnergy;s.actionsUsed=0;s.buffs.atk=Math.max(0,s.buffs.atk-9);s.buffs.def=Math.max(0,s.buffs.def-6);cgDrawBattle();
};

/* Collection deck max = 3 for missions */
window.cgToggleDeck=function(id){
  ensureCardData();const k=String(id),d=P.cardGame.deck;const i=d.indexOf(k);
  if(i>=0)d.splice(i,1);else if(d.length<3)d.push(k);else return notif('Missões usam no máximo 3 Pokémon no deck.');
  autoSave();renderCardTab('collection');
};
window.cgAutoDeck=function(){
  const a=Object.values(P.cardGame.collection).sort((x,y)=>cg2Power(y)-cg2Power(x)).slice(0,3);
  P.cardGame.deck=a.map(x=>String(x.id));autoSave();renderCardTab('collection');
};
const cgCollectionOld=window.cgRenderCollection;
window.cgRenderCollection=function(c){
  const list=Object.values(P.cardGame.collection||{}).sort((a,b)=>cg2Power(b)-cg2Power(a));
  c.innerHTML=`<div style="display:flex;justify-content:space-between;margin-bottom:8px"><div><b>DECK DE MISSÃO ${P.cardGame.deck.length}/3</b><div class="psy-desc">Escolha até 3 Pokémon. Eles alternam durante a luta.</div></div><button onclick="cgAutoDeck()">AUTO DECK</button></div><div class="cardgame-grid">${list.map(card=>cg2CardHtml(card,`cgToggleDeck(${card.id})`)).join('')}</div>`;
};

