/* ============================================================
   TIER / RARITY BALANCE HOTFIX
   - Tier defines the minimum rarity deterministically.
   - SS starts at Pika das Galáxias.
   - Level 1 SS floor: 5,000 HP / 2,000 ATK.
   - Existing saves are migrated automatically.
   ============================================================ */
window.PSY_TIER_MIN_RARITY = {
  E:"Lixo", D:"Quase Lixo", C:"Nice", B:"Belezura", A:"Lêndea",
  S:"Bombado", SS:"Pika das Galáxias", SSS:"DEUS", UR:"CRIADOR",
  "UR+":"VOID", "UR++":"OBLIVION"
};
window.PSY_TIER_RARITY_WINDOW = {
  E:["Lixo","Quase Lixo"],
  D:["Quase Lixo","Nice"],
  C:["Nice","Belezura"],
  B:["Belezura","Lêndea"],
  A:["Lêndea","Bombado"],
  S:["Bombado","Pika das Galáxias"],
  SS:["Pika das Galáxias","DEUS"],
  SSS:["DEUS","CRIADOR"],
  UR:["CRIADOR","VOID"],
  "UR+":["VOID","OBLIVION"],
  "UR++":["OBLIVION"]
};

/* Floors are the BASE stats at Pokémon Lv.1 before trainer/world buffs.
   They scale smoothly upward with Pokémon level. */
window.PSY_TIER_STAT_FLOORS = {
  E:   {hp:80,    atk:25},
  D:   {hp:180,   atk:60},
  C:   {hp:420,   atk:145},
  B:   {hp:850,   atk:320},
  A:   {hp:1600,  atk:650},
  S:   {hp:2800,  atk:1100},
  SS:  {hp:5000,  atk:2000},
  SSS: {hp:9000,  atk:3800},
  UR:  {hp:15000, atk:6500},
  "UR+":{hp:24000,atk:10500},
  "UR++":{hp:38000,atk:17000},
  SP:{hp:56000,atk:25500}
};

function psyFindRarityByName(name){
  return (window.RARITIES||[]).find(r=>r.n===name)
    || Object.values(window.PSY_RARITY_REBORN||{}).find(r=>r.n===name)
    || {n:name||"Lixo",color:"#888",mult:1,cap:.5};
}

function psyMinimumRarityForTier(tier){
  return {...psyFindRarityByName(PSY_TIER_MIN_RARITY[tier]||"Lixo")};
}

function psyEnforceTierRarity(p){
  if(!p || !p.id) return p;
  const tier=p.forceTier||getTier(p.id,!!p.shiny,!!p.isMega,!!p.isBoss);
  p.tier=tier;

  /* Special forms use the Tier window too. A default is only supplied when the Pokémon has no quality yet. */
  const special=psyRarityForPokemon?.(p.id,!!p.shiny,!!p.isMega,!!p.isBoss);
  if(special&&!p.rarity)p.rarity={...special};

  const names=PSY_TIER_RARITY_WINDOW?.[tier]||[PSY_TIER_MIN_RARITY[tier]||"Lixo"];
  const allowed=names.map(psyFindRarityByName).filter(Boolean);
  const min=allowed[0]||psyMinimumRarityForTier(tier),max=allowed[allowed.length-1]||min;
  if(!p.rarity)p.rarity={...min};
  else if(Number(p.rarity.mult||0)<Number(min.mult||1))p.rarity={...min};
  else if(Number(p.rarity.mult||0)>Number(max.mult||min.mult||1))p.rarity={...max};
  else if(!names.includes(p.rarity.n)){
    p.rarity={...(Number(p.rarity.mult||0)<=Number(min.mult||1)?min:max)};
  }
  return p;
}

/* Random rarity still exists, but can NEVER fall below the Tier floor. */
window.rollRarity=function(tier){
  tier=tier||"E";
  const min=psyMinimumRarityForTier(tier);
  const forbidden=new Set(["VOID","OBLIVION","CRIADOR"]);
  const eligible=(window.RARITIES||[]).filter(r=>
    !forbidden.has(r.n) && Number(r.mult||0)>=Number(min.mult||1) && Number(r.chance||0)>0
  );
  if(!eligible.length) return {...min};

  const total=eligible.reduce((s,r)=>s+Number(r.chance||0),0);
  let roll=Math.random()*total,acc=0;
  for(const r of eligible){
    acc+=Number(r.chance||0);
    if(roll<=acc) return {...r};
  }
  return {...min};
};

function psyTierLevelScale(level){
  level=Math.max(1,Number(level)||1);
  /* Gentle scaling: level matters, but Tier remains the main identity. */
  return 1 + (level-1)*0.075;
}

/* Replace recalc with a single authoritative version. */
window.recalcPoke=function(p){
  if(!p)return;
  ensurePokeBase(p);
  psyEnforceTierRarity(p);

  p.level=Math.max(1,Number(p.level)||1);
  p.boost=Math.max(0,Math.min(100,Number(p.boost)||0));
  p.resets=Math.max(0,Number(p.resets)||0);
  p.evoMult=Math.max(1,Number(p.evoMult)||1);

  const oldMax=Math.max(1,Number(p.maxHp)||1);
  const oldHp=Math.max(0,Number(p.hp)||oldMax);
  const hpRatio=Math.max(0,Math.min(1,oldHp/oldMax));

  const tier=p.tier||getTier(p.id,!!p.shiny,!!p.isMega,!!p.isBoss);
  const floorCfg=PSY_TIER_STAT_FLOORS[tier]||PSY_TIER_STAT_FLOORS.E;
  const levelScale=psyTierLevelScale(p.level);

  /* Formula result */
  let formulaHp=calcBaseHpV14(p.level,p.rarity?.mult||1,!!p.shiny,!!p.isMega,p.id);
  let formulaAtk=calcBaseAtkV14(p.level,p.rarity?.mult||1,!!p.shiny,!!p.isMega,p.id);

  /* Guaranteed Tier floor */
  let tierHp=Math.floor(floorCfg.hp*levelScale);
  let tierAtk=Math.floor(floorCfg.atk*levelScale);

  let baseHp=Math.max(formulaHp,tierHp);
  let baseAtk=Math.max(formulaAtk,tierAtk);

  const resetMult=1+p.resets*(Number(p.id)===54?0.10:0.05);
  const boostMult=1+p.boost/100;
  const evoMult=p.evoMult;

  p.baseMaxHp=Math.floor(baseHp*resetMult*boostMult*evoMult);
  p.baseMaxAtk=Math.floor(baseAtk*resetMult*boostMult*evoMult);

  p.maxHp=Math.floor(p.baseMaxHp*(1+getTotalBuff('hp')/100));
  p.atk=Math.floor(p.baseMaxAtk*(1+getTotalBuff('dmg')/100));
  p.def=Math.floor(p.atk*0.65);

  /* Preserve current HP percentage when recalculating. */
  p.hp=Math.max(1,Math.min(p.maxHp,Math.floor(p.maxHp*hpRatio)));
};

/* Captures and starters immediately receive the correct Tier floor. */
const psyTierCreateOld=window.createCapturedPoke;
window.createCapturedPoke=function(id,rarity,shiny,isPremier,isMega){
  const tier=getTier(id,!!shiny,!!isMega,false);
  const special=psyRarityForPokemon?.(id,!!shiny,!!isMega,false);
  const min=psyMinimumRarityForTier(tier);
  if(!rarity && special) rarity={...special};
  if(!rarity || Number(rarity.mult||0)<Number(min.mult||1)) rarity={...min};

  const p=psyTierCreateOld(id,rarity,shiny,isPremier,isMega);
  psyEnforceTierRarity(p);
  recalcPoke(p);
  return p;
};

function psyMigrateTierBalance(){
  const all=[...(P?.team||[]),...(P?.box||[])];
  all.forEach(p=>{
    psyEnforceTierRarity(p);
    recalcPoke(p);
  });
  if(P?.team?.[0]){
    P.pokemon=P.team[0];
    P.hp=P.team[0].hp;
    P.maxHp=P.team[0].maxHp;
  }
  try{updateHUD()}catch(e){}
  try{renderTeam()}catch(e){}
  try{autoSave()}catch(e){}
}

setTimeout(psyMigrateTierBalance,500);
setTimeout(psyMigrateTierBalance,1800);



/* ============================================================
   FINAL STABILITY PATCH
   - rebuilds main menu into real compact square grids
   - X is always top-right
   - removes sandbox confirm() dependency from Shiny/Mega
   - fixes tutorial insertBefore NotFoundError
   - removes blocked GitHub fallback requests
   ============================================================ */

/* ---------- Main menu rebuild ---------- */
function psyBuildCompactMainMenu(){
  const menu=document.getElementById('menu');
  if(!menu || menu.dataset.compactFinal==='1') return;
  menu.dataset.compactFinal='1';

  const allButtons=[...menu.querySelectorAll(':scope > button, :scope > div > button')];

  const featureMatchers=[
    'BOLSA','TIME / BOX','POKÉ CARDS','CONQUISTAS','EGG CENTER','CASH SHOP','TALENTOS DO TREINADOR'
  ];
  const featureButtons=[];
  for(const label of featureMatchers){
    const b=allButtons.find(x=>(x.textContent||'').toUpperCase().includes(label));
    if(b && !featureButtons.includes(b)) featureButtons.push(b);
  }

  const saveMatchers=['SALVAR','CARREGAR','BAIXAR SAVE.PSY','CARREGAR ARQUIVO.PSY'];
  const saveButtons=[];
  for(const label of saveMatchers){
    const b=allButtons.find(x=>{
      const t=(x.textContent||'').trim().toUpperCase();
      if(label==='CARREGAR') return t==='📂 CARREGAR'||t==='CARREGAR';
      return t.includes(label);
    });
    if(b && !saveButtons.includes(b)) saveButtons.push(b);
  }

  const featureGrid=document.createElement('div');
  featureGrid.className='psy-main-grid';
  featureButtons.forEach(b=>{
    b.removeAttribute('style');
    featureGrid.appendChild(b);
  });

  const saveGrid=document.createElement('div');
  saveGrid.className='psy-save-grid';
  saveButtons.forEach(b=>{
    b.removeAttribute('style');
    saveGrid.appendChild(b);
  });

  /* Remove now-empty legacy wrappers. */
  [...menu.children].forEach(el=>{
    if(el.tagName==='DIV' && el.id!=='boxPokemon' && !el.children.length && !(el.textContent||'').trim()) el.remove();
  });

  const box=document.getElementById('boxPokemon');
  if(box) box.insertAdjacentElement('afterend',featureGrid);
  else menu.appendChild(featureGrid);
  menu.appendChild(saveGrid);

  /* Hide the old bottom close. */
  const oldClose=[...menu.querySelectorAll('button')].find(b=>(b.textContent||'').trim().toUpperCase()==='FECHAR');
  if(oldClose) oldClose.classList.add('psy-old-main-close');

  /* Create reliable top X. */
  if(!menu.querySelector('.psy-main-menu-x')){
    const x=document.createElement('button');
    x.type='button';
    x.className='psy-main-menu-x';
    x.textContent='×';
    x.title='Fechar menu';
    x.setAttribute('aria-label','Fechar menu');
    x.addEventListener('click',()=>toggleMenu());
    menu.appendChild(x);
  }
}

/* ---------- Tutorial menu bug: robust insertion ---------- */
window.psyAddTutorialMenu=function(){
  const menu=document.getElementById('menu');
  if(!menu || menu.querySelector('[data-psy-tutorial-btn="1"]')) return;
  const b=document.createElement('button');
  b.dataset.psyTutorialBtn='1';
  b.onclick=openTutorial;
  b.innerHTML='📖 TUTORIAL / AJUDA';
  b.style.cssText='background:linear-gradient(90deg,#0ea5e9,#7c3aed);color:#fff;border:none;font-weight:bold;';
  let grid=menu.querySelector('.psy-main-grid');
  if(!grid){
    psyBuildCompactMainMenu();
    grid=menu.querySelector('.psy-main-grid');
  }
  if(grid) grid.appendChild(b);
  else menu.appendChild(b);
};

/* ---------- Safe image fallback: no CSP-spamming GitHub request ---------- */
window.getImg=function(id,shiny=false,isMega=false,megaForm=null){
  const url=getRealSprite({id,shiny:!!shiny,isMega:!!isMega,megaForm:megaForm||null});
  if(typeof imgCache==='undefined') window.imgCache={};
  if(imgCache[url]) return imgCache[url];
  const img=new Image();
  img.src=url;
  img.onerror=function(){ this.onerror=null; this.style.visibility='hidden'; };
  imgCache[url]=img;
  return img;
};
window.psySetPokeImgSmooth=function(el,poke){
  if(!el||!poke)return;
  const url=getRealSprite(poke);
  if(el.dataset.psyUrl===url && el.getAttribute('src')){
    psyApplyAura?.(el,poke); return;
  }
  el.dataset.psyUrl=url;
  el.style.opacity='0';
  const pre=new Image();
  pre.onload=()=>{
    if(el.dataset.psyUrl!==url)return;
    el.src=url;
    el.style.visibility='visible';
    psyApplyAura?.(el,poke);
    requestAnimationFrame(()=>el.style.opacity='1');
  };
  pre.onerror=()=>{
    if(el.dataset.psyUrl!==url)return;
    el.removeAttribute('src');
    el.style.opacity='1';
    el.style.visibility='hidden';
  };
  pre.src=url;
};

/* ---------- Shiny without confirm(): sandbox-safe and deterministic ---------- */
window.useShinyStone=function(idx,isBox){
  const poke=isBox?P.box[idx]:P.team[idx];
  if(!poke) return notif('❌ Pokémon não encontrado');
  const have=P.inventory["Shiny Stone"]||0;

  if(!poke.shiny){
    const cost=(typeof getTierCost==='function'?getTierCost(poke.id):1);
    if(have<cost) return notif(`❌ Precisa ${cost} Shiny Stone (tem ${have})`,3200);

    P.inventory["Shiny Stone"]-=cost;
    if(P.inventory["Shiny Stone"]<=0) delete P.inventory["Shiny Stone"];

    poke.shiny=true;
    poke.shinyCostInvested=cost;
    poke.rarity={...(poke.isMega?PSY_RARITY_REBORN.CRIADOR:PSY_RARITY_REBORN.PIKA)};
    poke.tier=getTier(poke.id,true,!!poke.isMega,!!poke.isBoss);
    recalcPoke(poke);
    autoSave();renderTeam();updateHUD();
    notif(`✨ ${getPokeName(poke.id)} agora é SHINY!`,3500);
    setTimeout(()=>openPokeDetail(idx,isBox),80);
    return;
  }

  /* If already shiny, preserve old behavior: shiny evolution path. */
  const evo=EVOLUTION_MAP?.[poke.id];
  if(!evo) return notif('✨ Já é Shiny e está na forma final.',2800);

  const nextId=evo.to;
  const nextCost=(typeof getTierCost==='function'?getTierCost(nextId):1);
  if((P.inventory["Shiny Stone"]||0)<nextCost)
    return notif(`❌ Precisa ${nextCost} Shiny Stone para evoluir (tem ${P.inventory["Shiny Stone"]||0})`,3200);

  P.inventory["Shiny Stone"]-=nextCost;
  if(P.inventory["Shiny Stone"]<=0) delete P.inventory["Shiny Stone"];

  poke.id=nextId;
  poke.name='Shiny '+getPokeName(nextId);
  poke.shiny=true;
  poke.isMega=false;
  poke.megaForm=null;
  poke.level=1; poke.exp=0; poke.maxExp=100;
  poke.evoMult=(poke.evoMult||1)*(EVOLUTION_MAP?.[nextId]?1.4:1.6);
  poke.moves=getMovesForLevel(nextId,1);
  poke.movePool=typeof getFullMoveList==='function'?getFullMoveList(nextId,1):poke.moves;
  poke.rarity={...PSY_RARITY_REBORN.PIKA};
  poke.tier=getTier(nextId,true,false,false);
  recalcPoke(poke);
  autoSave();renderTeam();updateHUD();
  notif(`✨ Evoluiu para ${poke.name}!`,3500);
  setTimeout(()=>openPokeDetail(idx,isBox),80);
};

/* Tree button always delegates to the fixed function. */
window.psyTreeMakeShiny=function(idx,isBox){ return window.useShinyStone(idx,isBox); };

/* ---------- Mega without confirm() for single-form Megas ---------- */
window.useMegaStone=function(idx,isBox){
  const poke=isBox?P.box[idx]:P.team[idx];
  if(!poke||poke.isMega)return;
  const need=poke.shiny?PSY_TRAINER_GATES.shinyMega:PSY_TRAINER_GATES.mega;
  if((P.trainerLevel||1)<need) return notif(`🔒 ${poke.shiny?'Shiny Mega':'Mega'} libera no Trainer Lv.${need}.`,3500);
  if(!window.MEGA_POKES.includes(poke.id)) return notif('Esse Pokémon não possui Mega cadastrada.');
  const cost=poke.shiny?150:50;
  if((P.inventory["Fragmento Mega Stone"]||0)<cost) return notif(`Precisa ${cost} Fragmentos Mega.`);

  if(window.MEGA_XY[poke.id] && window.MEGA_XY[poke.id].length>1){
    return openMegaChoice(idx,isBox,cost);
  }

  P.inventory["Fragmento Mega Stone"]-=cost;
  if(P.inventory["Fragmento Mega Stone"]<=0) delete P.inventory["Fragmento Mega Stone"];
  poke.isMega=true;
  poke.megaForm=window.MEGA_XY[poke.id]?.[0]?.id || (getShowdownName(poke.id)+'-mega');
  poke.name=(poke.shiny?'Shiny Mega ':'Mega ')+getPokeName(poke.id);
  poke.tier=getTier(poke.id,!!poke.shiny,true,false);
  psyEnforceTierRarity?.(poke);recalcPoke(poke);
  autoSave();renderTeam();updateHUD();
  notif(`🔷 ${poke.name}!`,3500);
  setTimeout(()=>openPokeDetail(idx,isBox),80);
};

