/* ---------- SOUND ENGINE (WebAudio, no external files) ---------- */
window.PSY_AUDIO={ctx:null,enabled:true,master:.18,music:false};
function psyAudioCtx(){
  if(!PSY_AUDIO.enabled)return null;
  if(!PSY_AUDIO.ctx){
    const AC=window.AudioContext||window.webkitAudioContext;
    if(!AC)return null;
    PSY_AUDIO.ctx=new AC();
  }
  if(PSY_AUDIO.ctx.state==='suspended')PSY_AUDIO.ctx.resume().catch(()=>{});
  return PSY_AUDIO.ctx;
}
function psyTone(freq=440,dur=.12,type='sine',vol=.12,delay=0){
  const c=psyAudioCtx();if(!c)return;
  const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.value=freq;
  const t=c.currentTime+delay;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.001,vol*PSY_AUDIO.master),t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+dur);
  o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+dur+.03);
}
function psySfx(name){
  const seq={
    click:[[540,.05,'square',.06,0]],
    attack:[[180,.06,'sawtooth',.12,0],[110,.08,'square',.08,.04]],
    heal:[[523,.12,'sine',.10,0],[659,.12,'sine',.10,.09],[784,.16,'sine',.10,.18]],
    buff:[[330,.08,'triangle',.09,0],[440,.08,'triangle',.09,.07],[660,.12,'triangle',.1,.14]],
    shiny:[[880,.12,'sine',.12,0],[1175,.12,'sine',.12,.1],[1568,.22,'sine',.14,.2]],
    mega:[[110,.18,'sawtooth',.12,0],[220,.18,'square',.10,.11],[440,.22,'triangle',.12,.22]],
    rare:[[392,.10,'triangle',.1,0],[523,.12,'triangle',.1,.1],[659,.15,'triangle',.11,.2]],
    evolve:[[330,.1,'sine',.11,0],[440,.1,'sine',.11,.1],[660,.12,'sine',.12,.2],[880,.25,'sine',.13,.32]],
    gacha:[[440,.08,'triangle',.08,0],[554,.08,'triangle',.08,.07],[659,.08,'triangle',.08,.14],[880,.18,'sine',.12,.22]],
    capture:[[660,.08,'square',.08,0],[880,.15,'sine',.12,.08]]
  }[name]||[];
  seq.forEach(x=>psyTone(...x));
}
document.addEventListener('pointerdown',e=>{psyAudioCtx();if(e.target.closest('button'))psySfx('click')},{passive:true});
window.psySfx=psySfx;

/* ---------- ALERTS / RARE WILD ---------- */
function ensureRareAlert(){
  if(document.getElementById('psy-rare-alert'))return;
  const d=document.createElement('div');d.id='psy-rare-alert';document.body.appendChild(d);
}
function psyRareAlert(wild){
  if(!wild)return;
  const rar=wild.rarity?.n||'';
  const rareNames=['Bombado','Pika das Galáxias','DEUS','VOID','CRIADOR','OBLIVION'];
  let text='',col='#fff',sfx='rare';
  if(wild.shiny){text=`✨ SHINY ${getPokeName(wild.id)} apareceu!`;col='#ffd700';sfx='shiny'}
  else if(wild.isMega){text=`🔷 MEGA ${getPokeName(wild.id)} apareceu!`;col='#00d9ff';sfx='mega'}
  else if(rareNames.includes(rar)){text=`🔥 ${rar}: ${getPokeName(wild.id)}!`;col=wild.rarity?.color||'#ff8800'}
  else return;
  ensureRareAlert();const d=document.getElementById('psy-rare-alert');d.style.color=col;d.textContent=text;d.style.display='block';psySfx(sfx);setTimeout(()=>d.style.display='none',2600);
}
