/* ---------- HUNTS: gym-gated ---------- */
function psyHuntRequiredGyms(cardIndex){
  /* 648 zones -> progressive unlock; every 8 gyms opens roughly one region band */
  return Math.min(72,Math.floor(cardIndex/72)*8 + Math.floor((cardIndex%72)/18)*2);
}
function psyDecorateHuntLocks(){
  const list=document.getElementById('hunt-list');if(!list)return;
  const cards=[...list.children];const done=P.gymProgress?.length||0;
  cards.forEach((card,i)=>{
    card.style.position='relative';const need=psyHuntRequiredGyms(i);
    const old=card.querySelector('.psy-hunt-lock');if(old)old.remove();
    if(done<need){
      const o=document.createElement('div');o.className='psy-hunt-lock';o.innerHTML=`🔒 BLOQUEADO<br><small>Vença ${need} Ginásios (${done}/${need})</small>`;card.appendChild(o);
      card.querySelectorAll('button').forEach(b=>b.disabled=true);
    }else card.classList.add('psy-hunt-open');
  });
}
const psyOpenHuntsOld=window.openHunts;
