/* ---------- CARDS: proper moves, 3 queued actions, undo before READY ---------- */
window.CG_MOVE_COLOR={Fire:'#ef4444',Water:'#38bdf8',Grass:'#22c55e',Electric:'#facc15',Normal:'#d1d5db',Flying:'#93c5fd',Psychic:'#d946ef',Ghost:'#8b5cf6',Dark:'#475569',Dragon:'#6366f1',Ice:'#67e8f9',Fighting:'#f97316',Poison:'#a855f7',Ground:'#a16207',Rock:'#78716c',Bug:'#84cc16',Steel:'#94a3b8',Fairy:'#f9a8d4',Status:'#06b6d4'};
function cgMoveKind(m){
  const n=String(m?.name||'').toLowerCase(),type=String(m?.type||'Status');
  if(type==='Status'||/\b(growl|tail whip|leer|harden|agility|swords dance|calm mind|protect|defense curl|howl|focus energy)\b/.test(n))return 'buff';
  if(/\b(recover|roost|synthesis|rest|soft-boiled|milk drink|heal pulse|wish|moonlight)\b/.test(n))return 'heal';
  return 'attack';
}
function cgMoveDesc(m,kind,power){
  if(kind==='attack')return `Causa ${power} de dano base. Tipo ${m.type||'Normal'}.`;
  if(kind==='heal')return `Recupera HP do Nexus com base no PWR da carta.`;
  return `Aumenta ATK/DEF temporariamente para as próximas ações.`;
}
function cgBuildMoveSet(card){
  let list=[];
  try{list=getMovesForLevel(card.id,Math.max(20,card.level||1))||[]}catch(e){}
  if(!list.length)list=[{name:'Tackle',type:'Normal',power:40},{name:'Growl',type:'Status',power:0},{name:'Quick Attack',type:'Normal',power:40}];
  const uniq=[];for(const m of list){if(!uniq.some(x=>x.name===m.name))uniq.push(m)}
  return uniq.slice(-4);
}
window.cgStartStage=function(){
  ensureCardData();if(!P.cardGame.deck.length)return notif('Monte seu deck primeiro!');
  const stage=P.cardGame.stage||1,deck=P.cardGame.deck.slice(0,3).map(k=>P.cardGame.collection[k]).filter(Boolean);
  let ids=Object.keys(ALL_POKE_NAMES||{}).map(Number).filter(psyEligibleEggId);
  const rank={E:0,D:1,C:2,B:3,A:4,S:5,SS:6,SSS:7,UR:8,"UR+":9};
  const need=stage>=18?'SS':stage>=14?'S':stage>=10?'A':stage>=6?'B':stage>=3?'C':'D';
  let pool=ids.filter(id=>rank[getTier(id,false,false,false)||'E']>=rank[need]);if(!pool.length)pool=ids;
  const enemyId=pool[Math.floor(Math.random()*pool.length)],enemyTier=getTier(enemyId,false,false,false)||'E';
  const partyHp=Math.floor(520+deck.reduce((s,c)=>s+cg2Power(c),0)*.35),enemyHp=Math.floor((480*Math.pow(1.19,stage-1))*({E:1,D:1.08,C:1.18,B:1.33,A:1.52,S:1.75,SS:2.05,SSS:2.4,UR:2.9}[enemyTier]||1));
  window.cgBattleState={stage,enemyId,enemyTier,enemyHp,enemyMax:enemyHp,playerHp:partyHp,playerMax:partyHp,turn:1,deck,activeIndex:0,queue:[],buffs:{atk:0,def:0}};
  cgDrawBattle();
};
window.cgQueueMove=function(moveIndex){
  const s=cgBattleState;if(!s||s.queue.length>=3)return;
  const hero=s.deck[s.activeIndex%s.deck.length],moves=cgBuildMoveSet(hero),m=moves[moveIndex];if(!m)return;
  s.queue.push({cardId:hero.id,cardIndex:s.activeIndex,moveIndex,name:m.name,type:m.type||'Normal',kind:cgMoveKind(m),power:Number(m.power||40)});
  s.activeIndex=(s.activeIndex+1)%s.deck.length;psySfx('click');cgDrawBattle();
};
window.cgUndoMove=function(i){
  const s=cgBattleState;if(!s||i<0||i>=s.queue.length)return;
  s.queue.splice(i,1);s.activeIndex=Math.max(0,(s.activeIndex-1+s.deck.length)%s.deck.length);cgDrawBattle();
};
window.cgCommitTurn=function(){
  const s=cgBattleState;if(!s||!s.queue.length)return notif('Escolha pelo menos 1 ação.');
  const actions=[...s.queue];s.queue=[];
  let delay=0;
  actions.forEach((a,i)=>{
    setTimeout(()=>{
      if(!cgBattleState)return;
      const card=s.deck[a.cardIndex%s.deck.length],pwr=cg2Power(card);
      if(a.kind==='attack'){
        const dmg=Math.floor((a.power/40)*pwr*(.65+Math.random()*.18)*(1+s.buffs.atk/100));s.enemyHp-=dmg;psySfx('attack');cgAnimateBattleSprite('enemy','hit');
      }else if(a.kind==='heal'){
        const heal=Math.floor(s.playerMax*(.13+Math.min(.10,pwr/15000)));s.playerHp=Math.min(s.playerMax,s.playerHp+heal);psySfx('heal');cgAnimateBattleSprite('player','heal');
      }else{
        s.buffs.atk=Math.min(45,s.buffs.atk+12);s.buffs.def=Math.min(30,s.buffs.def+9);psySfx('buff');cgAnimateBattleSprite('player','buff');
      }
      if(s.enemyHp<=0)return cgWinStage();
      cgDrawBattle();
    },delay);
    delay+=420;
  });
  setTimeout(()=>{
    if(!cgBattleState||s.enemyHp<=0)return;
    const tr={E:1,D:1.08,C:1.16,B:1.27,A:1.4,S:1.55,SS:1.72,SSS:1.92,UR:2.15}[s.enemyTier]||1;
    const hits=Math.max(1,actions.length);let dmg=Math.floor(16*Math.pow(1.12,s.stage-1)*tr*hits*(1-s.buffs.def/100));s.playerHp-=Math.max(5,dmg);psySfx('attack');cgAnimateBattleSprite('player','hit');
    if(s.playerHp<=0)return cgLoseStage();s.turn++;s.activeIndex=0;s.buffs.atk=Math.max(0,s.buffs.atk-5);s.buffs.def=Math.max(0,s.buffs.def-4);cgDrawBattle();
  },delay+220);
};
window.cgAnimateBattleSprite=function(which,cls){
  const el=document.querySelector(which==='enemy'?'.cg-enemy-sprite':'.cg-player-zone .cg-battle-sprite');if(!el)return;
  el.classList.remove('hit','heal','buff');void el.offsetWidth;el.classList.add(cls);setTimeout(()=>el.classList.remove(cls),600);
};
window.cgDrawBattle=function(){
  const s=cgBattleState,c=document.getElementById('cg-content');if(!s||!c)return;
  const hero=s.deck[s.activeIndex%s.deck.length]||s.deck[0],moves=cgBuildMoveSet(hero),enemyPct=Math.max(0,s.enemyHp/s.enemyMax*100),playerPct=Math.max(0,s.playerHp/s.playerMax*100),tc=CG_TIER_COLOR[s.enemyTier]||'#888';
  c.innerHTML=`<div class="cg-map">
    <div class="cg-enemy-zone"><div class="cg-hpbox"><b style="color:${tc}">${getPokeName(s.enemyId)} • ${s.enemyTier}</b><div class="cg-bar"><div class="cg-fill" style="width:${enemyPct}%"></div></div>${Math.max(0,s.enemyHp).toLocaleString()} / ${s.enemyMax.toLocaleString()} HP</div><img class="cg-battle-sprite cg-enemy-sprite" src="${getRealSprite({id:s.enemyId})}"></div>
    <div class="cg-player-zone"><img class="cg-battle-sprite" src="${getRealSprite({id:hero.id})}"><div class="cg-hpbox"><b>${getPokeName(hero.id)}</b> • PWR ${cg2Power(hero).toLocaleString()} • Ação ${s.queue.length+1}/3<div class="cg-bar"><div class="cg-fill" style="width:${playerPct}%"></div></div>${Math.max(0,s.playerHp).toLocaleString()} / ${s.playerMax.toLocaleString()} HP</div></div>
    <div class="cg-queue">${s.queue.map((a,i)=>`<span class="cg-queue-chip">${i+1}. ${getPokeName(a.cardId)} — ${a.name}<button onclick="cgUndoMove(${i})">↩</button></span>`).join('')}</div>
    <div class="cg-action-hand">${moves.slice(0,4).map((m,i)=>{const k=cgMoveKind(m),col=CG_MOVE_COLOR[m.type]||CG_MOVE_COLOR.Status,p=Math.max(20,Number(m.power||40));return `<button class="cg-move-card" style="--move:${col}" onclick="cgQueueMove(${i})" ${s.queue.length>=3?'disabled':''}><span class="move-type" style="color:${col}">${m.type||'Status'}</span><div style="font-size:28px">${k==='attack'?'💥':k==='heal'?'💚':'✨'}</div><div class="move-name">${m.name}</div><div class="move-desc">${cgMoveDesc(m,k,p)}</div></button>`}).join('')}</div>
    <button class="cg-ready" onclick="cgCommitTurn()" ${!s.queue.length?'disabled':''}>READY • ${s.queue.length}/3</button>
  </div>`;psyDecorateAllPokemonImages(c);
};

/* ---------- GACHA: Gold vs premium diamonds separated + animation ---------- */
window.cgMultiPull=function(n,currency='gold'){
  ensureCardData();n=Math.max(1,Math.min(100,Number(n)||1));const goldEach=65000,diaEach=4,cost=(currency==='diamond'?diaEach:goldEach)*n;
  if(currency==='diamond'){if(P.diamonds<cost)return notif(`Precisa ${cost} 💎`);P.diamonds-=cost}else{if(P.gold<cost)return notif(`Precisa ${cost.toLocaleString()} Gold`);P.gold-=cost}
  psySfx('gacha');
  const c=document.getElementById('cg-content');if(c)c.innerHTML=`<div class="psy-system-card" style="text-align:center;padding:50px"><div style="font-size:64px;animation:psyEvoBurst .8s ease">🎴</div><h2 class="psy-title-glint">ABRINDO PORTAL ${n}x...</h2></div>`;
  setTimeout(()=>{
    const pulls=[],ids=Object.keys(ALL_POKE_NAMES||{}).map(Number).filter(psyEligibleEggId);
    for(let z=0;z<n;z++){const id=ids[Math.floor(Math.random()*ids.length)],stars=cgRollStars(),k=String(id);let card=P.cardGame.collection[k];if(card){card.copies=(card.copies||1)+1;if(card.copies%4===0)card.level=(card.level||1)+1;card.stars=Math.max(card.stars||1,stars)}else card=P.cardGame.collection[k]={id,stars,level:1,copies:1};pulls.push({...card})}
    P.cardGame.lastPull=pulls.slice(-12);autoSave();renderCardTab('gacha');
  },850);
};
window.cgRenderGacha=function(c){
  const arr=Array.isArray(P.cardGame.lastPull)?P.cardGame.lastPull:(P.cardGame.lastPull?[P.cardGame.lastPull]:[]);
  c.innerHTML=`<div class="psy-system-card" style="text-align:center"><h3 class="psy-title-glint">🎴 PORTAL GACHA</h3><div class="psy-desc">Gold = pool padrão. Diamantes = portal premium com melhor taxa de estrelas. Diamantes não ficam misturados nos botões de Gold.</div>
  ${arr.length?`<div class="cardgame-grid" style="margin:10px 0">${arr.map(x=>cg2CardHtml(x)).join('')}</div>`:''}
  <div class="cg-gacha-free"><b>💰 PORTAL GOLD</b><div class="cg2-pull-grid">${[1,5,10,100].map(n=>`<button onclick="cgMultiPull(${n},'gold')">${n}x • ${(65000*n).toLocaleString()} Gold</button>`).join('')}</div></div>
  <div class="cg-gacha-premium"><b>💎 PORTAL PREMIUM</b><div class="psy-desc">Somente aqui entram Diamantes.</div><div class="cg2-pull-grid">${[1,5,10,100].map(n=>`<button onclick="cgMultiPull(${n},'diamond')">${n}x • ${4*n} 💎</button>`).join('')}</div></div></div>`;
};

