function psyRefreshPrettyHud(){
  const h=document.getElementById('hud-player');
  if(!h || h.dataset.prettyHud!=='1') return;
  const p=P?.team?.[0];
  if(!p)return;
  const n=document.getElementById('psy-hud-poke-name'); if(n)n.textContent=getPokeName(p.id);
  const l=document.getElementById('psy-hud-poke-lv'); if(l)l.textContent=p.level||1;
  const tl=document.getElementById('psy-hud-trainer-lv'); if(tl)tl.textContent=P.trainerLevel||1;
  const cp=document.getElementById('psy-hud-cap'); if(cp)cp.textContent=P.levelCap||20;
  const dia=document.getElementById('hud-diamonds'); if(dia)dia.textContent=Number(P.diamonds||0).toLocaleString('pt-BR');
  const av=document.getElementById('psy-hud-avatar-img');
  if(av) psySetPokeImgSmooth(av,p);
  const st=document.getElementById('psy-hud-mini-stats');
  if(st)st.textContent=`⚔ ${Math.floor(p.atk||0).toLocaleString()}  •  🛡 ${Math.floor(p.def||0).toLocaleString()}  •  ${p.tier||getTier(p.id,p.shiny,p.isMega,p.isBoss)}`;
  const psyProgress=document.getElementById('psy-hud-psyduck-progress');
  if(psyProgress){
    const psyPool=[...(P.team||[]),...(P.box||[])];
    const psy=psyPool.find(x=>Number(x?.id)===54&&x?.psyduckChosen)||psyPool.find(x=>Number(x?.id)===54);
    const best=Number(P?.psyduck?.survivorBest||P?.meta?.psyTree?.survivorBest||P?.psyTree?.survivorBest||0);
    const resets=Number(psy?.resets||0);
    psyProgress.textContent=`Fase ${best}/400 • Reset ${resets}/1000`;
  }
}

/* Patch updateHUD after all previous versions: keep original behavior, then decorate. */
const psyHudUpdateOld=window.updateHUD;
window.updateHUD=function(){
  const r=psyHudUpdateOld.apply(this,arguments);
  if(document.getElementById('hud-player')?.dataset.prettyHud==='1'){
    const p=P?.team?.[0];
    if(p){
      const hp=document.getElementById('hp-txt'); if(hp)hp.textContent=`${Math.floor(p.hp||0)}/${Math.floor(p.maxHp||0)}`;
      const hf=document.getElementById('hp-fill'); if(hf)hf.style.width=`${Math.max(0,Math.min(100,(p.hp||0)/(p.maxHp||1)*100))}%`;
      const ex=document.getElementById('exp-txt'); if(ex)ex.textContent=`${Math.floor(p.exp||0)}/${Math.floor(p.maxExp||100)}`;
      const ef=document.getElementById('exp-fill'); if(ef)ef.style.width=`${Math.max(0,Math.min(100,(p.exp||0)/(p.maxExp||100)*100))}%`;
      const ge=document.getElementById('hud-gold'); if(ge)ge.textContent=(P.gold||0).toLocaleString();
    }
    psyRefreshPrettyHud();
  }
  return r;
};

/* Buy eggs from Gold Shop properly instead of inventory. */
const psyBuyMultiOld=window.buyMulti;
window.buyMulti=function(){
  if(selShop==null){notif('Selecione um item');return}
  const it=SHOP_DG[selShop];
  if(!it || it.t!=='egg') return psyBuyMultiOld.apply(this,arguments);

  const q=Math.max(1,Math.min(20,parseInt(document.getElementById('shop-qty').value)||1));
  const total=it.p*q;
  if(P.gold<total)return notif('❌ Sem Gold suficiente!');
  if(typeof window.confirm==='function'&&!window.confirm(`Você deseja confirmar a compra?\n\n${q}x ${it.n} — ${total.toLocaleString('pt-BR')} Gold`))return;

  P.gold-=total;
  for(let z=0;z<q;z++){
    let opts={source:'gold-shop'};
    if(it.eggRandomRegion){
      const r=PSY_REGIONS[Math.floor(Math.random()*PSY_REGIONS.length)];
      opts.region=r.key;
    }
    if(it.eggRandomType){
      opts.type=PSY_TYPE_NAMES[Math.floor(Math.random()*PSY_TYPE_NAMES.length)];
    }
    P.eggs.push(psyNewEgg(opts));
  }
  autoSave();updateHUD();notif(`🥚 ${q}x ${it.n} comprado!`,3000);openShop();
};

/* Improve shop renderer for egg metadata and visual classes. */
const psyOpenShopEggOld=window.openShop;
window.openShop=function(){
  const r=psyOpenShopEggOld.apply(this,arguments);
  setTimeout(()=>{
    const g=document.getElementById('shop-grid');if(!g)return;
    if(g.classList.contains('psy-shop-grid'))return;
    [...g.children].forEach((card,idx)=>{
      const it=SHOP_DG[idx];if(!it)return;
      if(it.t==='egg')card.classList.add('dungeon-card-mini','psy-egg-shop-card');
      else card.classList.add('dungeon-card-mini');
      card.removeAttribute('style');
      const bColor=it.t==='ball'?'#ffd700':it.t==='potion'?'#00ff88':it.t==='egg'?'#a78bfa':'#7c3aed';
      card.style.setProperty('--item',bColor);

      let icon=card.querySelector('.psy-shop-icon');
      if(!icon){
        const oldIcon=card.firstElementChild;
        if(oldIcon){oldIcon.classList.add('psy-shop-icon'); icon=oldIcon;}
      }
      const divs=[...card.querySelectorAll('div')];
      if(divs[1])divs[1].classList.add('psy-shop-name','psy-glint-name');
      if(divs[2])divs[2].classList.add('psy-shop-price');

      if(!card.querySelector('.psy-shop-desc')){
        const d=document.createElement('div');d.className='psy-shop-desc';
        d.textContent=it.d||'';card.appendChild(d);
      }
    });
  },40);
  return r;
};

/* Make shop detail explicit for eggs. */
const psyUpdateShopOld=window.updateShopTotal;
window.updateShopTotal=function(){
  const r=psyUpdateShopOld.apply(this,arguments);
  if(selShop==null)return r;
  const it=SHOP_DG[selShop];
  if(it?.t==='egg'){
    const qty=Math.max(1,Math.min(20,parseInt(document.getElementById('shop-qty').value)||1));
    const total=it.p*qty,can=P.gold>=total;
    document.getElementById('shop-detail').innerHTML=
      `<b style="color:#c4b5fd">${getItemIcon(it.n)} ${it.n}</b><br><span style="color:#aaa">${it.d}</span><br>`+
      `<span style="color:${can?'#00ff88':'#ff4444'}">💰 ${it.p.toLocaleString()} x ${qty} = ${total.toLocaleString()}</span><br>`+
      `<span style="color:#888">Cada Egg precisa de 300 derrotas para chocar.</span>`;
    document.getElementById('btn-buy').textContent=`COMPRAR ${qty} EGG${qty>1?'S':''} • ${total.toLocaleString()}`;
  }
  return r;
};

