/* ---------- AFK ---------- */
window.CG_AFK_TICK_MS=30000;
function cgAfkTick(){
  cgEnsure4();if(!P.cardGame.afk.enabled)return;
  const lv=P.trainerLevel||1,b=P.cardGame.afk;
  const gold=Math.floor((900+lv*220)*(1+getTotalBuff('gold')/100)*.22);
  const xp=Math.max(1,Math.floor((4+lv*.55)*(1+getTotalBuff('xp')/100)*.22));
  P.gold+=gold;b.gold+=gold;b.xp+=xp;b.ticks++;
  const p=P.team?.[0];if(p){p.exp=(p.exp||0)+xp;try{checkLevelUp()}catch(e){}}psyAwardGlobalPsyduckXp(xp,'cards-afk');
  if(Math.random()<.035){const stones=['Fire Stone','Water Stone','Leaf Stone','Thunder Stone','Ice Stone','Normal Stone'];const s=stones[Math.floor(Math.random()*stones.length)];P.inventory[s]=(P.inventory[s]||0)+1;b.drops++}
  const fortune=1+(P.cardGame.skills.fortune||0)*.12;
  let pack=null,r=Math.random();
  if(r<.00005*fortune)pack='epic';else if(r<.00022*fortune)pack='rare';else if(r<.0009*fortune)pack='normal';
  if(pack){P.cardGame.packs[pack]=(P.cardGame.packs[pack]||0)+1;b.packs++;notif(`🎁 AFK encontrou ${CG_PACKS[pack].name}!`,3500)}
  autoSave();updateHUD();
  if(document.getElementById('screen-card-mode')?.style.display!=='none'&&document.getElementById('cg-content')?.dataset.tab==='afk')renderCardTab('afk');
}
setInterval(cgAfkTick,CG_AFK_TICK_MS);
window.cgToggleAfk=function(){cgEnsure4();P.cardGame.afk.enabled=!P.cardGame.afk.enabled;autoSave();renderCardTab('afk');notif(P.cardGame.afk.enabled?'🌙 AFK ligado. Continue jogando normalmente!':'⏸ AFK pausado.',2500)};
window.cgRenderAfk=function(c){
  cgEnsure4();const a=P.cardGame.afk;
  c.innerHTML=`<div class="cg-afk-panel"><h2 class="psy-title-glint">🌙 AFK</h2><p style="color:#ddd">Deixe o seu Pokémon upando enquanto poderá fazer outras coisas no jogo, experimente o modo Cards &lt;3</p><div class="psy-desc">O ganho é propositalmente reduzido e usa os mesmos buffs de Gold/XP/Drop do WORLD. AFK nunca captura Pokémon. Pode receber itens, XP, Gold e raramente Packs Normal, Raro ou Épico.</div>
  <div class="cg-afk-status"><div class="cg-afk-stat">STATUS<b style="color:${a.enabled?'#22c55e':'#f87171'}">${a.enabled?'ATIVO':'PAUSADO'}</b></div><div class="cg-afk-stat">💰 acumulado<b>${a.gold.toLocaleString()}</b></div><div class="cg-afk-stat">⭐ XP<b>${a.xp.toLocaleString()}</b></div><div class="cg-afk-stat">🎁 Packs<b>${a.packs}</b></div></div>
  <button onclick="cgToggleAfk()" style="width:100%;padding:12px;background:${a.enabled?'#7f1d1d':'#0891b2'};color:#fff;border:0;border-radius:9px;font-weight:900">${a.enabled?'⏸ PAUSAR AFK':'▶ ATIVAR AFK'}</button></div>`;
};

