/* add AFK shortcut to main menu */
function cgAddAfkShortcut(){
  const menu=document.getElementById('menu');if(!menu||menu.querySelector('[data-afk-shortcut]'))return;
  const grid=menu.querySelector('.psy-main-grid');if(!grid)return;
  const b=document.createElement('button');b.dataset.afkShortcut='1';b.innerHTML='🌙 AFK';b.style.background='linear-gradient(90deg,#0f172a,#4338ca)';b.style.color='#fff';
  b.onclick=()=>{openCardMode();renderCardTab('afk')};grid.appendChild(b);
}
