window.PSY_IS_MOBILE = matchMedia('(max-width: 900px), (pointer: coarse)').matches;

/* Starter/load drift fix: never inherit a stale movement target or held joystick key. */
function psyResetCityMotion(){
  try{
    P.moving=false;
    P.tx=Number(P.x)||25; P.ty=Number(P.y)||25;
    P.px=P.tx*TILE; P.py=P.ty*TILE;
    window.clickMove=null;
    ['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyW','KeyA','KeyS','KeyD'].forEach(k=>keys[k]=false);
    if(typeof resetJoy==='function')resetJoy();
  }catch(e){}
}
const psyInitEngineStableOld=window.initEngine;
window.initEngine=function(){
  psyResetCityMotion();
  return psyInitEngineStableOld.apply(this,arguments);
};

/* Also correct immediately after starter confirmation/load transitions. */
const psyConfirmStarterStableOld=window.confirmStarter;
window.confirmStarter=function(){
  const r=psyConfirmStarterStableOld.apply(this,arguments);
  setTimeout(psyResetCityMotion,0);
  return r;
};

/* Mobile rendering: hidden minimap no longer redraws every frame. */
if(PSY_IS_MOBILE){
  window.drawMinimap=function(){};
  if(typeof updateNPCSprites==='function'){
    const _npc=updateNPCSprites;let _npcLast=0;
    window.updateNPCSprites=function(){
      const n=performance.now();
      if(n-_npcLast<180)return;
      _npcLast=n;return _npc();
    };
  }
  /* Canvas rendering at ~30fps, while movement/input update can remain responsive. */
  if(typeof draw==='function'){
    const _draw=draw;let _drawLast=0;
    window.draw=function(){
      const n=performance.now();
      if(n-_drawLast<31)return;
      _drawLast=n;return _draw();
    };
  }
}

/* Canvas backing resolution is capped on phones.
   CSS still fills the screen, but GPU/CPU draws fewer pixels. */
function psyResizeCanvasEfficient(){
  if(typeof canvas==='undefined'||!canvas)return;
  const mobile=window.PSY_IS_MOBILE;
  const maxW=mobile?960:window.innerWidth,maxH=mobile?720:window.innerHeight;
  const scale=Math.min(1,maxW/window.innerWidth,maxH/window.innerHeight);
  const w=Math.max(320,Math.floor(window.innerWidth*scale));
  const h=Math.max(240,Math.floor(window.innerHeight*scale));
  if(canvas.width!==w)canvas.width=w;
  if(canvas.height!==h)canvas.height=h;
  if(typeof ctx!=='undefined')ctx.imageSmoothingEnabled=false;
}
setTimeout(psyResizeCanvasEfficient,100);
window.addEventListener('resize',()=>setTimeout(psyResizeCanvasEfficient,40),{passive:true});
window.addEventListener('orientationchange',()=>setTimeout(psyResizeCanvasEfficient,180),{passive:true});

/* The existing engine resize listener may enlarge it again; keep it capped sparsely. */
if(PSY_IS_MOBILE)setInterval(()=>{if(!document.hidden)psyResizeCanvasEfficient()},3000);

