function psyTierIsLegend(id){id=Number(id);try{if(window.LEGENDARY_IDS?.has?.(id))return true}catch(e){}try{if(typeof LEGENDARY_IDS!=='undefined'&&LEGENDARY_IDS.has(id))return true}catch(e){}return false}
function psyTierIsBossSpecies(id){id=Number(id);try{return !!window.BOSS_BAN_IDS?.has?.(id)}catch(e){return false}}
function psyTierEvolutionData(id){
  id=Number(id);const dex=window.PSY29_DEX||{};let stage=1,parent=0,req=0,hasChild=false,nextReq=0;
  try{if(typeof window.psy29DexStage==='function')stage=Math.max(1,Number(window.psy29DexStage(id)||1));else if(typeof getEvoStage==='function')stage=Math.max(1,Number(getEvoStage(id)||1))}catch(e){}
  try{parent=Number(dex.parent?.[id]||0);req=Number(dex.min?.[id]||0);hasChild=!!dex.children?.[id]?.length}catch(e){}
  try{if(typeof EVOLUTION_MAP!=='undefined'&&EVOLUTION_MAP[id]?.to){hasChild=true;nextReq=Number(EVOLUTION_MAP[id].minLevel||EVOLUTION_MAP[id].lvl||0)}}catch(e){}
  try{if(typeof SPECIAL_EVOLUTIONS!=='undefined'&&Object.keys(SPECIAL_EVOLUTIONS[id]||{}).length){hasChild=true;const vv=Object.values(SPECIAL_EVOLUTIONS[id]||{});nextReq=Number(vv[0]?.minLevel||vv[0]?.lvl||nextReq||0)}}catch(e){}
  if(!parent){try{for(const [from,e] of Object.entries(EVOLUTION_MAP||{})){if(Number(e?.to)===id){parent=Number(from);if(!req)req=Number(e.minLevel||e.lvl||0);break}}}catch(e){}}
  if(!parent){try{for(const [from,opts] of Object.entries(SPECIAL_EVOLUTIONS||{})){for(const e of Object.values(opts||{})){if(Number(e?.to)===id){parent=Number(from);if(!req)req=Number(e.minLevel||e.lvl||0);break}}if(parent)break}}catch(e){}}
  if(stage===1&&parent){stage=2;let cur=parent,seen=new Set([id]);while(cur&&!seen.has(cur)){seen.add(cur);let pp=Number(dex.parent?.[cur]||0);if(!pp){try{for(const [from,e] of Object.entries(EVOLUTION_MAP||{})){if(Number(e?.to)===cur){pp=Number(from);break}}}catch(e){}}if(!pp)break;stage++;cur=pp;if(stage>=3)break}}
  if(!nextReq&&dex.children?.[id]?.length){const c=Number(dex.children[id][0]);nextReq=Number(dex.min?.[c]||0)}return {stage:Math.min(3,stage),parent,req,hasChild,nextReq};
}
window.getBaseTier=function(id){
  id=Number(id);
  if(psyTierIsLegend(id))return 'UR+';
  if(psyTierIsBossSpecies(id))return 'SSS';
  if(id===133||PSY_TIER_PSEUDO_SS.has(id))return 'SS';
  if(PSY_TIER_STRONG_S.has(id))return 'S';
  const d=psyTierEvolutionData(id);
  if(d.stage>=3&&!d.hasChild){if(d.req>=45)return 'SS';if(d.req>=30)return 'S';if(d.req>=20)return 'A';return 'C'}
  if(d.stage===2){if(d.hasChild)return d.nextReq&&d.nextReq<=25?'C':'B';if(d.req>=30)return 'A';return 'B'}
  if(d.stage===1&&d.hasChild)return d.nextReq&&d.nextReq<=10?'E':'D';
  /* standalone / not yet mapped species stay mid-tier instead of gaining power by Pokédex number */
  return 'C';
};
window.getTier=function(id,shiny,mega,isBoss){
  id=Number(id);const base=getBaseTier(id);
  if(psyTierIsLegend(id))return shiny?'UR++':'UR+';
  if(shiny&&mega)return 'UR+';
  if(isBoss||psyTierIsBossSpecies(id))return 'UR';
  if(mega)return 'SSS';
  if(shiny)return ({E:'A',D:'S',C:'SS',B:'SS',A:'SSS',S:'SSS',SS:'UR',SSS:'UR',UR:'UR+','UR+':'UR++'}[base]||base);
  return base;
};

/* ---------- evolved species level gating ---------- */
function psySpeciesWildMinLevel(id){
  let cur=Number(id),seen=new Set(),threshold=1;
  while(cur && !seen.has(cur)){
    seen.add(cur);
    let parent=null,req=0;
    for(const [from,e] of Object.entries(EVOLUTION_MAP||{})){
      if(Number(e?.to)===cur){parent=Number(from);req=Math.max(req,Number(e.minLevel||e.lvl||1));break}
    }
    if(!parent)break;
    threshold=Math.max(threshold,Math.ceil(req/10)*10);
    cur=parent;
  }
  return threshold;
}
const psyHuntPokesOld=window.getPokesForHunt;
window.getPokesForHunt=function(reg,tipo,tierNum){
  let list=psyHuntPokesOld.apply(this,arguments)||[];
  const min={1:1,2:10,3:20,4:40,5:60}[Number(tierNum)]||1;
  return list.filter(p=>!PSY_SPECIAL_EXCLUDED_WILD.has(Number(p.id)) && psySpeciesWildMinLevel(p.id)<=min);
};
/* world excludes Psyduck + Eevee */
const psyRegionList5Old=window.getRegionPokemonList;
window.getRegionPokemonList=function(regionKey){
  return (psyRegionList5Old.apply(this,arguments)||[]).filter(id=>!PSY_SPECIAL_EXCLUDED_WILD.has(Number(id)));
};

/* ---------- official PokeAPI move learnset + TM cache ---------- */
window.PSY_OFFICIAL_MOVE_CACHE={};
try{PSY_OFFICIAL_MOVE_CACHE=JSON.parse(localStorage.getItem('psy_official_moves_v1')||'{}')}catch(e){}
function psyPrettyMove(n){return String(n).replace(/-/g,' ').replace(/\b\w/g,x=>x.toUpperCase())}
async function psyMoveDetail(name){
  const k='m:'+name;if(PSY_OFFICIAL_MOVE_CACHE[k])return PSY_OFFICIAL_MOVE_CACHE[k];
  try{
    const d=await fetch(`https://pokeapi.co/api/v2/move/${name}`).then(r=>r.json());
    const x={name:psyPrettyMove(d.name),power:Number(d.power||0),type:psyPrettyMove(d.type?.name||'Normal'),accuracy:d.accuracy,pp:d.pp,damageClass:d.damage_class?.name||'status'};
    PSY_OFFICIAL_MOVE_CACHE[k]=x;return x;
  }catch(e){return {name:psyPrettyMove(name),power:40,type:'Normal',accuracy:100,pp:20,damageClass:'physical'}}
}
window.psyHydrateOfficialMoves=async function(poke){
  if(!poke?.id)return;
  const key='p:'+poke.id;
  let meta=PSY_OFFICIAL_MOVE_CACHE[key];
  try{
    if(!meta){
      const d=await fetch(`https://pokeapi.co/api/v2/pokemon/${poke.id}`).then(r=>r.json());
      meta=d.moves.map(x=>({name:x.move.name,details:x.version_group_details||[]}));
      PSY_OFFICIAL_MOVE_CACHE[key]=meta;
    }
    /* Prefer newest available level-up entry per move. */
    const lv=[],tm=[];
    for(const x of meta){
      const details=x.details;
      const levelDetails=details.filter(v=>v.move_learn_method?.name==='level-up');
      const machine=details.some(v=>v.move_learn_method?.name==='machine');
      if(levelDetails.length){
        const newest=levelDetails[levelDetails.length-1];
        const md=await psyMoveDetail(x.name);
        lv.push({...md,lvl:Number(newest.level_learned_at||1)});
      }
      if(machine){const md=await psyMoveDetail(x.name);tm.push({...md,lvl:1})}
    }
    lv.sort((a,b)=>a.lvl-b.lvl);
    poke.officialMovePool=lv;
    poke.tmCompatibility=tm.map(m=>m.name);
    poke.movePool=lv.filter(m=>m.lvl<=(poke.level||1));
    if(!poke.moves?.length || !poke.moves.every(m=>lv.some(x=>x.name===m.name))){
      const available=poke.movePool.length?poke.movePool:lv.filter(m=>m.lvl<=1);
      poke.moves=(available.length?available:[{lvl:1,name:'Tackle',power:40,type:'Normal'}]).slice(-4);
    }
    localStorage.setItem('psy_official_moves_v1',JSON.stringify(PSY_OFFICIAL_MOVE_CACHE));
    autoSave();
  }catch(e){console.warn('Official moves fallback',e)}
};
function psyHydrateRosterMoves(){
  const all=[...(P.team||[]),...(P.box||[])].slice(0,18);
  let delay=0;all.forEach(p=>{setTimeout(()=>psyHydrateOfficialMoves(p),delay);delay+=220});
}
/* V10 performance: official move hydration is on-demand (TM/drop), not during initial load. */

/* ---------- TM drops / teaching ---------- */
function psyEnsure5(){P.tms=P.tms||{};P.meta=P.meta||{};P.meta.captures=Number(P.meta.captures||0);P.marketLocal=P.marketLocal||[];P.psyduck=P.psyduck||{trial:0,stones:0,ascensions:0};}
function psyRollTMDrop(pokeId){
  psyEnsure5();
  if(Math.random()>=0.006)return; // 0.6%
  const p={id:pokeId,level:100};psyHydrateOfficialMoves(p).then(()=>{
    const pool=p.tmCompatibility||[];if(!pool.length)return;
    const name=pool[Math.floor(Math.random()*pool.length)];
    P.tms[name]=(P.tms[name]||0)+1;notif(`📀 TM encontrada: ${name}!`,3200);autoSave();
  });
}
window.psyTeachTM=async function(poke,moveName){
  psyEnsure5();if((P.tms[moveName]||0)<=0)return notif('Você não possui essa TM.');
  await psyHydrateOfficialMoves(poke);
  if(!(poke.tmCompatibility||[]).includes(moveName))return notif(`${poke.name||getPokeName(poke.id)} não é compatível com ${moveName}.`);
  const md=await psyMoveDetail(moveName.toLowerCase().replace(/ /g,'-'));
  poke.movePool=poke.movePool||[];
  if(!poke.movePool.some(x=>x.name===md.name))poke.movePool.push({...md,lvl:1,tm:true});
  P.tms[moveName]--;if(P.tms[moveName]<=0)delete P.tms[moveName];
  autoSave();notif(`📀 ${poke.name||getPokeName(poke.id)} aprendeu ${moveName}!`,3000);
};

/* ---------- elemental essence drops 5% -> max 10% ---------- */
function psyEssenceChance(){
  const d=Math.max(0,Number(getTotalBuff('drop')||0));
  return Math.min(10,5+d/60); // +5 max if 300% drop
}
window.psyTryElementDrop=function(id,source='wild'){
  if(Math.random()*100>=psyEssenceChance())return false;
  const e=psyElement(id);P.inventory[e.ess]=(P.inventory[e.ess]||0)+1;notif(`${e.ico} ${e.ess} +1`,1500);autoSave();return true;
};
function psyCommonDropHooks(id){
  /* A tabela de materiais comum é instalada no núcleo e atende Wild/Fast,
     Hunts, Survivor, World e Aventura. Mantemos este fallback aqui porque
     este hook também é referenciado por camadas legadas já carregadas. */
  if(typeof window.psySharedCombatDrop==='function'){
    return window.psySharedCombatDrop(id,window.__psyDropContext?.mode||'auto');
  }
  psyTryElementDrop(id);psyRollTMDrop(id);try{window.psyQuestDrop?.(id)}catch(e){console.warn('Quest loot drop',e)}
}

