/* ---------- tier-based capture + elemental balls ---------- */
function psyTierCaptureBase(tier){
  return {E:7.5,D:5.2,C:3.3,B:2.1,A:1.25,S:.72,SS:.38,SSS:.20,UR:.10,'UR+':.05}[tier]||1;
}
Object.values(PSY_ELEMENT_DATA).forEach(e=>{if(!BALL_DATA[e.ball])BALL_DATA[e.ball]={chance:6,price:0};});
window.tryCaptureBattle=function(ballName){
  if((P.inventory[ballName]||0)<=0)return notif('Sem Balls!');
  const wild=battleData?.wild;if(!wild)return;
  if(wild.psyduckDungeon||window.isDungeonBoss||window.isDungeonMega)return notif('❌ Este encontro não pode ser capturado.');
  P.inventory[ballName]--;if(P.inventory[ballName]<=0)delete P.inventory[ballName];
  document.getElementById('screen-bag').style.display='none';window.bagBattleMode=null;
  const tier=getTier(wild.id,wild.shiny,wild.isMega,wild.isBoss),hpPct=battleData.wildHp/battleData.wildMaxHp;
  let ball=BALL_DATA[ballName]?.chance||1;
  const elem=psyElement(wild.id);
  if(ballName===elem.ball)ball=(BALL_DATA['Ultra Ball']?.chance||3)*2;
  const base=psyTierCaptureBase(tier),hpFactor=.25+(1-hpPct)*.75,rarity=Math.sqrt(Math.max(1,wild.rarity?.mult||1));
  const chance=Math.max(.01,Math.min(18,base*ball*hpFactor/rarity));
  psyEnsurePity();const key=psyPityKey(wild),entry=P.meta.capturePity[key]||(P.meta.capturePity[key]={ultraFails:0,allFails:0});
  const isUltra=/Ultra Ball/i.test(ballName),pity=psyPityTarget(wild),forced=isUltra&&entry.ultraFails>=pity;
  if(forced||Math.random()*100<chance){
    const pk=createCapturedPoke(wild.id,wild.rarity,wild.shiny,false,wild.isMega);P.box.push(pk);delete P.meta.capturePity[key];P.meta.captures++;
    psyHydrateOfficialMoves(pk);notif(forced?`✅ PITY! ${pk.name} capturado!`:`✅ Capturado! Chance desta Ball: ${chance.toFixed(2)}%`,3300);endBattle(true);autoSave();renderTeam();
  }else{
    entry.allFails++;if(isUltra)entry.ultraFails++;notif(`❌ Escapou. Chance desta Ball: ${chance.toFixed(2)}%`,2000);autoSave();
  }
};

