/* Psyduck progression */
function psyEnsurePsyduck(){psyEnsure5();P.psyduck=P.psyduck||{trial:0,stones:0,ascensions:0};P.inventory['PsyStone']=P.inventory['PsyStone']||0}
function psyPsyduckRequirements(stage){
  const lv=stage*10;
  return {trainer:Math.max(1,stage*8),gold:stage*350000,captures:stage*12,cards:Math.max(0,stage*4),stones:Math.max(1,stage)};
}
function psyPsyduckCan(stage){
  psyEnsurePsyduck();const r=psyPsyduckRequirements(stage),cards=Object.keys(P.cardGame?.collection||{}).length,caps=P.meta?.captures||0;
  return (P.trainerLevel||1)>=r.trainer&&P.gold>=r.gold&&caps>=r.captures&&cards>=r.cards&&(P.inventory['PsyStone']||0)>=r.stones;
}
function ensurePsyduckDungeon5(){let d=document.getElementById('screen-psyduck5');if(d)return d;d=document.createElement('div');d.id='screen-psyduck5';d.style.cssText='display:none;position:fixed;inset:0;background:#000f;z-index:1000010;overflow:auto;padding:10px';d.innerHTML=`<div class="psyduck-panel"><button class="psy-close-x" onclick="document.getElementById('screen-psyduck5').style.display='none'">×</button><div id="psyduck5-body"></div></div>`;document.body.appendChild(d);return d}
window.openPsyduckDungeon5=function(){psyEnsurePsyduck();ensurePsyduckDungeon5().style.display='block';renderPsyduckDungeon5()};
window.renderPsyduckDungeon5=function(){
  const b=document.getElementById('psyduck5-body');if(!b)return;const prog=P.psyduck.trial||0;
  b.innerHTML=`<div class="psyduck-hero"><img src="${getRealSprite({id:54,shiny:false})}"><div><h2 class="psy-title-glint">🦆 PSYDUCK — A PROVAÇÃO</h2><div class="psy-desc">Exclusivo desta Dungeon. Não aparece em Wild, Hunts ou WORLD. A força cresce por provas, PsyStone, capturas, Cards, Gold e Trainer Level.</div><div>Prova atual: <b>${prog}/9</b> • PsyStone: <b>${P.inventory['PsyStone']||0}</b></div><div class="psyduck-progress"><i style="width:${Math.min(100,prog/9*100)}%"></i></div></div></div>
  <div class="psyduck-stage-grid">${Array.from({length:9},(_,i)=>{const st=i+1,r=psyPsyduckRequirements(st),done=prog>=st,open=prog===i&&psyPsyduckCan(st);return `<div class="psyduck-stage ${done?'done':open?'open':'locked'}"><b>Prova ${st} • Lv${st*10}</b><div class="psy-desc">T.Lv ${r.trainer}<br>${r.gold.toLocaleString()} Gold<br>${r.captures} capturas<br>${r.cards} Cards<br>${r.stones} PsyStone</div><button ${!open?'disabled':''} onclick="psyStartPsyduckTrial(${st})">${done?'CONCLUÍDA':open?'DESAFIAR':'🔒'}</button></div>`}).join('')}</div>
  <div class="psy-system-card" style="margin-top:10px"><b>ASCENSÕES</b><div class="psy-desc">Lv90 alcança força próxima de SS. 10 resets → SSS. 20 resets → UR + Shiny Psyduck. 50 resets → Mega Psyduck. Cada ascensão adicional exige progressão real.</div><button onclick="psyAscendPsyduck5()">VERIFICAR / ASCENDER PSYDUCK DO BOX</button></div>`;
};
window.psyStartPsyduckTrial=function(stage){
  if(!psyPsyduckCan(stage))return;const r=psyPsyduckRequirements(stage);P.gold-=r.gold;P.inventory['PsyStone']-=r.stones;document.getElementById('screen-psyduck5').style.display='none';
  const lv=stage*10,tier=stage>=9?'SS':stage>=7?'S':stage>=5?'A':stage>=3?'B':'C',rar=psyMinimumRarityForTier(tier);
  const w={id:54,name:`Psyduck da Provação ${stage}`,level:lv,rarity:rar,shiny:false,isMega:false,psyduckDungeon:true,psyStage:stage};
  w.maxHp=Math.floor((2500+stage*2200)*rar.mult);w.hp=w.maxHp;startBattle(w);
};
window.psyPsyduckWin=function(w){
  if(!w?.psyduckDungeon)return;psyEnsurePsyduck();P.psyduck.trial=Math.max(P.psyduck.trial||0,w.psyStage||0);
  if(Math.random()<.45){P.inventory['PsyStone']=(P.inventory['PsyStone']||0)+1;notif('🟡 PsyStone +1!',2500)}
  if((w.psyStage||0)===9 && !(P.box||[]).some(p=>p.id===54)){const p=createCapturedPoke(54,psyMinimumRarityForTier('SS'),false,false,false);p.level=90;p.resets=0;p.psyduckChosen=true;recalcPoke(p);P.box.push(p);notif('🦆 Psyduck conquistado! Agora começa a verdadeira jornada.',4500)}
  autoSave();
};
window.psyAscendPsyduck5=function(){
  psyEnsurePsyduck();const p=[...(P.team||[]),...(P.box||[])].find(x=>x.id===54&&x.psyduckChosen);if(!p)return notif('Conclua a Prova Lv90 primeiro.');
  const resets=p.resets||0,cards=Object.keys(P.cardGame?.collection||{}).length,caps=P.meta?.captures||0,tl=P.trainerLevel||1;
  if(resets>=50){
    p.isMega=true;p.megaForm='psyduck';p.psyMega=true;p.rarity={...PSY_RARITY_REBORN.OBLIVION};p.tier='UR+';recalcPoke(p);autoSave();notif('🌌 MEGA PSYDUCK DESPERTOU!',5000);return;
  }
  if(resets>=20){
    p.shiny=true;p.rarity={...PSY_RARITY_REBORN.VOID};p.tier='UR';recalcPoke(p);autoSave();notif('✨ Psyduck alcançou UR e tornou-se SHINY!',4500);return;
  }
  if(resets>=10){
    if(tl<120||caps<250||cards<100)return notif('SSS exige T.Lv120, 250 capturas e 100 Cards.');
    p.rarity={...psyMinimumRarityForTier('SSS')};p.tier='SSS';recalcPoke(p);autoSave();notif('🔥 Psyduck alcançou SSS!',4000);return;
  }
  notif(`Progresso Psyduck: ${resets}/10 resets para SSS. Depois: 20 UR/Shiny, 50 Mega.`);
};

