/* ---------- FAST ENCOUNTER remains reachable during battle ---------- */
function psyV10FastEncounterTop(){const b=document.getElementById('fastEncounterBtn');if(!b)return;b.title='Pode desligar o Fast-Encounter durante a própria batalha';b.style.display='block'}
setInterval(()=>{if(!document.hidden)psyV10FastEncounterTop()},2400);setTimeout(psyV10FastEncounterTop,300);

/* ---------- GYM: victory stays open and offers next leader ---------- */
function psyV10FindNextGym(gym){
  if(!gym)return null;let ri=-1,gi=-1;
  GYM_DATA.forEach((r,ridx)=>r.gyms.forEach((g,gidx)=>{if(g.id===gym.id){ri=ridx;gi=gidx}}));
  if(ri<0)return null;if(gi+1<GYM_DATA[ri].gyms.length)return GYM_DATA[ri].gyms[gi+1];
  if(ri+1<GYM_DATA.length)return GYM_DATA[ri+1].gyms[0];return null;
}
function psyV10CloseGymVictory(openGymsAfter=false){
  document.getElementById('psy-v10-gym-result')?.remove();const acts=document.querySelector('.battle-actions');if(acts)acts.style.display='';
  const wasFast=!!window.fastEncounter;try{window.__psyV10GymExit=true;window.fastEncounter=false;gymBattle=null;endBattle(true)}finally{window.__psyV10GymExit=false;window.fastEncounter=wasFast;try{psyV10FastEncounterTop()}catch(e){}}
  if(openGymsAfter)setTimeout(()=>openGyms(),120);
}
window.psyV10NextGym=function(id){document.getElementById('psy-v10-gym-result')?.remove();const acts=document.querySelector('.battle-actions');if(acts)acts.style.display='';gymBattle=null;startGymBattle(id)};
window.psyV10ExitGym=function(){psyV10CloseGymVictory(true)};
window.startNextGymPoke=function(){
  if(!gymBattle)return;
  if(gymBattle.current>=6){
    const gym=gymBattle.gym;
    if(!P.gymProgress.includes(gym.id)){
      P.gymProgress.push(gym.id);
      if(getRegionCompleted(gym.region)){recalcLevelCap();notif(`🏆 REGIÃO ${gym.region} COMPLETA! CAP ${P.levelCap} liberado!`,5000);try{spawnFloat(`CAP ${P.levelCap}!`,'#ffd700')}catch(e){}}
      else notif(`🏆 VENCEU ${gym.name}! ${gym.region} ${regProgressText(gym.region)}`,3500);
      autoSave();updateHUD();
    }
    const next=psyV10FindNextGym(gym);battleData.state='won';inBattle=true;
    const hud=document.querySelector('.battle-hud')||document.getElementById('battle-screen');if(!hud)return;
    document.getElementById('psy-v10-gym-result')?.remove();const acts=document.querySelector('.battle-actions');if(acts)acts.style.display='none';
    const box=document.createElement('div');box.id='psy-v10-gym-result';box.className='psy-v10-gym-result';
    box.innerHTML=`<div class="psy-v10-gym-card"><div style="font-size:46px">🏆</div><h2>${gym.name} DERROTADO!</h2><p>${gym.region} • ${regProgressText(gym.region)} líderes concluídos</p><p>CAP atual: <b>${P.levelCap}</b></p><div class="psy-v10-gym-actions">${next?`<button class="psy-v10-next" onclick="psyV10NextGym('${next.id}')">PRÓXIMO LÍDER<br><small>${next.name} • Lv${next.level}</small></button>`:`<button class="psy-v10-next" onclick="psyV10ExitGym()">🏆 LIGA CONCLUÍDA</button>`}<button class="psy-v10-exit" onclick="psyV10ExitGym()">SAIR / VER GINÁSIOS</button></div></div>`;
    hud.appendChild(box);return;
  }
  const poke=gymBattle.queue[gymBattle.current],gym=gymBattle.gym;inBattle=true;
  document.getElementById('battle-screen').style.display='flex';document.getElementById('gym-progress').style.display='block';document.getElementById('trainer-side').style.display='block';
  document.getElementById('gym-progress').textContent=`${gym.region} - ${gym.name} | ${gymBattle.current+1}/6 | REGIÃO CAP ${REGION_CAPS[gym.region]}`;
  document.getElementById('trainer-img').src=`https://play.pokemonshowdown.com/sprites/trainers/${gym.trainerSprite}.png`;document.getElementById('trainer-img').onerror=function(){this.src='https://play.pokemonshowdown.com/sprites/trainers/red.png'};
  document.getElementById('trainer-name').textContent=gym.name;battleData={wild:poke,wildHp:poke.maxHp,wildMaxHp:poke.maxHp,state:'active'};
  document.getElementById('enemy-name-tag').textContent=poke.name+' Lv'+poke.level;document.getElementById('enemy-img').src=getPokeAnim(poke);document.getElementById('player-name-tag').textContent=P.team[0].name;document.getElementById('player-img').src=getPokeAnim(P.team[0]);document.getElementById('battle-log').textContent=`🏆 ${gym.name} mandou ${poke.name}!`;updateBattleHP();loadMoveButtons();psyV10FastEncounterTop();
};

/* ---------- AFK V10: live projected counters + 30s settlement + scaling + essences/eggs ---------- */
function psyV10AfkRates(){
  const tl=Math.max(1,Number(P.trainerLevel||1)),cap=Math.max(20,Number(P.levelCap||20));
  const trainerSteps=Math.floor((tl-1)/10),capSteps=Math.floor((cap-20)/10);
  const progression=1+trainerSteps*.13+capSteps*.08;
  const goldPerMin=(320+tl*16)*progression*(1+Number(getTotalBuff?.('gold')||0)/100);
  const xpPerMin=(27+tl*2.35)*progression*(1+Number(getTotalBuff?.('xp')||0)/100);
  const dropBoost=1+Math.min(2,Number(getTotalBuff?.('drop')||0)/100);
  return {tl,cap,trainerSteps,capSteps,progression,goldPerMin,xpPerMin,dropBoost};
}
const psyV10AfkEnsureBase=psyAfkEnsure;
psyAfkEnsure=function(){const a=psyV10AfkEnsureBase();a.essences=Number(a.essences||0);a.eggs=Number(a.eggs||0);a.stones=Number(a.stones||0);return a};
function psyV10SilentEgg(opts){try{psyEnsureMeta();P.eggs.push(psyNewEgg(opts));return true}catch(e){return false}}
psyAfkReward=function(seconds,offline=false){
  psyCardsEnsure();const a=psyAfkEnsure();if(!a.enabled||seconds<2)return null;const mins=seconds/60,rates=psyV10AfkRates();
  const gold=Math.max(1,Math.floor(mins*rates.goldPerMin)),xp=Math.max(1,Math.floor(mins*rates.xpPerMin));P.gold=(P.gold||0)+gold;a.gold+=gold;a.xp+=xp;
  const poke=P.team?.[0];if(poke){poke.exp=(poke.exp||0)+xp;try{checkLevelUp()}catch(e){}}psyAwardGlobalPsyduckXp(xp,'afk');
  let stones=0,essences=0,eggs=0;const packs=[],loot=[];const whole=Math.floor(mins);
  const elems=[...new Map(Object.values(PSY_ELEMENT_DATA||{}).map(e=>[e.ess,e])).values()];
  for(let i=0;i<whole;i++){
    if(Math.random()<.050*rates.dropBoost){const e=elems[Math.floor(Math.random()*elems.length)]||PSY_ELEMENT_DATA.Normal;P.inventory[e.ess]=(P.inventory[e.ess]||0)+1;essences++;loot.push(e.ess)}
    if(Math.random()<.014*rates.dropBoost){const stonesPool=['Fire Stone','Water Stone','Leaf Stone','Thunder Stone','Ice Stone','Fighting Stone','Poison Stone','Ground Stone','Flying Stone','Psychic Stone','Bug Stone','Rock Stone','Ghost Stone','Dragon Stone','Dark Stone','Metal Stone','Fairy Stone','Normal Stone'];const st=stonesPool[Math.floor(Math.random()*stonesPool.length)];P.inventory[st]=(P.inventory[st]||0)+1;stones++;loot.push(st)}
    // WORLD/AFK: eggs are intentionally rarer than the previous 0.15% roll.
    if(Math.random()<.00075*rates.dropBoost){const t=PSY_TYPE_NAMES[Math.floor(Math.random()*PSY_TYPE_NAMES.length)];if(psyV10SilentEgg(Math.random()<.72?{type:t,source:'afk'}:{source:'afk'})){eggs++;loot.push(`${t} Egg`)}}
    const r=Math.random();if(r<.000025){P.cardGame.packs.ss=(P.cardGame.packs.ss||0)+1;packs.push('SS Global')}else if(r<.00018){P.cardGame.packs.epic=(P.cardGame.packs.epic||0)+1;packs.push('Épico')}else if(r<.00075){P.cardGame.packs.rare=(P.cardGame.packs.rare||0)+1;packs.push('Raro')}else if(r<.003){P.cardGame.packs.normal=(P.cardGame.packs.normal||0)+1;packs.push('Normal')}
  }
  const drops=stones+essences+eggs;a.stones+=stones;a.essences+=essences;a.eggs+=eggs;a.drops+=drops;a.packs+=packs.length;a.lastSettlementAt=Date.now();
  a.history.unshift({at:Date.now(),seconds:Math.floor(seconds),gold,xp,drops,stones,essences,eggs,packs,loot:loot.slice(0,12),offline});a.history=a.history.slice(0,25);autoSave();updateHUD();return {gold,xp,drops,stones,essences,eggs,packs};
};
window.openAfkV9=function(){
  const a=psyAfkEnsure(),d=psyEnsureAfkScreen(),elapsed=a.enabled?Math.floor((Date.now()-(a.startedAt||Date.now()))/1000):0,r=psyV10AfkRates();
  d.innerHTML=`<div class="psy-v9-panel"><button class="psy-close-x" onclick="document.getElementById('screen-afk-v9').style.display='none'">×</button><div class="psy-afk-head"><div class="psy-afk-orb">🌙</div><div><h2 class="psy-title-glint">EXPEDIÇÃO AFK</h2><b>${a.enabled?'ATIVA':'PAUSADA'}</b><div id="psy-afk-clock">${psyFmtTime(elapsed)}</div><small>Continua com o jogo fechado • sem limite de duração • recompensas escalam por Trainer Lv. e CAP.</small></div></div><div class="psy-afk-live">Ritmo atual: <b id="psy-afk-rate-gold">${Math.floor(r.goldPerMin).toLocaleString()}G/min</b> • <b id="psy-afk-rate-xp">${Math.floor(r.xpPerMin)}XP/min</b> • bônus progressão x${r.progression.toFixed(2)}</div><div class="psy-afk-stats"><div>💰 Gold<b id="psy-afk-gold">${a.gold.toLocaleString()}</b></div><div>⭐ XP<b id="psy-afk-xp">${a.xp.toLocaleString()}</b></div><div>🧪 Essências<b id="psy-afk-ess">${a.essences}</b></div><div>🥚 Eggs<b id="psy-afk-eggs">${a.eggs}</b></div><div>📦 Itens<b id="psy-afk-drops">${a.drops}</b></div><div>🎴 Packs<b id="psy-afk-packs">${a.packs}</b></div></div><button class="psy-afk-main" onclick="toggleAfkV9()">${a.enabled?'⏸ PAUSAR E COLETAR':'▶ INICIAR EXPEDIÇÃO'}</button><h3>Últimas recompensas</h3><div class="psy-afk-history">${a.history.length?a.history.map(h=>`<div><span>${h.offline?'📴 OFFLINE':'🌙 AFK'} • ${new Date(h.at).toLocaleString()}</span><b>${psyFmtTime(h.seconds)} • +${Number(h.gold||0).toLocaleString()}G • +${h.xp||0}XP${h.essences?' • 🧪'+h.essences:''}${h.stones?' • 💎'+h.stones:''}${h.eggs?' • 🥚'+h.eggs:''}${h.packs?.length?' • 🎴 '+h.packs.join(', '):''}</b></div>`).join(''):'<div class="empty">Nenhuma coleta ainda.</div>'}</div></div>`;d.style.display='flex';psyV10RefreshAfkLive();
};
function psyV10RefreshAfkLive(){
  const a=psyAfkEnsure();if(!a.enabled)return;const now=Date.now(),pending=Math.max(0,(now-Number(a.lastSettlementAt||a.startedAt||now))/1000),r=psyV10AfkRates();
  const pg=Math.floor(pending/60*r.goldPerMin),px=Math.floor(pending/60*r.xpPerMin);const set=(id,val)=>{const e=document.getElementById(id);if(e)e.textContent=val};
  set('psy-afk-clock',psyFmtTime((now-(a.startedAt||now))/1000));set('psy-afk-gold',(a.gold+pg).toLocaleString());set('psy-afk-xp',(a.xp+px).toLocaleString());set('psy-afk-ess',a.essences);set('psy-afk-eggs',a.eggs);set('psy-afk-drops',a.drops);set('psy-afk-packs',a.packs);set('psy-afk-rate-gold',Math.floor(r.goldPerMin).toLocaleString()+'G/min');set('psy-afk-rate-xp',Math.floor(r.xpPerMin)+'XP/min');
}
setInterval(()=>{const a=psyAfkEnsure();if(!a.enabled)return;const open=document.getElementById('screen-afk-v9')?.style.display==='flex';if(open&&!document.hidden)psyV10RefreshAfkLive();if(Date.now()-Number(a.lastSettlementAt||Date.now())>=30000){psyAfkSettleNow(false,true);if(open&&!document.hidden){psyV10RefreshAfkLive();openAfkV9()}}},1500);

/* ---------- Bag: direct selling of normal stones and essences ---------- */
function psyV10SellPrice(name){const it=SHOP_DG.find(x=>x.n===name);if(it?.t==='stone'&&!/Shiny Stone|PsyStone/i.test(name))return Math.max(1,Math.floor(it.p*.32));if(/^Essência /.test(name))return 550;return 0}
function psyV10Sellables(){return Object.entries(P.inventory||{}).filter(([n,q])=>q>0&&psyV10SellPrice(n)>0).sort((a,b)=>a[0].localeCompare(b[0]))}
function psyV10SellScreen(){let d=document.getElementById('psy-v10-sell');if(d)return d;d=document.createElement('div');d.id='psy-v10-sell';d.className='psy-v10-sell';d.innerHTML=`<div class="psy-v10-sell-panel"><button class="psy-close-x" onclick="document.getElementById('psy-v10-sell').style.display='none'">×</button><span class="psy-kicker">VENDOR NPC</span><h2 class="psy-title-glint">💰 VENDER ITENS</h2><p class="psy-desc">Revise a quantidade e o valor antes de vender. Itens protegidos não aparecem aqui.</p><div id="psy-v10-sell-wallet" class="psy-v10-sell-wallet"></div><div id="psy-v10-sell-feedback" class="psy-v10-sell-feedback" aria-live="polite"></div><div id="psy-v10-sell-grid" class="psy-v10-sell-grid"></div></div>`;document.body.appendChild(d);return d}
window.openBagSellV10=function(){const d=psyV10SellScreen();d.style.display='block';psyV10RenderSell()};
window.psyV10RenderSell=function(feedback=''){const g=document.getElementById('psy-v10-sell-grid');if(!g)return;const wallet=document.getElementById('psy-v10-sell-wallet');if(wallet)wallet.textContent=`💰 Gold disponível: ${Number(P.gold||0).toLocaleString('pt-BR')}`;const note=document.getElementById('psy-v10-sell-feedback');if(note){note.textContent=feedback;note.classList.toggle('show',!!feedback)}const arr=psyV10Sellables();g.innerHTML=arr.length?arr.map(([n,q])=>{const p=psyV10SellPrice(n),code=encodeURIComponent(n);return `<div class="psy-v10-sell-card" style="--item:#f59e0b"><div class="psy-item-art">${getItemIcon?.(n)||'📦'}</div><div class="psy-sell-copy"><b>${n}</b><small>Na bolsa: ${Number(q).toLocaleString('pt-BR')}</small><strong>💰 ${Number(p).toLocaleString('pt-BR')} cada</strong></div><div class="psy-sell-actions"><button onclick="psySellBagV10(decodeURIComponent('${code}'),1)">1x</button>${q>=10?`<button onclick="psySellBagV10(decodeURIComponent('${code}'),10)">10x</button>`:''}<button class="all" onclick="psySellBagV10(decodeURIComponent('${code}'),${q})">VENDER TODOS</button></div></div>`}).join(''):'<div class="empty">Nenhum item vendável na mochila.</div>'};
window.psySellBagV10=function(name,qty){const own=Number(P.inventory?.[name]||0),p=psyV10SellPrice(name);qty=Math.max(1,Math.min(own,Number(qty)||1));if(!p||!own)return;const gain=p*qty;P.inventory[name]-=qty;if(P.inventory[name]<=0)delete P.inventory[name];P.gold+=gain;autoSave();updateHUD();psyV10RenderSell(`✅ Venda concluída: ${qty}x ${name} • +${gain.toLocaleString('pt-BR')} Gold`);try{renderBag()}catch(e){}notif(`💰 ${qty}x ${name}: +${gain.toLocaleString()} Gold`,2200)};
function psyV10InstallBagSell(){const panel=document.querySelector('#screen-bag .shop-box');if(!panel)return;let bar=panel.querySelector('.psy-tabbar5');if(!bar){try{psyBagEnhance()}catch(e){}bar=panel.querySelector('.psy-tabbar5')}if(bar&&!bar.querySelector('[data-v10-sell]')){const b=document.createElement('button');b.dataset.v10Sell='1';b.textContent='💰 VENDER';b.onclick=openBagSellV10;bar.appendChild(b)}}
setInterval(()=>{if(!document.hidden)psyV10InstallBagSell()},3000);

/* Remove Eggs from the ordinary Poké Shop; Egg Center is the only Gold egg shop. */
for(let i=SHOP_DG.length-1;i>=0;i--)if(SHOP_DG[i]?.t==='egg')SHOP_DG.splice(i,1);

/* ---------- Egg Center: specific type eggs + lower, progression-friendly prices ---------- */
const psyV10EggRenderBase=window.renderEggCenter;
window.renderEggCenter=function(tab='incubator'){
  if(tab!=='goldshop')return psyV10EggRenderBase(tab);
  psyEnsureMeta();ensureEggScreen();const c=document.getElementById('psy-egg-content');if(!c)return;
  const mystery=120000,regional=220000,typeCost=180000;
  const regions=PSY_REGIONS.map(r=>`<div class="psy-system-card"><div class="psy-egg"></div><b class="psy-glint-name">${r.key} Egg</b><div class="psy-desc">Somente Pokémon da região • 1% Shiny • qualidade E-S</div><div class="psy-money">💰 ${regional.toLocaleString()}</div><button onclick="psyBuyGoldEgg('region','${r.key}',${regional})">COMPRAR</button></div>`).join('');
  const types=PSY_TYPE_NAMES.map(t=>`<div class="psy-system-card"><div class="psy-egg"></div><b class="psy-glint-name">${t} Egg</b><div class="psy-desc">Somente Pokémon do tipo ${t} • 1% Shiny • qualidade E-S</div><div class="psy-money">💰 ${typeCost.toLocaleString()}</div><button onclick="psyBuyGoldEgg('type','${t}',${typeCost})">COMPRAR</button></div>`).join('');
  c.innerHTML=`<div class="psy-system-card" style="border-color:#8b5cf6"><div class="psy-egg"></div><b class="psy-glint-name">Mystery Egg</b><div class="psy-desc">Qualquer espécie válida • 1% Shiny • qualidade E-S. É o Egg realmente aleatório.</div><div class="psy-money">💰 ${mystery.toLocaleString()}</div><button onclick="psyBuyGoldEgg('random','',${mystery})">COMPRAR</button></div><h3 style="margin-top:12px">Eggs Regionais</h3><div class="psy-shop-grid">${regions}</div><h3 style="margin-top:12px">Eggs por Elemento — escolha o tipo</h3><div class="psy-shop-grid">${types}</div>`;
  try{psyUpgradeModalChrome(document.getElementById('screen-egg-center'))}catch(e){}
};
window.psyBuyGoldEgg=function(kind,val,cost){if(P.gold<cost)return notif(`Gold insuficiente. Precisa ${cost.toLocaleString()}.`);if(typeof window.confirm==='function'&&!window.confirm(`Você deseja confirmar a compra?\n\nEgg — ${Number(cost).toLocaleString('pt-BR')} Gold`))return;P.gold-=cost;const opt=kind==='region'?{region:val,source:'gold'}:kind==='type'?{type:val,source:'gold'}:{source:'gold'};psyGiveEgg(opt);updateHUD();renderEggCenter('goldshop')};

/* ---------- Repeatable hunting achievements + accumulated 30-minute roulette ---------- */
let psyV10BuffRuntimeLast=Date.now();
function psyV10RewardsEnsure(){psyEnsureMeta();const m=P.meta;m.repeatClaims=m.repeatClaims||{};m.typeKills=m.typeKills||{};m.cardWins=Number(m.cardWins||0);m.rouletteProgress=Number(m.rouletteProgress||0);m.rouletteSpins=Number(m.rouletteSpins||0);m.tempBuffs=Array.isArray(m.tempBuffs)?m.tempBuffs:[];const now=Date.now(),merged={};for(const raw of m.tempBuffs){const b=raw||{},k=String(b.kind||'');if(!k)continue;if(!Number.isFinite(Number(b.remainingMs)))b.remainingMs=Math.max(0,Number(b.until||now)-now);const rem=Math.max(0,Number(b.remainingMs||0)),amt=Math.max(0,Number(b.amount||0));if(rem<=0||amt<=0)continue;if(!merged[k])merged[k]={kind:k,amount:amt,remainingMs:rem,label:b.label||`${k.toUpperCase()} +${amt}%`};else{merged[k].remainingMs+=rem;if(amt>Number(merged[k].amount||0)){merged[k].amount=amt;merged[k].label=b.label||`${k.toUpperCase()} +${amt}%`}}}m.tempBuffs=Object.values(merged);for(const b of m.tempBuffs)b.until=now+Number(b.remainingMs||0);return m}
function psyV10TickTempBuffs(){const m=psyV10RewardsEnsure(),now=Date.now(),delta=Math.max(0,Math.min(5000,now-psyV10BuffRuntimeLast));psyV10BuffRuntimeLast=now;if(!document.hidden&&delta>0){for(const b of m.tempBuffs)b.remainingMs=Math.max(0,Number(b.remainingMs||0)-delta)}m.tempBuffs=m.tempBuffs.filter(b=>Number(b.remainingMs)>0);for(const b of m.tempBuffs)b.until=now+Number(b.remainingMs||0);return m.tempBuffs}
window.psyV10RewardsEnsure=psyV10RewardsEnsure;
const PSY_V10_REPEAT_BASE=[
 {id:'repeat_kills',name:'Caçada Contínua',desc:'Derrote 50 Pokémon',kind:'kills',goal:50,gold:15000},
 {id:'repeat_capture',name:'Coletores de Campo',desc:'Capture 10 Pokémon',kind:'captures',goal:10,gold:20000,diamonds:1},
 {id:'repeat_eggs',name:'Incubação Constante',desc:'Choque 3 Eggs',kind:'eggs',goal:3,gold:30000,diamonds:1},
 {id:'repeat_cards',name:'Tático de Cards',desc:'Vença 10 fases de Cards',kind:'cardWins',goal:10,gold:22000}
];
function psyV10CanonType(t){const e=PSY_ELEMENT_DATA[t]||PSY_ELEMENT_DATA.Normal;return e.ess}
function psyV10CanonicalTypeForId(id){const ess=(psyElement(id)||PSY_ELEMENT_DATA.Normal).ess;return PSY_TYPE_NAMES.find(t=>(PSY_ELEMENT_DATA[t]||{}).ess===ess)||'Normal'}
function psyV10RepeatList(){const types=PSY_TYPE_NAMES.map(t=>({id:'type_'+t,name:`Caçador ${t}`,desc:`Derrote 25 Pokémon do tipo ${t}`,kind:'type',type:t,goal:25,gold:12000,essence:psyV10CanonType(t),essQty:3}));return [...PSY_V10_REPEAT_BASE,...types]}
function psyV10RepeatValue(r){const m=psyV10RewardsEnsure();if(r.kind==='kills')return Number(m.kills||0);if(r.kind==='captures')return Number(m.captures||0);if(r.kind==='eggs')return Number(m.eggHatches||0);if(r.kind==='cardWins')return Number(m.cardWins||0);if(r.kind==='type')return Number(m.typeKills[r.type]||0);return 0}
window.psyClaimRepeatV10=function(id){const m=psyV10RewardsEnsure(),r=psyV10RepeatList().find(x=>x.id===id);if(!r)return;const completed=Math.floor(psyV10RepeatValue(r)/r.goal),claimed=Number(m.repeatClaims[id]||0),times=Math.max(0,completed-claimed);if(!times)return notif('Ainda não há recompensa acumulada.');m.repeatClaims[id]=claimed+times;const g=(r.gold||0)*times,d=(r.diamonds||0)*times;P.gold+=g;P.diamonds+=d;if(r.essence){const q=(r.essQty||1)*times;P.inventory[r.essence]=(P.inventory[r.essence]||0)+q}autoSave();updateHUD();renderAchievements();notif(`🏆 ${r.name} x${times}: +${g.toLocaleString()}G${d?' +'+d+'💎':''}`,3200)};
function psyV10TrackTypeKill(id){const m=psyV10RewardsEnsure(),match=psyV10CanonicalTypeForId(id);m.typeKills[match]=Number(m.typeKills[match]||0)+1;autoSave()}
const psyV10EndBattleTrack=window.endBattle;window.endBattle=function(won){const w=window.battleData?.wild?{...battleData.wild}:null,inGym=(typeof gymBattle!=='undefined'&&!!gymBattle),wasMegaDungeon=!!window.isDungeonMega,wasKill=!!(won&&w&&Number(battleData?.wildHp||0)<=0&&!inGym&&!window.__psyV10GymExit&&!w.psyduckDungeon&&!w.eeveeDungeon);const r=psyV10EndBattleTrack.apply(this,arguments);if(wasKill)psyV10TrackTypeKill(w.id);if(wasMegaDungeon)window.isDungeonMega=false;return r};
const psyV10WorldKillTrack=window.handleWorldKill;if(psyV10WorldKillTrack)window.handleWorldKill=function(t){const id=t?.id,r=psyV10WorldKillTrack.apply(this,arguments);if(id)psyV10TrackTypeKill(id);return r};

let psyV10RouletteTick=Date.now();
function psyV10TickRoulette(){const m=psyV10RewardsEnsure(),now=Date.now(),delta=Math.max(0,Math.min(120,(now-psyV10RouletteTick)/1000));psyV10RouletteTick=now;m.rouletteProgress+=delta;if(m.rouletteProgress>=1800){const add=Math.floor(m.rouletteProgress/1800);m.rouletteProgress%=1800;m.rouletteSpins+=add;autoSave();notif(`🎡 +${add} giro${add>1?'s':''} da Roleta de Jornada!`,2600)}if(document.getElementById('screen-achievements')?.style.display==='block')psyV10UpdateWheelOnly();const wt=document.getElementById('psy20-wheel-time'),ws=document.getElementById('psy20-wheel-spins');if(wt)wt.textContent=typeof psyFmtTime==='function'?psyFmtTime(Math.max(0,1800-m.rouletteProgress)):Math.ceil(Math.max(0,1800-m.rouletteProgress)/60)+'m';if(ws)ws.textContent=String(m.rouletteSpins||0)}
setInterval(psyV10TickRoulette,5000);
window.psyV10AddTempBuff=function(kind,amount,minutes,label){const m=psyV10RewardsEnsure(),now=Date.now(),k=String(kind||''),a=Math.max(0,Number(amount||0)),mins=Math.max(1,Number(minutes||1));if(!k||!a)return false;psyV10TickTempBuffs();let b=m.tempBuffs.find(x=>x.kind===k);if(b){b.remainingMs=Math.max(0,Number(b.remainingMs||0))+mins*60000;if(a>=Number(b.amount||0)){b.amount=a;b.label=label||`${k.toUpperCase()} +${a}%`}b.until=now+b.remainingMs}else{b={kind:k,amount:a,remainingMs:mins*60000,until:now+mins*60000,label:label||`${k.toUpperCase()} +${a}%`};m.tempBuffs.push(b)}try{autoSave()}catch(e){try{save()}catch(_){}}try{updateHUD?.()}catch(e){}try{psy22BuffStrip?.()}catch(e){}return true};
const psyV10AddTempBuff=window.psyV10AddTempBuff;
const psyV10BuffBase=window.getTotalBuff;window.getTotalBuff=function(k){let base=Number(psyV10BuffBase.apply(this,arguments)||0);for(const b of psyV10TickTempBuffs())if(b.kind===k)base+=Number(b.amount||0);return base};
document.addEventListener('visibilitychange',()=>{psyV10BuffRuntimeLast=Date.now();try{autoSave()}catch(e){}});
window.addEventListener('beforeunload',()=>{try{psyV10TickTempBuffs();autoSave()}catch(e){}});
setInterval(()=>{try{psyV10TickTempBuffs();autoSave()}catch(e){}},15000);
function psyV10WheelScale(){return 1+Math.floor((P.trainerLevel||1)/10)*.08+Math.floor((Math.max(20,P.levelCap||20)-20)/10)*.05}
window.psySpinWheelV10=function(){const m=psyV10RewardsEnsure();if(m.rouletteSpins<=0)return notif('🎡 Você ganha 1 giro a cada 30 minutos com o jogo aberto.');m.rouletteSpins--;const scale=psyV10WheelScale(),r=Math.random()*100;let msg='';if(r<28){const g=Math.floor(6000*scale);P.gold+=g;msg=`💰 ${g.toLocaleString()} Gold`}else if(r<48){const g=Math.floor(14000*scale);P.gold+=g;msg=`💰 ${g.toLocaleString()} Gold`}else if(r<54){P.diamonds+=1;msg='💎 1 Diamante'}else if(r<56){P.diamonds+=2;msg='💎 2 Diamantes'}else if(r<68){window.psyV10AddTempBuff('gold',10,15,'Gold +10%');msg='💰 Buff Gold +10% por 15 min'}else if(r<80){window.psyV10AddTempBuff('xp',10,15,'XP +10%');msg='⭐ Buff XP +10% por 15 min'}else if(r<90){window.psyV10AddTempBuff('drop',8,15,'Drop +8%');msg='🎁 Buff Drop +8% por 15 min'}else if(r<97){const elems=[...new Map(Object.values(PSY_ELEMENT_DATA).map(e=>[e.ess,e])).values()],e=elems[Math.floor(Math.random()*elems.length)];P.inventory[e.ess]=(P.inventory[e.ess]||0)+4;msg=`${e.ico} 4x ${e.ess}`}else{psyCardsEnsure();P.cardGame.packs.normal++;msg='🎴 Pack Cards Normal'}autoSave();updateHUD();renderAchievements();notif(`🎡 ${msg}!`,3600)};
function psyV10WheelHtml(){const m=psyV10RewardsEnsure(),left=Math.max(0,1800-m.rouletteProgress),buffs=psyV10TickTempBuffs();return `<div class="psy-v10-reward-head"><div class="psy-v10-wheel"><div class="psy-v10-wheel-orb">🎡</div><div><h3 class="psy-title-glint">ROLETA DE JORNADA</h3><div>1 giro a cada <b>30 minutos</b> com o jogo aberto. O tempo parcial e giros ficam acumulados.</div><div>Giros disponíveis: <b id="psy-v10-spins">${m.rouletteSpins}</b> • próximo em <b id="psy-v10-wheel-time">${psyFmtTime(left)}</b></div><div class="psy-v10-buffline">${buffs.length?'Ativos: '+buffs.map(b=>`${b.label} (${Math.ceil(Number(b.remainingMs||0)/60000)}m)`).join(' • '):'Sem buffs temporários ativos.'}</div></div><button onclick="psySpinWheelV10()" ${m.rouletteSpins<=0?'disabled':''}>GIRAR AGORA</button></div></div>`}
function psyV10UpdateWheelOnly(){const m=psyV10RewardsEnsure(),t=document.getElementById('psy-v10-wheel-time'),s=document.getElementById('psy-v10-spins');if(t)t.textContent=psyFmtTime(Math.max(0,1800-m.rouletteProgress));if(s)s.textContent=m.rouletteSpins}
window.renderAchievements=function(){const el=document.getElementById('psy-ach-list');if(!el)return;psyV10RewardsEnsure();const panel=document.querySelector('#screen-achievements .psy-neon-box');if(panel)panel.style.maxWidth='1180px';let html=psyV10WheelHtml()+`<h3 class="psy-v10-section-title">🏆 CONQUISTAS ÚNICAS</h3>`;html+=PSY_ACHIEVEMENTS.map(a=>{const v=psyAchievementValue(a),done=v>=a.goal,claimed=!!P.meta.achievements[a.id],pct=Math.min(100,v/a.goal*100);return `<div class="psy-system-card psy-ach ${done&&!claimed?'claimable':''} ${claimed?'claimed':''}"><b>${a.name}</b><div class="psy-desc">${a.desc}</div><div class="psy-progress"><i style="width:${pct}%"></i></div><div>${Math.min(v,a.goal)}/${a.goal}</div><div class="badge">💰 ${(a.gold||0).toLocaleString()} • 💎 ${a.diamonds||0}${a.egg?' • 🥚':''}</div><button ${!done||claimed?'disabled':''} onclick="psyClaimAchievement('${a.id}')">${claimed?'RESGATADO':done?'RESGATAR':'BLOQUEADO'}</button></div>`}).join('');html+=`<h3 class="psy-v10-section-title">♻ MISSÕES DE CAÇADA REPETÍVEIS — progresso nunca é perdido</h3>`;html+=psyV10RepeatList().map(r=>{const v=psyV10RepeatValue(r),completed=Math.floor(v/r.goal),claimed=Number(P.meta.repeatClaims[r.id]||0),available=Math.max(0,completed-claimed),rem=v%r.goal,pct=Math.min(100,rem/r.goal*100);return `<div class="psy-system-card psy-v10-repeat ${available?'claimable':''}"><b>${r.name}</b><div class="psy-desc">${r.desc}</div><div class="psy-progress"><i style="width:${pct}%"></i></div><div>${rem}/${r.goal} • ciclos concluídos ${completed}</div><div class="badge">💰 ${(r.gold||0).toLocaleString()}${r.diamonds?' • 💎 '+r.diamonds:''}${r.essence?' • '+r.essQty+'x '+r.essence:''}</div><button ${!available?'disabled':''} onclick="psyClaimRepeatV10('${r.id}')">${available?'RESGATAR x'+available:'CONTINUE CAÇANDO'}</button></div>`}).join('');el.innerHTML=html};
window.psyAchievementPulse=function(){const btn=document.querySelector('[onclick="openAchievements()"]');if(!btn)return;const m=psyV10RewardsEnsure(),one=PSY_ACHIEVEMENTS.some(a=>psyAchievementValue(a)>=a.goal&&!P.meta.achievements[a.id]),rep=psyV10RepeatList().some(r=>Math.floor(psyV10RepeatValue(r)/r.goal)>Number(m.repeatClaims[r.id]||0));btn.style.boxShadow=(one||rep||m.rouletteSpins>0)?'0 0 18px #00ff88':''};

/* ---------- Cards V10: one main Pokémon + auxiliary deck, 50 chapters x 10 stages ---------- */
const psyV10CardsEnsureBase=psyCardsEnsure;
psyCardsEnsure=function(){const preStage=Number(P.cardGame?.stage||1),preBest=Number(P.cardGame?.best||0),c=psyV10CardsEnsureBase();c.stage=Math.max(1,Math.min(500,preStage));c.best=Math.max(Number(c.best||0),Math.min(500,preBest));c.chapterView=Math.max(1,Math.min(50,Number(c.chapterView||Math.ceil(c.stage/10))));const cards=Object.values(c.collection);if(!c.heroId||!c.collection[String(c.heroId)])c.heroId=(cards.sort((a,b)=>psyCardPower(b)-psyCardPower(a))[0]?.id||null);if(c.heroId)c.deck=c.deck.filter(k=>k!==`p:${c.heroId}`);return c};
window.psySetCardHeroV10=function(id){const c=psyCardsEnsure();id=Number(id);if(!c.collection[String(id)])return;c.heroId=id;c.deck=c.deck.filter(k=>k!==`p:${id}`);autoSave();renderCardTab('collection');notif(`⭐ ${getPokeName(id)} é seu Pokémon principal nas missões de Cards.`,2600)};
const psyV10ToggleDeckBase=window.cgToggleDeck;window.cgToggleDeck=function(key){const c=psyCardsEnsure();key=String(key);if(!key.includes(':'))key=`p:${key}`;if(key===`p:${c.heroId}`)return notif('Esse é seu Pokémon principal. Escolha outras cartas como auxiliares.');return psyV10ToggleDeckBase.apply(this,arguments)};
window.cgAutoDeck=function(){const c=psyCardsEnsure(),p=Object.values(c.collection).filter(x=>Number(x.id)!==Number(c.heroId)).sort((a,b)=>psyCardPower(b)-psyCardPower(a)).slice(0,14).map(x=>`p:${x.id}`),e=Object.keys(c.effectCollection).slice(0,6).map(x=>`e:${x}`);c.deck=[...p,...e].slice(0,20);autoSave();renderCardTab('collection')};
psyCollectionCardHtml=function(x){const c=psyCardsEnsure(),selected=c.deck.includes(x.key),col=CG_TIER_COLOR[x.tier]||'#aaa';if(x.kind==='effect')return `<div class="psy-v10-card-wrap ${selected?'selected':''}" style="--tier:${col}"><span class="tier">${x.tier}</span><div class="effect-ico">${x.icon}</div><b>${x.name}</b><small>${x.desc}</small><em>cópias ${x.copies||1}</em><div class="psy-v10-card-actions" style="grid-template-columns:1fr"><button class="psy-v10-deck-btn" onclick="cgToggleDeck('${x.key}')">${selected?'REMOVER':'+ DECK'}</button></div></div>`;const hero=Number(c.heroId)===Number(x.id);return `<div class="psy-v10-card-wrap ${selected?'selected':''} ${hero?'hero':''}" style="--tier:${col}"><span class="tier">${x.tier}</span><span class="stars">${'★'.repeat(x.stars||1)}${'☆'.repeat(5-(x.stars||1))}</span>${psyCardSprite(x.id)}<b>${getPokeName(x.id)}</b><small>${psyV10CanonicalTypeForId(x.id)} • Lv.${x.level||1} • PWR ${psyCardPower(x).toLocaleString()}</small><em>cópias ${x.copies||1}</em><div class="psy-v10-card-actions"><button class="psy-v10-main-btn" onclick="psySetCardHeroV10(${x.id})">${hero?'⭐ PRINCIPAL':'TORNAR PRINCIPAL'}</button><button class="psy-v10-deck-btn" ${hero?'disabled':''} onclick="cgToggleDeck('${x.key}')">${selected?'REMOVER':'AUXILIAR'}</button></div></div>`};
const psyV10RenderCollectionBase=window.cgRenderCollection;window.cgRenderCollection=function(c){psyV10RenderCollectionBase(c);const cg=psyCardsEnsure(),hero=cg.heroId?cg.collection[String(cg.heroId)]:null;if(hero){const head=c.querySelector('.psy-deck-head');if(head){const h=document.createElement('div');h.className='psy-v10-hero';h.innerHTML=`${psyCardSprite(hero.id)}<div><b>⭐ PRINCIPAL: ${getPokeName(hero.id)}</b><small>${psyV10CanonicalTypeForId(hero.id)} • ${psyCardTier(hero)} • ${hero.stars}★ • PWR ${psyCardPower(hero).toLocaleString()}</small><small>As 20 cartas do Deck são auxiliares. Ataques auxiliares usam suas tipagens; o inimigo também bate contra a tipagem do seu principal.</small></div>`;head.after(h)}}};

const PSY_V10_STAGE_TYPES=['Normal','Fogo','Agua','Eletrico','Planta','Gelo','Lutador','Veneno','Terra','Voador','Psiquico','Inseto','Pedra','Fantasma','Dragao','Noturno','Metal','Fada'];
function psyV10StageType(stage){return PSY_V10_STAGE_TYPES[(stage-1)%PSY_V10_STAGE_TYPES.length]}
function psyV10StageTier(stage){return stage>=481?'UR++':stage>=441?'UR+':stage>=391?'UR':stage>=331?'SSS':stage>=261?'SS':stage>=191?'S':stage>=131?'A':stage>=81?'B':stage>=41?'C':'D'}
function psyV10StageBoss(stage){return stage%10===0}
const psyV10TypePoolCache={};function psyV10PokemonForType(type){if(!psyV10TypePoolCache[type])psyV10TypePoolCache[type]=Object.keys(ALL_POKE_NAMES||{}).map(Number).filter(id=>id&&id!==54&&psyV10CanonicalTypeForId(id)===type);const a=psyV10TypePoolCache[type];return a?.length?a[Math.floor(Math.random()*a.length)]:psyRollPokemonId()}

/* ---------- Global Psyduck XP outside Survivor ----------
   Normal WORLD, battle, dungeon and AFK rewards still go to the active
   Pokémon as before. This companion channel also grants the same XP to an
   owned Psyduck in the box, so Psyduck does not lose global progression just
   because another Pokémon is currently leading the team. */
function psyFindGlobalPsyduck(){
  const pool=[...(P?.team||[]),...(P?.box||[])];
  return pool.find(p=>Number(p?.id)===54&&p?.psyduckChosen)||pool.find(p=>Number(p?.id)===54)||null;
}
function psyAwardGlobalPsyduckXp(amount,source='normal'){
  const active=P?.team?.[0],p=psyFindGlobalPsyduck();
  if(!p||p===active)return 0;
  const xp=Math.max(0,Math.floor(Number(amount)||0));if(!xp)return 0;
  p.level=Math.max(1,Number(p.level||1));p.exp=Math.max(0,Number(p.exp||0));p.maxExp=Math.max(100,Number(p.maxExp||100));
  const cap=Math.max(1,Number(P.levelCap||100));p.exp+=xp;let ups=0;
  while(p.exp>=p.maxExp&&p.level<cap){p.exp-=p.maxExp;p.level++;p.maxExp=Math.floor(p.maxExp*1.3);ups++;try{ensurePokeBase(p);p.baseMaxHp=(p.baseMaxHp||p.maxHp||50)+20;recalcPoke(p)}catch(_){p.maxHp=(p.maxHp||50)+20}p.hp=p.maxHp}
  if(p.level>=cap)p.exp=Math.min(p.exp,Math.max(0,p.maxExp-1));
  P.meta=P.meta||{};P.meta.psyduckGlobalXp=Math.max(0,Number(P.meta.psyduckGlobalXp||0))+xp;P.meta.psyduckGlobalXpBySource=P.meta.psyduckGlobalXpBySource||{};P.meta.psyduckGlobalXpBySource[source]=(Number(P.meta.psyduckGlobalXpBySource[source]||0)+xp);
  if(ups){notif(`🦆 Psyduck recebeu XP global e subiu ${ups>1?ups+' níveis':'de nível'}!`,3000);try{renderTeam()}catch(_){} }
  return xp;
}
window.psyAwardGlobalPsyduckXp=psyAwardGlobalPsyduckXp;
window.psyCardChapterV10=function(ch){const c=psyCardsEnsure();c.chapterView=Math.max(1,Math.min(50,Number(ch)||1));renderCardTab('battle')};
window.cgRenderBattleMenu=function(c){const cg=psyCardsEnsure(),currentChapter=Math.ceil((cg.stage||1)/10),unlockedChapter=Math.min(50,Math.max(1,Math.ceil((Math.max(0,cg.best)+1)/10))),view=Math.max(1,Math.min(50,cg.chapterView||currentChapter)),start=(view-1)*10+1,end=view*10;c.innerHTML=`<div class="psy-card-campaign"><div class="campaign-hero"><h2 class="psy-title-glint">⚔ CAMPANHA — 50 CAPÍTULOS</h2><p><b>500 fases</b> • 10 fases por capítulo • Boss na fase 10 de cada capítulo • cada fase muda de elemento</p><b>Atual: ${cg.stage}/500 • Melhor: ${cg.best}/500 • Capítulo ${view}/50</b></div><div class="psy-v10-chapters">${Array.from({length:50},(_,i)=>i+1).map(ch=>`<button class="${ch===view?'current':''}" ${ch>unlockedChapter?'disabled':''} onclick="psyCardChapterV10(${ch})">C${ch}</button>`).join('')}</div><div class="psy-stage-grid">${Array.from({length:10},(_,i)=>start+i).map(n=>{const open=n<=Math.max(1,cg.best+1),boss=psyV10StageBoss(n),type=psyV10StageType(n);return `<button class="psy-stage ${boss?'boss':''} ${n===cg.stage?'current':''}" ${!open?'disabled':''} onclick="P.cardGame.stage=${n};P.cardGame.chapterView=${view};cgStartStage()"><b>${boss?'👑 BOSS ':'FASE '}${n}</b><span>${psyV10StageTier(n)}</span><i class="psy-v10-stage-type">${type}</i><small>${open?'JOGAR':'🔒'}</small></button>`}).join('')}</div><div class="campaign-rules">Escolha 1 Pokémon principal + até 20 cartas auxiliares. Mão aleatória de 5. Explore fraquezas/resistências: a tipagem da carta auxiliar define o ataque e a tipagem do principal define sua defesa.</div></div>`};
function psyV10HeroCard(){const c=psyCardsEnsure();return c.heroId?c.collection[String(c.heroId)]:null}
window.cgStartStage=function(){const cg=psyCardsEnsure(),hero=psyV10HeroCard();if(!hero)return notif('Escolha um Pokémon PRINCIPAL na Coleção.');if(cg.deck.length<5)return notif('Monte um deck auxiliar com pelo menos 5 cartas.');const stage=cg.stage||1,tier=psyV10StageTier(stage),boss=psyV10StageBoss(stage),enemyType=psyV10StageType(stage),enemyId=psyV10PokemonForType(enemyType),rank=CG_TIER_RANK[tier]||1,chapter=Math.ceil(stage/10);const enemyHp=Math.floor((850+stage*62+chapter*150)*(1+rank*.11)*(boss?1.55:1)),deck=cg.deck.map(String),heroPower=psyCardPower(hero),aux=deck.map(psyDeckItem).filter(x=>x?.kind==='pokemon'),avg=aux.length?aux.reduce((s,x)=>s+psyCardPower(x),0)/aux.length:0,playerHp=Math.floor(1500+heroPower*2.7+avg*.55);window.cgBattleState={stage,tier,boss,chapter,enemyId,enemyType,enemyHp,enemyMax:enemyHp,heroId:hero.id,heroType:psyV10CanonicalTypeForId(hero.id),heroPower,playerHp,playerMax:playerHp,energy:4,maxEnergy:7,turn:1,deck,hand:[],selectedKey:null,lastUsedKey:null,shield:0,poisonTurns:0,poisonPct:0,weakenTurns:0,weaken:0,focus:0,stun:false};psyDrawHand(cgBattleState);cgDrawBattle()};
function psyV10Eff(atk,def){try{return getEffectiveness(atk,def)}catch(e){return 1}}
psyBattleHandHtml=function(key,s){const x=psyDeckItem(key);if(!x)return '';const col=CG_TIER_COLOR[x.tier]||'#aaa',sel=s.selectedKey===key;if(x.kind==='effect')return `<button class="psy-hand-card effect ${sel?'selected':''}" style="--tier:${col}" onclick="psySelectHandCard('${key}')"><span class="tier">${x.tier}</span><div class="effect-ico">${x.icon}</div><b>${x.name}</b><small>${x.desc}</small><em>⚡${x.cost}</em></button>`;const cost=psyPokemonCost(x),type=psyV10CanonicalTypeForId(x.id),eff=psyV10Eff(type,s.enemyType);return `<button class="psy-hand-card ${sel?'selected':''}" style="--tier:${col}" onclick="psySelectHandCard('${key}')"><span class="tier">${x.tier}</span><span class="stars">${'★'.repeat(x.stars||1)}</span>${psyCardSprite(x.id)}<b>Auxílio: ${getPokeName(x.id)}</b><span class="assist-type">${type}</span><small>PWR ${psyCardPower(x).toLocaleString()}</small><span class="psy-effectiveness">${eff>=2?'🔥 Super efetivo':eff<1?'🛡 Resistido':'• Neutro'}</span><em>⚡${cost}</em></button>`};
window.cgDrawBattle=function(){const s=window.cgBattleState,c=document.getElementById('cg-content');if(!s||!c)return;const ep=Math.max(0,s.enemyHp/s.enemyMax*100),pp=Math.max(0,s.playerHp/s.playerMax*100);c.innerHTML=`<div class="psy-card-arena"><div class="psy-arena-top"><button onclick="window.cgBattleState=null;renderCardTab('battle')">← CAPÍTULO</button><b>Fase ${s.stage}/500 • Turno ${s.turn} • ⚡ ${s.energy}/${s.maxEnergy}</b><span>${s.boss?'👑 BOSS • ':''}${s.tier} • ${s.enemyType}</span></div><div class="psy-arena-enemy"><div class="psy-hpbox"><b>${getPokeName(s.enemyId)} [${s.tier}]</b><div><i style="width:${ep}%"></i></div><small>${Math.max(0,s.enemyHp).toLocaleString()} / ${s.enemyMax.toLocaleString()} • ${s.enemyType}</small></div>${psyCardSprite(s.enemyId)}</div><div class="psy-v10-hero-battle">${psyCardSprite(s.heroId)}<div class="psy-hpbox"><b>${getPokeName(s.heroId)} • PRINCIPAL</b><div><i style="width:${pp}%"></i></div><small>${Math.max(0,s.playerHp).toLocaleString()} / ${s.playerMax.toLocaleString()} • ${s.heroType}</small></div><div class="psy-status-line">${s.shield?'🛡️ Escudo '+Math.round(s.shield*100)+'%':''} ${s.focus?'🎯 Foco +'+Math.round(s.focus*100)+'%':''} ${s.poisonTurns?'☠️ Veneno '+s.poisonTurns+'t':''}</div></div><div class="psy-hand-title">CARTAS AUXILIARES — escolha 1 das 5</div><div class="psy-card-hand">${s.hand.map(k=>psyBattleHandHtml(k,s)).join('')}</div><button class="psy-use-card" onclick="psyUseSelectedCard()" ${!s.selectedKey?'disabled':''}>USAR CARTA SELECIONADA</button></div>`};
window.psyUseSelectedCard=function(){const s=window.cgBattleState;if(!s||!s.selectedKey)return;const key=s.selectedKey,x=psyDeckItem(key);if(!x)return;const cost=x.kind==='effect'?Number(x.cost||0):psyPokemonCost(x);if(cost>s.energy)return notif(`⚡ Precisa ${cost} de Energia.`);s.energy-=cost;s.lastUsedKey=key;
  if(x.kind==='pokemon'){const at=psyV10CanonicalTypeForId(x.id),eff=psyV10Eff(at,s.enemyType),sameHero=String(s.heroType).toLowerCase().includes(at.toLowerCase())?1.12:1;let dmg=(s.heroPower*.42+psyCardPower(x)*.92)*(1.02+Math.random()*.18)*(1+(s.focus||0))*sameHero*eff;s.focus=0;if(s.boss)dmg*=.94;s.enemyHp-=Math.floor(dmg);if(eff>=2)notif(`🔥 ${at} foi super efetivo em ${s.enemyType}!`,1300);psySfx?.('attack')}
  else{const d=PSY_EFFECT_CARDS[x.id];if(d.effect==='energy')s.energy=Math.min(s.maxEnergy,s.energy+d.value);if(d.effect==='heal')s.playerHp=Math.min(s.playerMax,s.playerHp+Math.floor(s.playerMax*d.value));if(d.effect==='shield')s.shield=Math.max(s.shield,d.value);if(d.effect==='poison'){s.poisonTurns=3;s.poisonPct=d.value}if(d.effect==='weaken'){s.weakenTurns=2;s.weaken=d.value}if(d.effect==='focus')s.focus=d.value;if(d.effect==='stun')s.stun=Math.random()<d.value;if(d.effect==='drain'){const dmg=Math.floor(s.enemyMax*d.value);s.enemyHp-=dmg;s.playerHp=Math.min(s.playerMax,s.playerHp+Math.floor(dmg*.5))}psySfx?.('buff')}
  if(s.enemyHp<=0)return psyCardStageWin();if(s.poisonTurns>0){s.enemyHp-=Math.floor(s.enemyMax*s.poisonPct);s.poisonTurns--;if(s.enemyHp<=0)return psyCardStageWin()}
  if(!s.stun){const chapter=Math.ceil(s.stage/10),rank=CG_TIER_RANK[s.tier]||1,eff=psyV10Eff(s.enemyType,s.heroType);let dmg=Math.floor((38+s.stage*.34+chapter*1.8)*(1+rank*.07)*(s.boss?1.28:1)*Math.max(.5,eff));if(s.weakenTurns>0){dmg=Math.floor(dmg*(1-s.weaken));s.weakenTurns--}if(s.shield){dmg=Math.floor(dmg*(1-s.shield));s.shield=0}s.playerHp=Math.max(0,s.playerHp-Math.max(5,dmg));if(eff>=2)notif(`⚠ ${s.enemyType} é forte contra seu principal!`,1300)}else{s.stun=false;notif('⏳ Inimigo perdeu o contra-ataque!',1500)}
  if(s.playerHp<=0)return psyCardStageLose();s.turn++;s.energy=Math.min(s.maxEnergy,s.energy+2);psyDrawHand(s);cgDrawBattle();
};
psyCardStageWin=function(){const s=window.cgBattleState,cg=psyCardsEnsure(),first=s.stage>cg.best;cg.best=Math.max(cg.best,s.stage);if(first)cg.skillPoints=(cg.skillPoints||0)+1;if(s.stage<500)cg.stage=s.stage+1;cg.chapterView=Math.ceil(cg.stage/10);const gold=Math.floor((2200+s.stage*165)*(s.boss?1.7:1)),dia=s.boss?Math.min(6,1+Math.floor(s.stage/100)):0;P.gold+=gold;P.diamonds+=dia;psyV10RewardsEnsure().cardWins++;if(s.boss&&Math.random()<.045){cg.packs.ss++;notif('🌐 DROP GLOBAL: Pack SS!',4200)}window.cgBattleState=null;autoSave();updateHUD();notif(`🏆 Fase ${s.stage}/500! +${gold.toLocaleString()} Gold${dia?' +'+dia+' 💎':''}`,3200);renderCardTab('battle')};window.cgWinStage=psyCardStageWin;
function psyInstallCardTabsV10(){const s=document.getElementById('screen-card-mode');if(!s)return;const bar=s.querySelector('.cardgame-tabs');if(!bar)return;bar.innerHTML=`<button onclick="renderCardTab('collection')">📚 PRINCIPAL / DECK</button><button onclick="renderCardTab('gacha')">✨ GACHA / PACKS</button><button onclick="renderCardTab('history')">📜 HISTÓRICO</button><button onclick="renderCardTab('skills')">🌟 HABILIDADES</button><button onclick="renderCardTab('battle')">⚔ 500 FASES</button>`}
setInterval(()=>{if(!document.hidden)psyInstallCardTabsV10()},3000);setTimeout(psyInstallCardTabsV10,400);

/* ---------- Psyduck Dungeon V10: visible, farmable, strongest endgame Pokémon ---------- */
function psyV10PsyReq(stage){return {trainer:Math.max(1,stage*5),gold:stage*35000,captures:Math.max(0,(stage-1)*4),cards:Math.max(0,(stage-1)*3)}}
function psyV10PsyCan(stage){psyEnsurePsyduck();const r=psyV10PsyReq(stage),cards=Object.keys(P.cardGame?.collection||{}).length,caps=Number(P.meta?.captures||0),prog=Number(P.psyduck?.trial||0);return stage<=Math.min(9,prog+1)&&(P.trainerLevel||1)>=r.trainer&&P.gold>=r.gold&&caps>=r.captures&&cards>=r.cards}
window.renderPsyduckDungeon5=function(){const b=document.getElementById('psyduck5-body');if(!b)return;psyEnsurePsyduck();const prog=Number(P.psyduck.trial||0),chosen=[...(P.team||[]),...(P.box||[])].find(x=>x.id===54&&x.psyduckChosen);b.innerHTML=`<div class="psyduck-hero"><img src="${getRealSprite({id:54,shiny:!!chosen?.shiny,isMega:!!chosen?.isMega})}"><div><h2 class="psy-title-glint">🦆 PSYDUCK — A PROVAÇÃO SUPREMA</h2><div class="psy-desc">Psyduck continua exclusivo desta Dungeon. Conclua as 9 provas para conquistá-lo. Depois, Ascensões Lv100 transformam-no no Pokémon de maior teto de poder do PSYWORLD.</div><div>Provas: <b>${prog}/9</b> • PsyStone: <b>${P.inventory['PsyStone']||0}</b>${chosen?` • Ascensões: <b>${chosen.resets||0}/50</b>`:''}</div><div class="psyduck-progress"><i style="width:${Math.min(100,prog/9*100)}%"></i></div></div></div><div class="psyduck-v10-milestones"><div><b>0</b>Lv90 • SS</div><div><b>10</b>SSS</div><div><b>20</b>UR + SHINY</div><div><b>50</b>UR++ • MEGA • PODER MÁXIMO</div></div><div class="psyduck-stage-grid">${Array.from({length:9},(_,i)=>{const st=i+1,r=psyV10PsyReq(st),done=prog>=st,open=psyV10PsyCan(st);return `<div class="psyduck-stage ${done?'done':open?'open':'locked'}"><b>Prova ${st} • Lv${st*10}</b><div class="psy-desc">T.Lv ${r.trainer}<br>${r.gold.toLocaleString()} Gold<br>${r.captures} capturas<br>${r.cards} Cards</div><button ${!open&&!done?'disabled':''} onclick="psyStartPsyduckTrial(${st})">${done?'REPETIR':open?'DESAFIAR':'🔒'}</button></div>`}).join('')}</div>${chosen?`<div class="psy-system-card" style="margin-top:10px"><b>ASCENSÃO DO PSYDUCK</b><div class="psy-desc">Seu Psyduck precisa chegar ao Lv100 para cada Ascensão. PsyStone é obtida nas Provações. Cada Ascensão aumenta o poder permanente e libera formas nos marcos 10/20/50.</div><button class="psyduck-v10-ascend" onclick="psyAscendPsyduck5()">ASCENDER PSYDUCK • RESET ${chosen.resets||0} → ${(chosen.resets||0)+1}</button></div>`:''}`};
window.psyStartPsyduckTrial=function(stage){stage=Number(stage);psyEnsurePsyduck();const prog=Number(P.psyduck.trial||0);if(stage>prog+1||stage<1||stage>9)return notif('🔒 Complete a prova anterior.');const r=psyV10PsyReq(stage);if((P.trainerLevel||1)<r.trainer||P.gold<r.gold||Number(P.meta?.captures||0)<r.captures||Object.keys(P.cardGame?.collection||{}).length<r.cards)return notif(`🔒 Requisitos: T.Lv${r.trainer}, ${r.gold.toLocaleString()}G, ${r.captures} capturas, ${r.cards} Cards.`);const replay=stage<=prog,Pcost=replay?Math.floor(r.gold*.25):r.gold;if(P.gold<Pcost)return notif('Gold insuficiente.');P.gold-=Pcost;document.getElementById('screen-psyduck5').style.display='none';const tier=stage>=9?'SS':stage>=7?'S':stage>=5?'A':stage>=3?'B':'C',rar=psyMinimumRarityForTier(tier),w={id:54,name:`Psyduck da Provação ${stage}`,level:stage*10,rarity:rar,shiny:false,isMega:false,psyduckDungeon:true,psyStage:stage,psyReplay:replay};w.maxHp=Math.floor((2200+stage*2100)*rar.mult*(replay?1.08:1));w.hp=w.maxHp;startBattle(w)};
window.psyPsyduckWin=function(w){if(!w?.psyduckDungeon)return;psyEnsurePsyduck();const old=Number(P.psyduck.trial||0),st=Number(w.psyStage||0),first=st>old;if(first){P.psyduck.trial=st;P.inventory['PsyStone']=(P.inventory['PsyStone']||0)+1;notif(`🟡 Prova ${st} concluída: PsyStone +1!`,3000)}else if(Math.random()<.30){P.inventory['PsyStone']=(P.inventory['PsyStone']||0)+1;notif('🟡 Replay: PsyStone +1!',2500)}if(st===9&&![...(P.team||[]),...(P.box||[])].some(p=>p.id===54&&p.psyduckChosen)){const p=createCapturedPoke(54,psyMinimumRarityForTier('SS'),false,false,false);p.level=90;p.exp=0;p.maxExp=Math.max(100,p.maxExp||100);p.resets=0;p.psyduckChosen=true;p.psyLegacy=true;p.tier='SS';recalcPoke(p);p.hp=p.maxHp;P.box.push(p);notif('🦆 PSYDUCK SUPREMO CONQUISTADO! Leve-o ao Lv100 para iniciar as Ascensões.',5200)}autoSave();renderTeam()};
window.psyAscendPsyduck5=function(){return W.psyCleanAscend?.()};
const psyV10RecalcPsy=window.recalcPoke;window.recalcPoke=function(p){const r=psyV10RecalcPsy.apply(this,arguments);if(p?.id===54&&p?.psyduckChosen){const resets=Number(p.resets||0),m=(1.25+resets*.025)*(p.shiny?1.12:1)*(p.psyMega?1.65:1);p.baseMaxHp=Math.floor((p.baseMaxHp||p.maxHp||1)*m);p.baseMaxAtk=Math.floor((p.baseMaxAtk||p.atk||1)*m);p.maxHp=Math.floor((p.maxHp||1)*m);p.atk=Math.floor((p.atk||1)*m);p.def=Math.floor((p.def||1)*m);p.hp=Math.min(p.maxHp,Math.max(1,p.hp||p.maxHp))}return r};
const psyV10ResetBase=window.resetPokemon;window.resetPokemon=function(idx,isBox){const p=isBox?P.box?.[idx]:P.team?.[idx];if(p?.id===54&&p?.psyduckChosen)return psyAscendPsyduck5();return psyV10ResetBase.apply(this,arguments)};
function psyV10InstallPsyduckShortcut(){const grid=document.querySelector('#menu .psy-main-grid');if(!grid||grid.querySelector('[data-psyduck-v10]'))return;const b=document.createElement('button');b.dataset.psyduckV10='1';b.innerHTML='🦆 PSYDUCK SUPREMO';b.style.background='linear-gradient(90deg,#a16207,#7c3aed)';b.style.color='#fff';b.onclick=()=>{document.getElementById('menu').style.display='none';openPsyduckDungeon5()};grid.appendChild(b)}
setInterval(()=>{if(!document.hidden)psyV10InstallPsyduckShortcut()},3000);setTimeout(psyV10InstallPsyduckShortcut,600);

